(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-376":{scenario:{legacy:"D"},learning:{summary:{vi:"Chuyên viên Quảng cáo hiệu suất đa kênh lập kế hoạch, triển khai và tối ưu chiến dịch quảng cáo trả phí trên công cụ tìm kiếm, mạng xã hội và nền tảng video ngắn để đạt mục tiêu chuyển đổi đo được (đơn hàng, khách hàng tiềm năng, lượt cài đặt) với chi phí hợp lý. Nghề đòi hỏi đo lường chính xác, tư duy thử nghiệm, phân bổ ngân sách theo hiệu quả thật và tuân thủ quy định quảng cáo, dữ liệu cá nhân.",en:"A Performance Marketing Specialist plans, launches and optimizes paid campaigns across search, social and short-video platforms to reach measurable conversion goals (orders, leads, installs) at an efficient cost. The role requires accurate measurement, an experimentation mindset, budget allocation by true efficiency and compliance with advertising and personal data rules."},responsibilities:{vi:["Lập kế hoạch kênh, ngân sách và mục tiêu CPA, ROAS theo từng giai đoạn của phễu chuyển đổi.","Thiết lập cấu trúc chiến dịch, nhóm quảng cáo, đối tượng và chiến lược đặt giá thầu.","Cài đặt và kiểm tra đo lường: pixel, API chuyển đổi phía máy chủ, UTM, sự kiện chuyển đổi.","Thử nghiệm A/B mẫu quảng cáo, trang đích và đối tượng; tối ưu hằng ngày theo dữ liệu.","Báo cáo hiệu quả, phân bổ lại ngân sách giữa các kênh và đề xuất kiểm định tăng trưởng thực."],en:["Plan channels, budgets and CPA and ROAS targets for each stage of the conversion funnel.","Set up campaign structure, ad groups, audiences and bidding strategies.","Implement and audit measurement: pixels, server-side conversion APIs, UTMs and conversion events.","A/B test creatives, landing pages and audiences; optimize daily from data.","Report performance, reallocate budget across channels and propose incrementality tests."]},competencies:[{name:{vi:"Đo lường & phân bổ chuyển đổi",en:"Measurement & attribution"},desc:{vi:"Hiểu các mô hình phân bổ, giới hạn của dữ liệu nền tảng và cách kiểm chứng bằng nhóm đối chứng.",en:"Understand attribution models, the limits of platform data and validation with control groups."}},{name:{vi:"Tối ưu đấu giá & ngân sách",en:"Auction & budget optimization"},desc:{vi:"Chọn chiến lược giá thầu, điều chỉnh ngân sách theo hiệu quả biên thay vì hiệu quả trung bình.",en:"Choose bidding strategies and shift budget by marginal rather than average efficiency."}},{name:{vi:"Tư duy thử nghiệm",en:"Experimentation"},desc:{vi:"Đặt giả thuyết, thiết kế A/B đủ cỡ mẫu và chỉ kết luận khi có ý nghĩa thống kê.",en:"Form hypotheses, design properly sized A/B tests and conclude only on statistical significance."}},{name:{vi:"Phối hợp sáng tạo",en:"Creative collaboration"},desc:{vi:"Đưa dữ liệu vào brief sáng tạo, phát hiện mẫu quảng cáo mỏi và đề xuất góc tiếp cận mới.",en:"Feed data into creative briefs, spot creative fatigue and suggest new angles."}},{name:{vi:"Tuân thủ quảng cáo",en:"Advertising compliance"},desc:{vi:"Chỉ dùng thông điệp có bằng chứng, tôn trọng chính sách nền tảng và quyền riêng tư người dùng.",en:"Use only substantiated claims and respect platform policies and user privacy."}}],knowledge:{vi:["Chỉ số hiệu suất: CPM, CPC, CTR, CVR, CPA, ROAS, MER và giá trị vòng đời khách hàng.","Cơ chế đấu giá quảng cáo, điểm chất lượng, mức độ liên quan và các chiến lược giá thầu tự động.","Mô hình phân bổ (lượt nhấp cuối, theo dữ liệu), kiểm định tăng trưởng thực (lift test, holdout).","Luật Quảng cáo năm 2012 và các văn bản sửa đổi, hướng dẫn; chính sách quảng cáo của từng nền tảng.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân khi theo dõi chuyển đổi và tiếp thị lại."],en:["Performance metrics: CPM, CPC, CTR, CVR, CPA, ROAS, MER and customer lifetime value.","Ad auction mechanics, quality and relevance scores and automated bidding strategies.","Attribution models (last click, data-driven) and incrementality testing (lift tests, holdouts).","The 2012 Advertising Law with its amendments and guidance; each platform's advertising policies.","Decree 13/2023/ND-CP on personal data protection for conversion tracking and retargeting."]},tools:["Trình quản lý quảng cáo tìm kiếm","Trình quản lý quảng cáo mạng xã hội","Công cụ phân tích web (GA4)","Tag manager / server-side tracking","Looker Studio / BI","Microsoft Excel"],kpis:{vi:["CPA hoặc ROAS so với mục tiêu đã duyệt theo từng kênh.","Tỷ lệ chuyển đổi trang đích và tỷ lệ nhấp quảng cáo.","Mức tăng trưởng thực (incremental) đo bằng nhóm đối chứng.","Mức độ chính xác của dữ liệu chuyển đổi so với hệ thống đơn hàng."],en:["CPA or ROAS versus the approved target per channel.","Landing page conversion rate and ad click-through rate.","True incremental lift measured with control groups.","Accuracy of conversion data versus the order system."]},day:[{time:"08:30",vi:"Kiểm tra chi tiêu, CPA, ROAS hôm qua và cảnh báo bất thường trên các nền tảng.",en:"Check yesterday's spend, CPA, ROAS and anomaly alerts across platforms."},{time:"10:00",vi:"Đối chiếu số chuyển đổi nền tảng với hệ thống đơn hàng, sửa lỗi gắn thẻ.",en:"Reconcile platform conversions with the order system and fix tagging errors."},{time:"13:30",vi:"Thiết kế thử nghiệm A/B mẫu quảng cáo mới cùng đội sáng tạo.",en:"Design an A/B test for new creatives with the creative team."},{time:"15:30",vi:"Phân bổ lại ngân sách giữa tìm kiếm và mạng xã hội theo hiệu quả biên.",en:"Reallocate budget between search and social by marginal efficiency."},{time:"17:00",vi:"Gửi báo cáo ngày, ghi nhận bài học thử nghiệm và kế hoạch ngày mai.",en:"Send the daily report, log test learnings and tomorrow's plan."}],mistakes:{vi:["Tin hoàn toàn số chuyển đổi do nền tảng tự báo cáo mà không đối chiếu đơn hàng thật.","Kết luận thử nghiệm A/B quá sớm khi chưa đủ cỡ mẫu và ý nghĩa thống kê.","Dùng thông điệp cam kết tuyệt đối không có bằng chứng để tăng tỷ lệ chuyển đổi."],en:["Trusting platform-reported conversions without reconciling real orders.","Calling A/B tests too early before reaching sample size and significance.","Using absolute, unsubstantiated promises to lift conversion rates."]},career:[{vi:"Nhân viên vận hành quảng cáo",en:"Ads Operations Executive"},{vi:"Chuyên viên Quảng cáo hiệu suất",en:"Performance Marketing Specialist"},{vi:"Trưởng nhóm Performance Marketing",en:"Performance Marketing Lead"},{vi:"Giám đốc Marketing tăng trưởng / Digital",en:"Head of Growth / Digital Marketing Director"}],glossary:[{term:"CPA",vi:"Chi phí cho mỗi chuyển đổi, bằng tổng chi tiêu chia số chuyển đổi.",en:"Cost per acquisition, total spend divided by conversions."},{term:"ROAS",vi:"Doanh thu quảng cáo trên chi phí quảng cáo, đo hiệu quả hoàn vốn của ngân sách.",en:"Return on ad spend, ad-attributed revenue divided by ad cost."},{term:"Attribution",vi:"Quy tắc gán công lao chuyển đổi cho các điểm chạm quảng cáo trên hành trình khách hàng.",en:"Rules that assign conversion credit to ad touchpoints along the customer journey."},{term:"Lift test",vi:"Thử nghiệm so sánh nhóm thấy quảng cáo và nhóm đối chứng để đo tăng trưởng thực.",en:"A test comparing an exposed group with a control group to measure true incremental impact."},{term:"Creative fatigue",vi:"Hiện tượng mẫu quảng cáo giảm hiệu quả do tần suất hiển thị cao với cùng đối tượng.",en:"Declining ad performance caused by high frequency to the same audience."}],quiz:[{q:{vi:"Kênh A chi 4000 có 80 chuyển đổi, kênh B chi 6000 có 20 chuyển đổi. CPA của kênh A là bao nhiêu?",en:"Channel A spends 4000 for 80 conversions, channel B spends 6000 for 20. What is channel A's CPA?"},options:{vi:["300","100","50","200"],en:["300","100","50","200"]},answer:2,explain:{vi:"CPA = 4000 / 80 = 50; kênh B có CPA 300 nên kém hiệu quả hơn nhiều.",en:"CPA = 4000 / 80 = 50; channel B's CPA is 300, far less efficient."}},{q:{vi:"Cách tin cậy nhất để biết quảng cáo có tạo doanh số tăng thêm thật hay không?",en:"What is the most reliable way to know whether ads create true incremental sales?"},options:{vi:["Thử nghiệm có nhóm đối chứng (holdout)","Xem ROAS do nền tảng báo cáo","So sánh với tháng trước","Hỏi ý kiến đội bán hàng"],en:["A test with a holdout control group","Platform-reported ROAS","Comparing with last month","Asking the sales team"]},answer:0,explain:{vi:"Nhóm đối chứng loại trừ doanh số tự nhiên, cho thấy phần tăng thêm do quảng cáo tạo ra.",en:"A control group removes organic sales and reveals the increment caused by ads."}},{q:{vi:"Thử nghiệm A/B mới chạy 2 ngày, mẫu B đang cao hơn 15% nhưng chưa có ý nghĩa thống kê. Nên làm gì?",en:"An A/B test has run 2 days; variant B leads by 15% but is not significant. What should you do?"},options:{vi:["Dừng ngay và chọn B","Tăng gấp đôi ngân sách cho B","Xóa thử nghiệm và làm lại từ đầu","Chạy tiếp đến cỡ mẫu đã định rồi mới kết luận"],en:["Stop now and pick B","Double B's budget","Delete the test and restart","Run to the planned sample size before concluding"]},answer:3,explain:{vi:"Kết luận sớm dễ chọn nhầm do dao động ngẫu nhiên; phải đạt cỡ mẫu và ý nghĩa đã định trước.",en:"Early calls often pick noise; reach the pre-set sample size and significance first."}},{q:{vi:"Khách hàng yêu cầu quảng cáo ghi “hiệu quả đảm bảo 100%” dù không có bằng chứng. Bạn xử lý thế nào?",en:"The client wants ads to say “100% guaranteed results” with no evidence. How do you handle it?"},options:{vi:["Chạy thử vài ngày rồi gỡ","Từ chối, đề xuất thông điệp có bằng chứng và thử nghiệm A/B có đo lường","Chỉ chạy trên một nền tảng","Thêm dấu sao chú thích thật nhỏ"],en:["Run it a few days then remove it","Decline, propose substantiated messaging and a measured A/B test","Run it on one platform only","Add a tiny asterisk note"]},answer:1,explain:{vi:"Thông điệp không có căn cứ vi phạm quy định quảng cáo và chính sách nền tảng; dùng bằng chứng và kiểm chứng bằng thử nghiệm.",en:"Unsubstantiated claims breach advertising rules and platform policies; use evidence and validate by testing."}}]}},"KK-377":{scenario:{company:"Greenhaus Living",supervisor:{name:"Khúc Thành Lộc",role:{vi:"Trưởng nhóm SEO",en:"SEO Lead"}},ref_code:"SEO-3390",title:{vi:"Giữ thứ hạng khi đổi URL. Đo CTR cho đúng.",en:"Keep rankings through a URL move. Measure CTR right."},brief:{vi:"Bạn rà soát kế hoạch chuyển URL và báo cáo tháng SEO-3390. Danh mục /sofa-go được đổi vĩnh viễn sang /sofa/go-tu-nhien, nhưng bản nháp cấu hình chuyển hướng 302. Dữ liệu 28 ngày của cụm từ khóa: “sofa gỗ” 20000 lượt hiển thị, 2000 lượt nhấp; “sofa gỗ sồi” 2000 hiển thị, 640 nhấp; “sofa gỗ phòng khách nhỏ” 3000 hiển thị, 360 nhấp. Sửa mã chuyển hướng và CTR của cụm, rồi lập báo cáo có căn cứ.",en:"You are reviewing URL migration plan and monthly report SEO-3390. Category /sofa-go moves permanently to /sofa/go-tu-nhien, but the draft configures a 302 redirect. 28-day data for the keyword cluster: “wooden sofa” 20000 impressions, 2000 clicks; “oak sofa” 2000 impressions, 640 clicks; “small living room wooden sofa” 3000 impressions, 360 clicks. Correct the redirect code and the cluster CTR, then write an evidence-based report."},reference_title:{vi:"Bảng ánh xạ URL & dữ liệu tìm kiếm đã duyệt · SEO-3390",en:"Approved URL map & search data · SEO-3390"},fields:[{id:"REDIRECT",label:{vi:"Mã chuyển hướng HTTP",en:"HTTP redirect code"},initial:"302",expected:"301",choices:["302","301","307"],reference:"Bảng ánh xạ URL cũ - mới",hint:{vi:"URL đổi vĩnh viễn cần mã chuyển hướng báo cho công cụ tìm kiếm thay URL cũ bằng URL mới và chuyển tín hiệu xếp hạng.",en:"A permanent URL change needs a redirect telling search engines to replace the old URL and pass ranking signals."}},{id:"CTR_PCT",label:{vi:"CTR của cụm từ khóa (%)",en:"Keyword cluster CTR (%)"},initial:"18",expected:"12",reference:"Báo cáo hiệu suất tìm kiếm 28 ngày",ref_value:{vi:"3 truy vấn: 20000/2000, 2000/640, 3000/360 (lượt hiển thị/lượt nhấp)",en:"3 queries: 20000/2000, 2000/640, 3000/360 (impressions/clicks)"},hint:{vi:"Không lấy trung bình cộng các CTR; truy vấn nhiều lượt hiển thị phải có trọng số lớn hơn.",en:"Do not average the CTRs; queries with more impressions must weigh more."}}],sop32:{vi:"CTR của cụm = tổng lượt nhấp / tổng lượt hiển thị của mọi truy vấn trong cụm x 100; không lấy trung bình cộng CTR từng truy vấn. URL đổi vĩnh viễn dùng chuyển hướng vĩnh viễn một bước.",en:"Cluster CTR = total clicks / total impressions of all queries in the cluster x 100; never average per-query CTRs. Permanently moved URLs use a single-hop permanent redirect."},context:{label:"SEARCH CONSOLE / SEO-3390",metrics:[{label:{vi:"Tổng lượt hiển thị",en:"Total impressions"},value:"25000"},{label:{vi:"Số truy vấn trong cụm",en:"Queries in cluster"},value:"3"},{label:{vi:"URL cần chuyển hướng",en:"URLs to redirect"},value:"/sofa-go -> /sofa/go-tu-nhien"}]},crisis:{vi:"Đối tác agency đề xuất: “Mua gói 300 backlink từ mạng blog vệ tinh và chèn đoạn chữ ẩn chứa từ khóa vào chân trang, hai tuần là lên top trước mùa sale, không ai phát hiện đâu.”",en:"The agency suggests: “Buy a package of 300 backlinks from a satellite blog network and add hidden keyword text to the footer, you will hit the top in two weeks before the sale season and nobody will notice.”"},options:{safe:{vi:"Từ chối vì vi phạm chính sách chống spam của công cụ tìm kiếm, báo trưởng nhóm SEO; đề xuất chuyển hướng 301 chuẩn, liên kết nội bộ, nâng cấp nội dung và PR số để có liên kết tự nhiên.",en:"Decline because it breaches search engine spam policies, inform the SEO Lead; propose clean 301s, internal links, better content and digital PR to earn natural links."},shortcut:{vi:"Mua gói backlink và chèn chữ ẩn trong thời gian ngắn rồi gỡ sau mùa sale.",en:"Buy the backlink package and add hidden text briefly, then remove it after the sale."},wait:{vi:"Không phản hồi agency và để nguyên kế hoạch chuyển URL như bản nháp.",en:"Ignore the agency and leave the URL plan as drafted."}},questions:{vi:["Vì sao phải dùng chuyển hướng 301 thay vì 302 cho URL danh mục? Hãy giải thích bằng tác động đến lập chỉ mục và tín hiệu xếp hạng.","Trình bày cách tính CTR 12% của cụm và rủi ro nếu dùng backlink mua hoặc văn bản ẩn để tăng thứ hạng."],en:["Why must the category URL use a 301 instead of a 302? Explain the effect on indexing and ranking signals.","Explain how you reached the 12% cluster CTR and the risks of bought backlinks or hidden text to boost rankings."]},hints:{vi:["So bảng ánh xạ URL với loại thay đổi: tạm thời hay vĩnh viễn, rồi chọn mã phản hồi HTTP phù hợp.","Theo SOP mục 3.2, cộng tất cả lượt nhấp và lượt hiển thị trước khi chia.","Đọc SOP mục 4.2: mọi đề xuất thao túng liên kết hoặc nội dung ẩn phải bị từ chối và báo cáo."],en:["Compare the URL map with the type of change, temporary or permanent, then pick the matching HTTP status.","Per SOP 3.2, sum all clicks and impressions before dividing.","Read SOP 4.2: any proposal to manipulate links or hide content must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên Tối ưu hóa công cụ tìm kiếm (SEO) giúp website được thu thập, lập chỉ mục và xếp hạng tốt cho các truy vấn có giá trị, từ đó tạo lưu lượng tự nhiên bền vững. Công việc gồm SEO kỹ thuật, nghiên cứu từ khóa theo ý định tìm kiếm, tối ưu nội dung, liên kết nội bộ, xây dựng uy tín và đo lường. Nghề đòi hỏi tư duy dữ liệu, hiểu cách công cụ tìm kiếm hoạt động và tuyệt đối tuân thủ chính sách chống spam.",en:"An SEO Specialist helps a website get crawled, indexed and ranked well for valuable queries, creating sustainable organic traffic. The work covers technical SEO, intent-based keyword research, content optimization, internal linking, authority building and measurement. The role requires data thinking, a clear understanding of how search engines work and strict compliance with spam policies."},responsibilities:{vi:["Kiểm tra SEO kỹ thuật: khả năng thu thập, lập chỉ mục, mã phản hồi, canonical, sơ đồ trang, tốc độ.","Nghiên cứu từ khóa, phân nhóm theo ý định tìm kiếm và lập bản đồ nội dung cho từng cụm.","Tối ưu tiêu đề, mô tả, cấu trúc nội dung, dữ liệu có cấu trúc và liên kết nội bộ.","Lập kế hoạch và kiểm soát chuyển đổi URL, di chuyển website để không mất thứ hạng.","Theo dõi thứ hạng, lượt hiển thị, CTR, lưu lượng và chuyển đổi tự nhiên; báo cáo định kỳ."],en:["Audit technical SEO: crawlability, indexing, status codes, canonicals, sitemaps and speed.","Research keywords, group them by search intent and map content to each cluster.","Optimize titles, descriptions, content structure, structured data and internal links.","Plan and control URL changes and site migrations without losing rankings.","Track rankings, impressions, CTR, organic traffic and conversions; report regularly."]},competencies:[{name:{vi:"SEO kỹ thuật",en:"Technical SEO"},desc:{vi:"Đọc nhật ký máy chủ, mã HTTP, robots.txt, canonical và chẩn đoán lỗi lập chỉ mục.",en:"Read server logs, HTTP codes, robots.txt and canonicals to diagnose indexing issues."}},{name:{vi:"Nghiên cứu ý định tìm kiếm",en:"Search intent research"},desc:{vi:"Phân biệt ý định thông tin, điều hướng, giao dịch để chọn loại trang phù hợp.",en:"Separate informational, navigational and transactional intent to choose the right page type."}},{name:{vi:"Tối ưu nội dung",en:"Content optimization"},desc:{vi:"Xây nội dung hữu ích, thể hiện kinh nghiệm và chuyên môn, cấu trúc rõ ràng cho người đọc.",en:"Build helpful content that shows experience and expertise with a clear structure for readers."}},{name:{vi:"Phân tích dữ liệu tìm kiếm",en:"Search data analysis"},desc:{vi:"Tính CTR, thị phần hiển thị, phân tách thương hiệu và phi thương hiệu đúng phương pháp.",en:"Compute CTR, impression share and brand versus non-brand splits with sound methods."}},{name:{vi:"SEO mũ trắng",en:"White-hat ethics"},desc:{vi:"Từ chối thao túng liên kết, nội dung ẩn, cloaking; xây uy tín bằng giá trị thật.",en:"Refuse link schemes, hidden content and cloaking; build authority through real value."}}],knowledge:{vi:["Mã phản hồi HTTP: 200, 301, 302, 307, 404, 410 và tác động đến lập chỉ mục.","Giao thức loại trừ robot (robots.txt, RFC 9309), thẻ meta robots, canonical và hreflang.","Chỉ số Core Web Vitals: LCP, INP, CLS và các ngưỡng tốt (LCP ≤ 2,5 giây, INP ≤ 200 ms, CLS ≤ 0,1).","Nguyên tắc nội dung hữu ích và khái niệm E-E-A-T trong hướng dẫn đánh giá chất lượng tìm kiếm.","Chính sách chống spam của công cụ tìm kiếm: mua bán liên kết, văn bản ẩn, nhồi từ khóa, cloaking.","Dữ liệu có cấu trúc theo từ vựng Schema.org cho sản phẩm, bài viết, câu hỏi thường gặp."],en:["HTTP status codes 200, 301, 302, 307, 404, 410 and their indexing impact.","Robots Exclusion Protocol (robots.txt, RFC 9309), meta robots, canonical and hreflang.","Core Web Vitals LCP, INP, CLS and good thresholds (LCP <= 2.5 s, INP <= 200 ms, CLS <= 0.1).","Helpful content principles and E-E-A-T in search quality rater guidelines.","Search engine spam policies: link schemes, hidden text, keyword stuffing, cloaking.","Structured data using the Schema.org vocabulary for products, articles and FAQs."]},tools:["Search Console","Công cụ thu thập dữ liệu website (crawler)","Công cụ phân tích web (GA4)","Công cụ nghiên cứu từ khóa & backlink","PageSpeed / Lighthouse","Trình phân tích log máy chủ"],kpis:{vi:["Lưu lượng và chuyển đổi tự nhiên từ truy vấn phi thương hiệu.","Số trang quan trọng được lập chỉ mục và tỷ lệ lỗi thu thập dữ liệu.","Thứ hạng và CTR của các cụm từ khóa mục tiêu.","Tỷ lệ URL cũ được chuyển hướng đúng sau mỗi lần thay đổi cấu trúc."],en:["Organic traffic and conversions from non-brand queries.","Indexed key pages and crawl error rate.","Rankings and CTR of target keyword clusters.","Share of old URLs correctly redirected after each structure change."]},day:[{time:"08:30",vi:"Xem cảnh báo lập chỉ mục, lỗi 404 mới và biến động thứ hạng qua đêm.",en:"Check indexing alerts, new 404 errors and overnight ranking changes."},{time:"10:00",vi:"Chạy crawler kiểm tra chuỗi chuyển hướng và canonical của danh mục vừa đổi URL.",en:"Run a crawler to check redirect chains and canonicals for the moved category."},{time:"13:30",vi:"Nghiên cứu cụm từ khóa mới và viết brief nội dung cho biên tập viên.",en:"Research a new keyword cluster and write a content brief for editors."},{time:"15:30",vi:"Họp đội phát triển về tốc độ trang và dữ liệu có cấu trúc sản phẩm.",en:"Meet developers on page speed and product structured data."},{time:"17:00",vi:"Cập nhật báo cáo CTR, lưu lượng tự nhiên và danh sách việc ưu tiên tuần.",en:"Update the CTR and organic traffic report and the weekly priority list."}],mistakes:{vi:["Dùng chuyển hướng 302 hoặc chuỗi nhiều bước khi URL đổi vĩnh viễn.","Lấy trung bình cộng CTR các truy vấn thay vì tổng lượt nhấp chia tổng lượt hiển thị.","Chặn trang bằng robots.txt rồi mong công cụ tìm kiếm đọc được thẻ noindex trên trang đó."],en:["Using a 302 or multi-hop chains when a URL changes permanently.","Averaging per-query CTRs instead of total clicks over total impressions.","Blocking a page in robots.txt and expecting search engines to read its noindex tag."]},career:[{vi:"Nhân viên SEO / biên tập nội dung SEO",en:"SEO Executive / SEO Content Editor"},{vi:"Chuyên viên SEO",en:"SEO Specialist"},{vi:"Trưởng nhóm SEO kỹ thuật & nội dung",en:"SEO Lead (Technical & Content)"},{vi:"Giám đốc tăng trưởng tự nhiên / Head of SEO",en:"Head of SEO / Organic Growth Director"}],glossary:[{term:"301 redirect",vi:"Chuyển hướng vĩnh viễn, báo công cụ tìm kiếm thay URL cũ bằng URL mới trong chỉ mục.",en:"A permanent redirect telling search engines to replace the old URL with the new one in the index."},{term:"Canonical",vi:"Thẻ chỉ ra phiên bản URL chính khi nhiều URL có nội dung trùng hoặc gần trùng.",en:"A tag that names the preferred URL when several URLs carry duplicate or near-duplicate content."},{term:"CTR",vi:"Tỷ lệ nhấp, bằng lượt nhấp chia lượt hiển thị trên trang kết quả tìm kiếm.",en:"Click-through rate, clicks divided by impressions on the search results page."},{term:"Crawl budget",vi:"Mức độ và tần suất công cụ tìm kiếm sẵn sàng thu thập các URL của một website.",en:"How much and how often a search engine is willing to crawl a website's URLs."},{term:"E-E-A-T",vi:"Kinh nghiệm, chuyên môn, uy tín và độ tin cậy, khung đánh giá chất lượng nội dung.",en:"Experience, expertise, authoritativeness and trust, a framework for judging content quality."}],quiz:[{q:{vi:"Hai truy vấn: A có 9000 hiển thị, 450 nhấp; B có 1000 hiển thị, 150 nhấp. CTR chung là bao nhiêu?",en:"Two queries: A has 9000 impressions, 450 clicks; B has 1000 impressions, 150 clicks. What is the overall CTR?"},options:{vi:["10%","6%","5%","15%"],en:["10%","6%","5%","15%"]},answer:1,explain:{vi:"CTR = (450 + 150) / (9000 + 1000) = 6%; trung bình cộng 5% và 15% cho kết quả sai là 10%.",en:"CTR = (450 + 150) / (9000 + 1000) = 6%; averaging 5% and 15% gives the wrong 10%."}},{q:{vi:"Trang đã chuyển vĩnh viễn sang URL mới nên dùng mã phản hồi nào?",en:"Which status code should a permanently moved page use?"},options:{vi:["302","404","301","500"],en:["302","404","301","500"]},answer:2,explain:{vi:"301 là chuyển hướng vĩnh viễn, giúp chuyển tín hiệu xếp hạng sang URL mới.",en:"301 is a permanent redirect that passes ranking signals to the new URL."}},{q:{vi:"Chỉ số Core Web Vitals nào đo độ ổn định bố cục trang?",en:"Which Core Web Vital measures layout stability?"},options:{vi:["LCP","INP","TTFB","CLS"],en:["LCP","INP","TTFB","CLS"]},answer:3,explain:{vi:"CLS đo mức dịch chuyển bố cục bất ngờ; ngưỡng tốt là không quá 0,1.",en:"CLS measures unexpected layout shifts; the good threshold is 0.1 or less."}},{q:{vi:"Agency đề nghị mua backlink hàng loạt và chèn văn bản ẩn để lên top nhanh. Bạn làm gì?",en:"An agency proposes bulk-buying backlinks and adding hidden text to rank fast. What do you do?"},options:{vi:["Từ chối, báo cáo và đề xuất kế hoạch xây uy tín hợp lệ","Thử trên một danh mục nhỏ","Đồng ý nếu chi phí thấp","Dùng tên miền phụ để tránh bị phạt"],en:["Decline, escalate and propose a legitimate authority plan","Try it on a small category","Agree if the cost is low","Use a subdomain to avoid penalties"]},answer:0,explain:{vi:"Đây là hành vi spam, có thể bị xử lý thủ công và mất thứ hạng toàn site; chỉ dùng phương pháp mũ trắng.",en:"These are spam tactics that can trigger manual actions and site-wide ranking loss; use white-hat methods only."}}]}},"KK-378":{scenario:{company:"Lotus Dew Skincare",supervisor:{name:"Ngô Thùy Dương",role:{vi:"Trưởng phòng CRM & Marketing tự động",en:"CRM & Marketing Automation Manager"}},ref_code:"JRN-7714",title:{vi:"Đúng người đồng ý. Đúng doanh thu tăng thêm.",en:"Right consent. Right incremental revenue."},brief:{vi:"Bạn cấu hình đợt 2 hành trình tái kích hoạt JRN-7714, chỉ nhắm khách đã đồng ý nhận tin tiếp thị nhưng không mở email 90 ngày; bản nháp chọn phân khúc ALL-INACTIVE90 (gồm cả liên hệ chưa đồng ý và đã hủy đăng ký). Kết quả đợt 1: nhóm nhận tin 18000 liên hệ có 540 đơn; nhóm đối chứng 2000 liên hệ không nhận tin có 40 đơn; giá trị đơn trung bình 400 nghìn đồng (mô phỏng). Sửa phân khúc và doanh thu tăng thêm (triệu đồng), rồi lập báo cáo có căn cứ.",en:"You are configuring wave 2 of win-back journey JRN-7714, targeting only customers who gave marketing consent but have not opened an email in 90 days; the draft selects segment ALL-INACTIVE90 (including non-consented and unsubscribed contacts). Wave 1 results: the treated group of 18000 contacts placed 540 orders; the 2000-contact holdout placed 40; average order value 400 thousand VND (training data). Correct the segment and the incremental revenue (million VND), then write an evidence-based report."},reference_title:{vi:"Đặc tả phân khúc & báo cáo đối chứng đã duyệt · JRN-7714",en:"Approved segment spec & holdout report · JRN-7714"},fields:[{id:"SEGMENT",label:{vi:"Phân khúc gửi đợt 2",en:"Wave 2 send segment"},initial:"ALL-INACTIVE90",expected:"OPTIN-INACTIVE90",choices:["ALL-INACTIVE90","OPTIN-INACTIVE90","OPTIN-ACTIVE30"],reference:"Đặc tả phân khúc hành trình",hint:{vi:"Tin tiếp thị chỉ gửi cho liên hệ có đồng ý hợp lệ và chưa hủy; mục tiêu đợt này là nhóm không mở email 90 ngày.",en:"Marketing messages go only to contacts with valid, unrevoked consent; this wave targets the 90-day non-openers."}},{id:"INCR_REV",label:{vi:"Doanh thu tăng thêm đợt 1 (triệu đồng)",en:"Wave 1 incremental revenue (million VND)"},initial:"216",expected:"72",reference:"Báo cáo nhóm nhận tin / đối chứng",ref_value:{vi:"Nhận tin 18000 liên hệ - 540 đơn; đối chứng 2000 - 40 đơn; AOV 0,4 triệu đồng",en:"Treated 18000 contacts - 540 orders; holdout 2000 - 40 orders; AOV 0.4 million VND"},hint:{vi:"Không gán toàn bộ đơn hàng cho chiến dịch; phải trừ phần khách vẫn mua khi không nhận tin.",en:"Do not credit every order to the campaign; subtract what customers buy without the message."}}],sop32:{vi:"Đơn tăng thêm = (tỷ lệ mua nhóm nhận tin - tỷ lệ mua nhóm đối chứng) x số liên hệ nhóm nhận tin; doanh thu tăng thêm = đơn tăng thêm x giá trị đơn trung bình.",en:"Incremental orders = (treated purchase rate - holdout purchase rate) x treated contacts; incremental revenue = incremental orders x average order value."},context:{label:"CRM AUTOMATION / JRN-7714",metrics:[{label:{vi:"Tỷ lệ mua nhóm nhận tin",en:"Treated purchase rate"},value:"3.0%"},{label:{vi:"Tỷ lệ mua nhóm đối chứng",en:"Holdout purchase rate"},value:"2.0%"},{label:{vi:"Giá trị đơn trung bình",en:"Average order value"},value:"400k VND"}]},crisis:{vi:"Giám đốc kinh doanh gửi tệp 20000 số điện thoại và email mua từ bên ngoài: “Nhập hết vào hành trình, tối nay bắn SMS và email khuyến mại luôn, cần doanh số cuối tháng.”",en:"The sales director sends a file of 20000 phone numbers and emails bought from a third party: “Import them all into the journey and blast promo SMS and emails tonight, we need month-end sales.”"},options:{safe:{vi:"Từ chối nhập dữ liệu không có đồng ý hợp lệ, báo trưởng phòng CRM và bộ phận bảo vệ dữ liệu; đề xuất thu thập khách tiềm năng có đồng ý qua biểu mẫu xác nhận hai bước.",en:"Refuse to import data without valid consent, inform the CRM Manager and the data protection officer; propose consented lead capture through a double opt-in form."},shortcut:{vi:"Nhập tệp vào phân khúc riêng, gửi một lần rồi xóa để tránh bị phát hiện.",en:"Import the file into a separate segment, send once and delete it to avoid detection."},wait:{vi:"Để tệp trong hộp thư, không trả lời và chờ giám đốc tự nhập.",en:"Leave the file in the inbox, do not reply and wait for the director to import it."}},questions:{vi:["Vì sao phân khúc đúng là OPTIN-INACTIVE90? Hãy nêu căn cứ về sự đồng ý và tiêu chí hành vi.","Trình bày cách tính doanh thu tăng thêm 72 triệu đồng và rủi ro pháp lý nếu gửi tin cho dữ liệu mua ngoài."],en:["Why is OPTIN-INACTIVE90 the correct segment? State the consent basis and behavioral criteria.","Explain how you reached 72 million VND of incremental revenue and the legal risk of messaging bought data."]},hints:{vi:["Đọc đặc tả phân khúc: lọc trạng thái đồng ý trước, rồi mới lọc hành vi mở email.","Theo SOP mục 3.2, so tỷ lệ mua của nhóm nhận tin với nhóm đối chứng trước khi nhân giá trị đơn.","Đọc SOP mục 4.2: dữ liệu cá nhân không rõ nguồn gốc và không có đồng ý không được nhập vào hệ thống."],en:["Read the segment spec: filter consent status first, then email-open behavior.","Per SOP 3.2, compare treated and holdout purchase rates before multiplying by order value.","Read SOP 4.2: personal data of unknown origin and without consent must never enter the system."]}},learning:{summary:{vi:"Chuyên viên CRM & Marketing tự động hóa xây dựng và vận hành các hành trình khách hàng tự động qua email, SMS, thông báo ứng dụng và tin nhắn OTT: chào mừng, nuôi dưỡng, bỏ giỏ hàng, tái kích hoạt, chăm sóc sau mua. Nghề kết hợp phân khúc dữ liệu, thiết kế kịch bản, đo lường bằng nhóm đối chứng và quản trị sự đồng ý để tăng giá trị vòng đời khách hàng mà vẫn tuân thủ pháp luật về dữ liệu cá nhân và chống tin rác.",en:"A CRM & Marketing Automation Specialist builds and runs automated customer journeys across email, SMS, app push and messaging apps: welcome, nurture, cart abandonment, win-back and post-purchase care. The role combines data segmentation, journey design, holdout-based measurement and consent management to grow customer lifetime value while complying with personal data and anti-spam rules."},responsibilities:{vi:["Thiết kế hành trình tự động theo vòng đời khách hàng và điều kiện kích hoạt rõ ràng.","Xây phân khúc theo RFM, hành vi và trạng thái đồng ý; duy trì danh sách loại trừ.","Viết, kiểm thử nội dung đa kênh và kiểm soát tần suất gửi cho mỗi khách hàng.","Đo hiệu quả bằng nhóm đối chứng, tính doanh thu tăng thêm và tối ưu kịch bản.","Quản trị chất lượng dữ liệu, xác thực tên miền gửi thư và tuân thủ quy định dữ liệu cá nhân."],en:["Design lifecycle-based automated journeys with clear entry triggers.","Build segments by RFM, behavior and consent status; maintain suppression lists.","Write and test multichannel content and control message frequency per customer.","Measure with holdout groups, compute incremental revenue and optimize journeys.","Govern data quality, sender domain authentication and personal data compliance."]},competencies:[{name:{vi:"Phân khúc & dữ liệu khách hàng",en:"Segmentation & customer data"},desc:{vi:"Ghép dữ liệu giao dịch, hành vi, sự đồng ý thành phân khúc có thể hành động và cập nhật tự động.",en:"Combine transaction, behavior and consent data into actionable, auto-updating segments."}},{name:{vi:"Thiết kế hành trình",en:"Journey design"},desc:{vi:"Xây luồng kích hoạt, rẽ nhánh, thời gian chờ và điều kiện thoát hợp lý.",en:"Build triggers, branches, wait steps and sensible exit conditions."}},{name:{vi:"Đo lường tăng trưởng thực",en:"Incrementality measurement"},desc:{vi:"Dùng nhóm đối chứng để tách doanh thu do chiến dịch tạo ra khỏi doanh thu tự nhiên.",en:"Use holdouts to separate campaign-driven revenue from organic revenue."}},{name:{vi:"Khả năng gửi thư",en:"Deliverability"},desc:{vi:"Cấu hình SPF, DKIM, DMARC, giữ danh sách sạch và tỷ lệ khiếu nại thấp.",en:"Configure SPF, DKIM and DMARC and keep clean lists and low complaint rates."}},{name:{vi:"Quản trị sự đồng ý",en:"Consent governance"},desc:{vi:"Ghi nhận, lưu bằng chứng, tôn trọng việc rút đồng ý và từ chối dữ liệu không rõ nguồn gốc.",en:"Record and evidence consent, honor withdrawals and reject data of unknown origin."}}],knowledge:{vi:["Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và Luật Bảo vệ dữ liệu cá nhân có hiệu lực từ 01/01/2026.","Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác.","Xác thực thư điện tử SPF, DKIM, DMARC và hủy đăng ký một chạm theo RFC 8058.","Phân khúc RFM (gần đây, tần suất, giá trị) và mô hình vòng đời khách hàng.","Thiết kế thử nghiệm A/B và nhóm đối chứng, cách tính doanh thu tăng thêm."],en:["Decree 13/2023/ND-CP on personal data protection and the Personal Data Protection Law effective 1 January 2026.","Decree 91/2020/ND-CP on combating spam messages, spam emails and spam calls.","Email authentication with SPF, DKIM, DMARC and one-click unsubscribe under RFC 8058.","RFM segmentation (recency, frequency, monetary) and customer lifecycle models.","A/B test and holdout design and how to compute incremental revenue."]},tools:["Nền tảng CRM / CDP","Công cụ marketing tự động hóa","Cổng gửi SMS & tin nhắn OTT","SQL","Công cụ kiểm tra hiển thị & khả năng gửi email","Looker Studio / BI"],kpis:{vi:["Doanh thu tăng thêm đo bằng nhóm đối chứng của từng hành trình.","Tỷ lệ mở, nhấp, chuyển đổi và tỷ lệ hủy đăng ký theo kênh.","Tỷ lệ thư bị trả về và tỷ lệ khiếu nại spam dưới ngưỡng cho phép.","Tỷ lệ liên hệ có bằng chứng đồng ý hợp lệ trong cơ sở dữ liệu (mục tiêu 100%)."],en:["Holdout-measured incremental revenue per journey.","Open, click, conversion and unsubscribe rates by channel.","Bounce and spam complaint rates below allowed thresholds.","Share of contacts with valid consent evidence in the database (target 100%)."]},day:[{time:"08:30",vi:"Kiểm tra nhật ký gửi đêm qua, tỷ lệ trả về, khiếu nại và lỗi kích hoạt hành trình.",en:"Check last night's send logs, bounces, complaints and journey trigger errors."},{time:"10:00",vi:"Viết truy vấn SQL dựng phân khúc mới và đối chiếu trạng thái đồng ý.",en:"Write SQL for a new segment and reconcile consent status."},{time:"13:30",vi:"Kiểm thử nội dung email, SMS trên nhiều thiết bị và luồng rẽ nhánh.",en:"Test email and SMS content across devices and branching logic."},{time:"15:30",vi:"Phân tích kết quả nhóm nhận tin so với đối chứng, cập nhật doanh thu tăng thêm.",en:"Analyze treated versus holdout results and update incremental revenue."},{time:"17:00",vi:"Họp nhanh với bộ phận dữ liệu về yêu cầu rút đồng ý và danh sách loại trừ.",en:"Sync with the data team on consent withdrawals and suppression lists."}],mistakes:{vi:["Gửi tin tiếp thị cho liên hệ chưa đồng ý hoặc đã hủy đăng ký.","Gán toàn bộ doanh thu của người nhận tin cho chiến dịch mà không có nhóm đối chứng.","Nhập danh sách mua ngoài vào hệ thống, làm hỏng uy tín tên miền gửi và vi phạm pháp luật."],en:["Sending marketing messages to non-consented or unsubscribed contacts.","Crediting all recipient revenue to the campaign without a holdout group.","Importing bought lists, damaging sender reputation and breaking the law."]},career:[{vi:"Nhân viên vận hành CRM / email marketing",en:"CRM / Email Marketing Executive"},{vi:"Chuyên viên CRM & Marketing tự động hóa",en:"CRM & Marketing Automation Specialist"},{vi:"Trưởng nhóm CRM & vòng đời khách hàng",en:"CRM & Lifecycle Marketing Lead"},{vi:"Giám đốc CRM & Dữ liệu khách hàng",en:"Head of CRM & Customer Data"}],glossary:[{term:"Opt-in",vi:"Sự đồng ý chủ động của khách hàng cho phép nhận thông tin tiếp thị qua một kênh cụ thể.",en:"A customer's active consent to receive marketing messages through a given channel."},{term:"Holdout group",vi:"Nhóm đối chứng được giữ lại không nhận tin để đo tác động thực của chiến dịch.",en:"A control group kept from receiving messages to measure the campaign's true impact."},{term:"RFM",vi:"Phân khúc theo mức gần đây, tần suất và giá trị mua hàng của khách.",en:"Segmentation by recency, frequency and monetary value of purchases."},{term:"DMARC",vi:"Chính sách xác thực tên miền gửi thư dựa trên SPF và DKIM, chống giả mạo người gửi.",en:"A sender domain authentication policy built on SPF and DKIM that fights spoofing."},{term:"Suppression list",vi:"Danh sách liên hệ bị loại khỏi mọi lần gửi do hủy đăng ký, khiếu nại hoặc địa chỉ lỗi.",en:"Contacts excluded from all sends due to unsubscribes, complaints or invalid addresses."}],quiz:[{q:{vi:"Nhóm nhận tin 10000 liên hệ có 400 đơn, nhóm đối chứng 1000 liên hệ có 30 đơn. Số đơn tăng thêm là bao nhiêu?",en:"The treated group of 10000 contacts placed 400 orders; the 1000-contact holdout placed 30. How many incremental orders?"},options:{vi:["400","370","300","100"],en:["400","370","300","100"]},answer:3,explain:{vi:"(4% - 3%) x 10000 = 100 đơn tăng thêm; 300 đơn còn lại khách vẫn mua khi không nhận tin.",en:"(4% - 3%) x 10000 = 100 incremental orders; the other 300 would have happened anyway."}},{q:{vi:"Liên hệ đã hủy đăng ký email tháng trước có được đưa vào chiến dịch khuyến mại mới không?",en:"Can a contact who unsubscribed last month be added to a new promotional campaign?"},options:{vi:["Có, nếu là khách VIP","Không, phải tôn trọng việc rút đồng ý","Có, nếu gửi qua SMS thay email","Có, sau 30 ngày"],en:["Yes, if they are VIP","No, the withdrawal must be honored","Yes, via SMS instead of email","Yes, after 30 days"]},answer:1,explain:{vi:"Rút đồng ý có hiệu lực cho đến khi khách tự đồng ý lại; đổi kênh không hợp thức hóa việc gửi.",en:"Withdrawal stands until the customer consents again; switching channels does not make it lawful."}},{q:{vi:"Bản ghi DNS nào cho phép tên miền công bố chính sách xử lý thư giả mạo?",en:"Which DNS record lets a domain publish a policy for spoofed mail?"},options:{vi:["DMARC","MX","CNAME","AAAA"],en:["DMARC","MX","CNAME","AAAA"]},answer:0,explain:{vi:"DMARC dựa trên kết quả SPF, DKIM để chỉ định cách xử lý thư không xác thực.",en:"DMARC uses SPF and DKIM results to specify how unauthenticated mail is handled."}},{q:{vi:"Cấp trên đưa tệp dữ liệu mua ngoài và yêu cầu gửi SMS khuyến mại ngay. Bạn làm gì?",en:"A manager hands you a bought data file and asks for promo SMS right away. What do you do?"},options:{vi:["Gửi thử 1000 số trước","Gửi qua tài khoản cá nhân","Từ chối, báo bộ phận bảo vệ dữ liệu và đề xuất thu thập có đồng ý","Gửi nhưng thêm dòng hủy đăng ký"],en:["Test on 1000 numbers first","Send from a personal account","Refuse, inform data protection and propose consented capture","Send but add an opt-out line"]},answer:2,explain:{vi:"Dữ liệu không có đồng ý hợp lệ không được dùng để tiếp thị; dòng hủy đăng ký không thay thế sự đồng ý.",en:"Data without valid consent cannot be used for marketing; an opt-out line does not replace consent."}}]}},"KK-379":{scenario:{company:"Lumi Habit Studio",supervisor:{name:"Vũ Gia Bảo",role:{vi:"Trưởng bộ phận Tăng trưởng",en:"Head of Growth"}},ref_code:"EXP-4630",title:{vi:"Không nhìn trộm kết quả. Không tô đẹp CAC.",en:"No peeking at results. No flattering CAC."},brief:{vi:"Bạn rà soát biên bản tăng trưởng EXP-4630. Thử nghiệm màn hình nâng cấp Premium đăng ký trước cỡ mẫu 12000 người dùng mỗi nhóm, quyết định tại α = 0,05: ngày 4 bảng điều khiển từng báo p = 0,03, khi đủ cỡ mẫu ngày 14 thì p = 0,21. Hoàn vốn CAC tháng 10: quảng cáo 400 triệu, thưởng giới thiệu 80 triệu đồng, 1000 người trả phí mới, ARPU 50 nghìn đồng/tháng, biên lợi nhuận gộp 80% (mô phỏng). Sửa quyết định thử nghiệm và số tháng hoàn vốn, rồi lập báo cáo có căn cứ.",en:"You are reviewing growth memo EXP-4630. The Premium upgrade screen test pre-registered 12000 users per arm with a decision at alpha = 0.05: on day 4 the dashboard showed p = 0.03, at full sample on day 14 p = 0.21. October CAC payback: ads 400 million, referral rewards 80 million VND, 1000 new paying users, ARPU 50 thousand VND/month, gross margin 80% (training data). Correct the test decision and the payback months, then write an evidence-based report."},reference_title:{vi:"Đăng ký thử nghiệm & bảng kinh tế đơn vị đã duyệt · EXP-4630",en:"Approved test registration & unit economics sheet · EXP-4630"},fields:[{id:"DECISION",label:{vi:"Quyết định thử nghiệm",en:"Test decision"},initial:"SHIP-B",expected:"KEEP-A",choices:["SHIP-B","KEEP-A","EXTEND"],reference:"Phiếu đăng ký thử nghiệm",hint:{vi:"Chỉ đọc kết quả tại cỡ mẫu đã đăng ký; p ≥ 0,05 là chưa đủ bằng chứng, không kéo dài để săn ý nghĩa.",en:"Read results only at the registered sample; p >= 0.05 is not enough evidence, and do not extend to chase significance."}},{id:"PAYBACK_M",label:{vi:"Thời gian hoàn vốn CAC (tháng)",en:"CAC payback (months)"},initial:"8",expected:"12",reference:"Bảng kinh tế đơn vị tháng 10",ref_value:{vi:"Quảng cáo 400 + thưởng giới thiệu 80 (triệu đồng); 1000 khách; ARPU 50 nghìn; biên gộp 80%",en:"Ads 400 + referral rewards 80 (million VND); 1000 users; ARPU 50 thousand; gross margin 80%"},hint:{vi:"CAC phải gồm mọi chi phí thu hút, và hoàn vốn tính trên lợi nhuận gộp chứ không phải doanh thu.",en:"CAC must include every acquisition cost, and payback uses gross profit, not revenue."}}],sop32:{vi:"CAC = toàn bộ chi phí thu hút (quảng cáo + thưởng giới thiệu + khuyến mại) / số khách trả phí mới; hoàn vốn (tháng) = CAC / (ARPU tháng x biên lợi nhuận gộp).",en:"CAC = all acquisition costs (ads + referral rewards + promotions) / new paying users; payback (months) = CAC / (monthly ARPU x gross margin)."},context:{label:"GROWTH DASHBOARD / EXP-4630",metrics:[{label:{vi:"p tại cỡ mẫu đăng ký",en:"p at registered sample"},value:"0.21"},{label:{vi:"Chi phí thu hút (triệu đồng)",en:"Acquisition cost (million VND)"},value:"400 + 80"},{label:{vi:"Khách trả phí mới",en:"New paying users"},value:"1000"}]},crisis:{vi:"CEO nhắn: “Bật mặc định quyền đọc danh bạ để tự gửi lời mời đến mọi số trong máy người dùng, và giấu nút hủy gia hạn sâu trong cài đặt cho churn giảm. Quý này phải đạt chỉ tiêu.”",en:"The CEO messages you: “Turn on contact-book access by default to auto-invite every number on the user's phone, and bury the cancel-subscription button deep in settings to cut churn. We must hit this quarter's target.”"},options:{safe:{vi:"Từ chối thiết kế lừa dối người dùng, báo trưởng bộ phận Tăng trưởng và pháp chế; đề xuất giới thiệu bạn bè có đồng ý rõ ràng, nút hủy minh bạch và thử nghiệm giữ chân dựa trên giá trị.",en:"Refuse deceptive design, inform the Head of Growth and Legal; propose opt-in referrals, a transparent cancel button and value-based retention tests."},shortcut:{vi:"Bật đọc danh bạ mặc định cho một phần người dùng mới và giấu nút hủy trong một tháng thử.",en:"Enable default contact access for some new users and hide the cancel button for a one-month trial."},wait:{vi:"Không phản hồi CEO và để đội kỹ thuật tự quyết có làm hay không.",en:"Do not answer the CEO and let engineering decide whether to build it."}},questions:{vi:["Vì sao quyết định đúng là KEEP-A dù ngày 4 từng có p = 0,03? Hãy giải thích rủi ro nhìn trộm kết quả.","Trình bày cách tính thời gian hoàn vốn 12 tháng và vì sao thiết kế lừa dối làm hại tăng trưởng bền vững và tuân thủ."],en:["Why is KEEP-A correct even though day 4 showed p = 0.03? Explain the risk of peeking.","Explain how you reached the 12-month payback and why deceptive design harms sustainable growth and compliance."]},hints:{vi:["Đọc phiếu đăng ký: cỡ mẫu, ngưỡng α và thời điểm ra quyết định đã cam kết trước.","Theo SOP mục 3.2, cộng đủ chi phí thu hút rồi chia cho lợi nhuận gộp mỗi tháng của một khách.","Đọc SOP mục 4.2: thay đổi quyền riêng tư hoặc cản trở hủy dịch vụ phải qua pháp chế và được báo cáo."],en:["Read the registration: sample size, alpha threshold and the decision point committed in advance.","Per SOP 3.2, add all acquisition costs and divide by one user's monthly gross profit.","Read SOP 4.2: privacy changes or barriers to cancellation must go through Legal and be escalated."]}},learning:{summary:{vi:"Chuyên viên Marketing tăng trưởng sản phẩm kết hợp tư duy dữ liệu, thử nghiệm và tiếp thị sản phẩm để tăng người dùng, kích hoạt, giữ chân và doanh thu. Công việc gồm định vị sản phẩm, thông điệp ra mắt, tối ưu phễu AARRR, vòng lặp giới thiệu và kinh tế đơn vị. Nghề đòi hỏi thiết kế thử nghiệm đúng thống kê, đọc số liệu trung thực và tăng trưởng bằng giá trị thật thay vì thủ thuật lừa người dùng.",en:"A Growth / Product Marketing Manager combines data, experimentation and product marketing to grow acquisition, activation, retention and revenue. The work covers product positioning, launch messaging, AARRR funnel optimization, referral loops and unit economics. The role requires statistically sound tests, honest reading of numbers and growth through real value rather than tricks that mislead users."},responsibilities:{vi:["Xác định chỉ số định hướng (North Star) và cây chỉ số cho từng giai đoạn phễu AARRR.","Lập kế hoạch thử nghiệm, đăng ký giả thuyết, cỡ mẫu và tiêu chí quyết định trước khi chạy.","Xây định vị, thông điệp và kế hoạch ra mắt tính năng cùng đội sản phẩm.","Phân tích nhóm thuần tập (cohort), tỷ lệ giữ chân và kinh tế đơn vị CAC, LTV, hoàn vốn.","Thiết kế vòng lặp tăng trưởng như giới thiệu bạn bè, nội dung do người dùng tạo, tích hợp đối tác."],en:["Define the North Star metric and a metric tree for each AARRR funnel stage.","Plan experiments and pre-register hypotheses, sample sizes and decision rules.","Build positioning, messaging and feature launch plans with the product team.","Analyze cohorts, retention and unit economics: CAC, LTV and payback.","Design growth loops such as referrals, user-generated content and partner integrations."]},competencies:[{name:{vi:"Thống kê thử nghiệm",en:"Experiment statistics"},desc:{vi:"Tính cỡ mẫu, hiệu ứng tối thiểu phát hiện được, đọc p-value và tránh nhìn trộm kết quả.",en:"Compute sample size and minimum detectable effect, read p-values and avoid peeking."}},{name:{vi:"Kinh tế đơn vị",en:"Unit economics"},desc:{vi:"Tính CAC đầy đủ, LTV trên lợi nhuận gộp, thời gian hoàn vốn và biên đóng góp.",en:"Compute fully loaded CAC, gross-margin LTV, payback and contribution margin."}},{name:{vi:"Định vị & thông điệp",en:"Positioning & messaging"},desc:{vi:"Xác định khách hàng mục tiêu, phương án thay thế, giá trị khác biệt và bằng chứng.",en:"Define target customers, alternatives, differentiated value and proof points."}},{name:{vi:"Phân tích hành vi",en:"Behavioral analytics"},desc:{vi:"Dùng phễu, cohort và đường cong giữ chân để tìm điểm nghẽn kích hoạt.",en:"Use funnels, cohorts and retention curves to find activation bottlenecks."}},{name:{vi:"Tăng trưởng có đạo đức",en:"Ethical growth"},desc:{vi:"Từ chối thiết kế lừa dối, tôn trọng quyền riêng tư và quyền hủy dịch vụ của người dùng.",en:"Reject deceptive design and respect user privacy and the right to cancel."}}],knowledge:{vi:["Khung phễu AARRR (thu hút, kích hoạt, giữ chân, giới thiệu, doanh thu) và chỉ số North Star.","Thống kê A/B: giả thuyết, α, lực kiểm định, cỡ mẫu, lỗi nhìn trộm và lệch tỷ lệ phân nhóm (SRM).","Kinh tế đơn vị: CAC, LTV, thời gian hoàn vốn, tỷ lệ LTV/CAC, biên lợi nhuận gộp.","Khung định vị sản phẩm, Jobs-to-be-Done và kế hoạch ra mắt thị trường (go-to-market).","Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15 và Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân."],en:["The AARRR funnel (acquisition, activation, retention, referral, revenue) and the North Star metric.","A/B statistics: hypotheses, alpha, power, sample size, peeking errors and sample ratio mismatch (SRM).","Unit economics: CAC, LTV, payback period, LTV/CAC ratio and gross margin.","Product positioning frameworks, Jobs-to-be-Done and go-to-market planning.","Consumer Rights Protection Law No. 19/2023/QH15 and Decree 13/2023/ND-CP on personal data protection."]},tools:["Công cụ phân tích sản phẩm (product analytics)","Nền tảng thử nghiệm A/B & feature flag","SQL","Python / R cho thống kê","Công cụ khảo sát người dùng","Looker Studio / BI"],kpis:{vi:["Chỉ số North Star và tỷ lệ kích hoạt người dùng mới.","Tỷ lệ giữ chân theo cohort ngày 30 và ngày 90.","Thời gian hoàn vốn CAC và tỷ lệ LTV/CAC.","Tỷ lệ thử nghiệm được đăng ký trước và kết luận đúng quy trình."],en:["The North Star metric and new-user activation rate.","Day-30 and day-90 cohort retention.","CAC payback period and LTV/CAC ratio.","Share of experiments pre-registered and concluded by the rules."]},day:[{time:"08:30",vi:"Xem bảng chỉ số North Star, phễu kích hoạt và cảnh báo lệch tỷ lệ phân nhóm.",en:"Review the North Star board, activation funnel and sample ratio alerts."},{time:"10:00",vi:"Viết phiếu đăng ký thử nghiệm mới: giả thuyết, chỉ số chính, cỡ mẫu, thời hạn.",en:"Write a new test registration: hypothesis, primary metric, sample size and duration."},{time:"13:30",vi:"Phỏng vấn 3 người dùng rời bỏ để hiểu rào cản kích hoạt.",en:"Interview 3 churned users to understand activation barriers."},{time:"15:00",vi:"Họp đội sản phẩm duyệt thông điệp ra mắt và bằng chứng giá trị.",en:"Meet the product team to approve launch messaging and proof points."},{time:"17:00",vi:"Cập nhật bảng kinh tế đơn vị, ghi bài học thử nghiệm vào kho tri thức.",en:"Update the unit economics sheet and log test learnings in the knowledge base."}],mistakes:{vi:["Dừng thử nghiệm ngay khi thấy p < 0,05 ở giữa chừng, chọn nhầm phương án do dao động ngẫu nhiên.","Tính CAC chỉ bằng chi phí quảng cáo và hoàn vốn trên doanh thu thay vì lợi nhuận gộp.","Dùng thiết kế lừa dối để tăng số liệu ngắn hạn, gây khiếu nại và rủi ro pháp lý."],en:["Stopping a test the moment p < 0.05 appears mid-way and picking noise.","Computing CAC from ad spend only and payback on revenue instead of gross profit.","Using deceptive design to inflate short-term numbers, causing complaints and legal risk."]},career:[{vi:"Chuyên viên phân tích tăng trưởng",en:"Growth Analyst"},{vi:"Chuyên viên Marketing tăng trưởng / Product Marketing",en:"Growth Marketer / Product Marketing Manager"},{vi:"Trưởng nhóm Tăng trưởng",en:"Growth Lead"},{vi:"Giám đốc Tăng trưởng / Giám đốc Marketing sản phẩm",en:"Head of Growth / Director of Product Marketing"}],glossary:[{term:"North Star Metric",vi:"Chỉ số định hướng duy nhất phản ánh giá trị cốt lõi người dùng nhận được từ sản phẩm.",en:"The single guiding metric that reflects the core value users get from the product."},{term:"Peeking",vi:"Xem và ra quyết định từ kết quả thử nghiệm nhiều lần trước khi đủ cỡ mẫu, làm tăng dương tính giả.",en:"Checking and deciding on test results repeatedly before the full sample, inflating false positives."},{term:"CAC payback",vi:"Số tháng lợi nhuận gộp từ một khách hàng cần để bù chi phí thu hút khách đó.",en:"Months of gross profit from a customer needed to recover the cost of acquiring them."},{term:"Cohort",vi:"Nhóm người dùng có cùng thời điểm hoặc điều kiện bắt đầu, dùng để phân tích giữ chân.",en:"A group of users sharing a start date or condition, used for retention analysis."},{term:"Dark pattern",vi:"Thiết kế giao diện cố ý khiến người dùng làm điều họ không định làm.",en:"Interface design that deliberately pushes users into actions they did not intend."}],quiz:[{q:{vi:"CAC 300 nghìn đồng, ARPU 60 nghìn đồng/tháng, biên lợi nhuận gộp 50%. Thời gian hoàn vốn là bao nhiêu?",en:"CAC is 300 thousand VND, ARPU 60 thousand VND/month, gross margin 50%. What is the payback period?"},options:{vi:["5 tháng","6 tháng","2,5 tháng","10 tháng"],en:["5 months","6 months","2.5 months","10 months"]},answer:3,explain:{vi:"Lợi nhuận gộp mỗi tháng = 60 x 50% = 30; hoàn vốn = 300 / 30 = 10 tháng.",en:"Monthly gross profit = 60 x 50% = 30; payback = 300 / 30 = 10 months."}},{q:{vi:"Thử nghiệm đạt đủ cỡ mẫu đăng ký với p = 0,21 tại α = 0,05. Kết luận nào đúng?",en:"A test reaches its registered sample with p = 0.21 at alpha = 0.05. Which conclusion is right?"},options:{vi:["Chưa đủ bằng chứng, giữ phương án đối chứng","Phương án mới thắng","Kéo dài đến khi p < 0,05","Bỏ ngày xấu khỏi dữ liệu"],en:["Not enough evidence, keep the control","The new variant wins","Extend until p < 0.05","Drop the bad days from the data"]},answer:0,explain:{vi:"p lớn hơn α nghĩa là chưa bác bỏ được giả thuyết không; kéo dài hay cắt dữ liệu để săn ý nghĩa là sai phương pháp.",en:"p above alpha means the null is not rejected; extending or trimming data to chase significance is invalid."}},{q:{vi:"Thử nghiệm chia 50/50 nhưng thu được 10000 và 11200 người dùng, kiểm định chi bình phương cho p < 0,001. Nên làm gì?",en:"A 50/50 test collected 10000 and 11200 users and a chi-square check gives p < 0.001. What should you do?"},options:{vi:["Đọc kết quả bình thường vì mẫu đã lớn","Dừng diễn giải, điều tra lỗi phân nhóm hoặc ghi nhận sự kiện","Xóa bớt 1200 người dùng ở nhóm lớn hơn","Chọn nhóm có nhiều người dùng hơn"],en:["Read results as usual since the sample is large","Stop interpreting and investigate assignment or logging bugs","Delete 1200 users from the larger arm","Pick the arm with more users"]},answer:1,explain:{vi:"Đây là lệch tỷ lệ phân nhóm (SRM), dấu hiệu lỗi phân bổ hoặc đo lường; kết quả không đáng tin cho đến khi tìm ra nguyên nhân.",en:"This is a sample ratio mismatch (SRM), a sign of assignment or tracking bugs; results are untrustworthy until the cause is found."}},{q:{vi:"CEO yêu cầu giấu nút hủy gia hạn để giảm churn. Bạn làm gì?",en:"The CEO asks you to hide the cancel button to reduce churn. What do you do?"},options:{vi:["Làm theo trong một quý","Chỉ giấu trên ứng dụng di động","Từ chối, báo pháp chế và đề xuất giữ chân bằng giá trị","Làm nhưng không ghi vào tài liệu"],en:["Comply for one quarter","Hide it on mobile only","Refuse, inform Legal and propose value-based retention","Do it but keep it undocumented"]},answer:2,explain:{vi:"Cản trở quyền hủy là thiết kế lừa dối, xâm phạm quyền lợi người tiêu dùng; giữ chân phải bằng giá trị thật.",en:"Obstructing cancellation is a dark pattern that harms consumer rights; retention must come from real value."}}]}},"KK-380":{scenario:{company:"Cloud Hill Tea Co.",supervisor:{name:"Quách Tùng Lâm",role:{vi:"Giám đốc Marketing",en:"Marketing Director"}},ref_code:"BRF-1185",title:{vi:"Claim có bằng chứng. Độ phủ không vượt 100%.",en:"Claims with evidence. Reach never tops 100%."},brief:{vi:"Bạn duyệt hồ sơ ra mắt BRF-1185 của dòng trà đóng chai ít ngọt. Kết quả kiểm nghiệm: 4,5 g đường/100 ml, công thức gốc 7,0 g/100 ml; bản nháp nhãn ghi claim SUGAR-FREE (“Không đường”). Đợt TVC 1 đạt 312 GRP trên nhóm mục tiêu với tần suất trung bình 4,0 lần, nhưng báo cáo nháp ghi độ phủ 312%. Sửa claim theo hướng dẫn claim nội bộ (ngưỡng mô phỏng) và độ phủ 1+ (%), rồi lập báo cáo có căn cứ.",en:"You are approving launch file BRF-1185 for a less-sweet bottled tea line. Lab result: 4.5 g sugar/100 ml, original recipe 7.0 g/100 ml; the draft label carries the claim SUGAR-FREE. TVC flight 1 delivered 312 GRPs on the target audience at an average frequency of 4.0, yet the draft report shows 312% reach. Correct the claim per the internal claim guideline (training thresholds) and the 1+ reach (%), then write an evidence-based report."},reference_title:{vi:"Hướng dẫn claim & báo cáo hậu kiểm truyền thông đã duyệt · BRF-1185",en:"Approved claim guideline & media post-buy · BRF-1185"},fields:[{id:"CLAIM",label:{vi:"Claim đường trên nhãn",en:"Sugar claim on label"},initial:"SUGAR-FREE",expected:"REDUCED-SUGAR",choices:["SUGAR-FREE","LOW-SUGAR","REDUCED-SUGAR"],reference:"Hướng dẫn claim dinh dưỡng nội bộ",hint:{vi:"Ngưỡng mô phỏng: không đường ≤ 0,5 g/100 ml; ít đường ≤ 2,5 g/100 ml; giảm đường khi thấp hơn công thức gốc ít nhất 30%.",en:"Training thresholds: sugar-free <= 0.5 g/100 ml; low sugar <= 2.5 g/100 ml; reduced sugar if at least 30% below the original recipe."}},{id:"REACH_PCT",label:{vi:"Độ phủ 1+ đợt TVC 1 (%)",en:"TVC flight 1 reach 1+ (%)"},initial:"312",expected:"78",reference:"Báo cáo hậu kiểm truyền thông",ref_value:{vi:"Tổng 312 GRP trên nhóm mục tiêu; tần suất trung bình 4,0",en:"Total 312 GRPs on the target audience; average frequency 4.0"},hint:{vi:"GRP là tổng số lần tiếp cận tính theo phần trăm, không phải độ phủ; độ phủ không thể vượt 100%.",en:"GRPs are total exposures in percentage points, not reach; reach can never exceed 100%."}}],sop32:{vi:"GRP = độ phủ (%) x tần suất trung bình, nên độ phủ 1+ (%) = GRP / tần suất trung bình. Không báo cáo GRP như độ phủ; claim phải có kết quả kiểm nghiệm làm bằng chứng.",en:"GRP = reach (%) x average frequency, so reach 1+ (%) = GRP / average frequency. Never report GRPs as reach; every claim needs lab results as evidence."},context:{label:"BRAND LAUNCH FILE / BRF-1185",metrics:[{label:{vi:"Đường / 100 ml",en:"Sugar / 100 ml"},value:"4.5 g (gốc / original 7.0 g)"},{label:{vi:"Tổng GRP đợt 1",en:"Flight 1 GRPs"},value:"312"},{label:{vi:"Tần suất trung bình",en:"Average frequency"},value:"4.0"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Cứ in ‘Không đường’ và thêm ‘tốt cho người tiểu đường’, đối thủ cũng ghi vậy. File in bao bì phải chốt tối nay, sửa là lỡ lịch lên kệ.”",en:"The sales director messages you: “Just print sugar-free and add good for diabetics, competitors say the same. The packaging file must be locked tonight or we miss the shelf date.”"},options:{safe:{vi:"Từ chối claim sai và claim sức khỏe chưa được phép, báo Giám đốc Marketing cùng bộ phận chất lượng, pháp chế; dùng claim “giảm hơn 35% đường so với công thức gốc” kèm kết quả kiểm nghiệm.",en:"Refuse the false claim and the unauthorized health claim, inform the Marketing Director, QA and Legal; use the claim 35% less sugar than the original recipe, backed by lab results."},shortcut:{vi:"In “Không đường” cho lô đầu cho kịp lên kệ, lô sau sẽ sửa nhãn.",en:"Print sugar-free on the first batch to make the shelf date and fix the label later."},wait:{vi:"Không chốt file và chờ kinh doanh với nhà in tự quyết nội dung nhãn.",en:"Do not lock the file and wait for Sales and the printer to decide the label."}},questions:{vi:["Vì sao claim đúng là REDUCED-SUGAR mà không phải SUGAR-FREE hay LOW-SUGAR? Hãy dẫn số liệu kiểm nghiệm và ngưỡng.","Trình bày cách tính độ phủ 78% và rủi ro thương hiệu, pháp lý nếu in claim sai hoặc báo cáo GRP như độ phủ."],en:["Why is REDUCED-SUGAR right rather than SUGAR-FREE or LOW-SUGAR? Cite the lab data and thresholds.","Explain how you reached 78% reach and the brand and legal risks of a false claim or reporting GRPs as reach."]},hints:{vi:["So kết quả kiểm nghiệm với từng ngưỡng claim, rồi tính mức giảm so với công thức gốc.","Theo SOP mục 3.2, chia tổng GRP cho tần suất trung bình để có độ phủ.","Đọc SOP mục 4.2: mọi claim dinh dưỡng, sức khỏe phải có bằng chứng và được pháp chế duyệt trước khi in."],en:["Compare the lab result with each claim threshold, then compute the reduction versus the original recipe.","Per SOP 3.2, divide total GRPs by average frequency to get reach.","Read SOP 4.2: every nutrition or health claim needs evidence and Legal approval before printing."]}},learning:{summary:{vi:"Quản lý thương hiệu chịu trách nhiệm toàn diện về sức khỏe và tăng trưởng của một thương hiệu: định vị, chân dung khách hàng, danh mục sản phẩm, giá, bao bì, truyền thông và ngân sách marketing. Nghề đòi hỏi thấu hiểu người tiêu dùng, đọc số liệu thị trường và truyền thông, điều phối agency và các phòng ban, đồng thời bảo vệ niềm tin bằng các claim trung thực, có bằng chứng.",en:"A Brand Manager owns the health and growth of a brand end to end: positioning, target consumer, portfolio, pricing, packaging, communication and marketing budget. The role requires consumer insight, reading market and media data, steering agencies and internal teams, and protecting trust through honest, evidence-based claims."},responsibilities:{vi:["Xây dựng và giữ nhất quán định vị, tính cách và cấu trúc thương hiệu.","Lập kế hoạch thương hiệu năm: mục tiêu, ngân sách, kế hoạch ra mắt và truyền thông.","Viết brief cho agency sáng tạo, truyền thông và duyệt sản phẩm sáng tạo theo chiến lược.","Theo dõi sức khỏe thương hiệu: nhận biết, cân nhắc, dùng thử, mua lặp lại, thị phần.","Phối hợp R&D, chất lượng, pháp chế để bao bì, claim và quảng cáo đúng quy định."],en:["Build and keep brand positioning, personality and architecture consistent.","Write the annual brand plan: goals, budget, launches and communication.","Brief creative and media agencies and approve creative work against strategy.","Track brand health: awareness, consideration, trial, repeat and market share.","Work with R&D, QA and Legal so packaging, claims and ads comply with regulations."]},competencies:[{name:{vi:"Chiến lược thương hiệu",en:"Brand strategy"},desc:{vi:"Xác định khách hàng mục tiêu, sự thật ngầm hiểu, lợi ích khác biệt và lý do tin tưởng.",en:"Define the target, consumer insight, differentiated benefit and reasons to believe."}},{name:{vi:"Đọc số liệu thị trường",en:"Market data literacy"},desc:{vi:"Phân tích thị phần, phân phối, giá, chỉ số sức khỏe thương hiệu và hậu kiểm truyền thông.",en:"Analyze share, distribution, price, brand health and media post-buy data."}},{name:{vi:"Quản trị sáng tạo",en:"Creative leadership"},desc:{vi:"Viết brief sắc, phản hồi sáng tạo dựa trên chiến lược thay vì sở thích cá nhân.",en:"Write sharp briefs and give creative feedback based on strategy, not taste."}},{name:{vi:"Quản lý ngân sách & P&L",en:"Budget & P&L management"},desc:{vi:"Phân bổ ngân sách theo hiệu quả, theo dõi biên lợi nhuận và đóng góp của thương hiệu.",en:"Allocate budget by effectiveness and track the brand's margin and contribution."}},{name:{vi:"Liêm chính thương hiệu",en:"Brand integrity"},desc:{vi:"Chỉ dùng claim có bằng chứng, từ chối thông điệp gây hiểu lầm dù chịu áp lực doanh số.",en:"Use only substantiated claims and refuse misleading messages despite sales pressure."}}],knowledge:{vi:["Mô hình tài sản thương hiệu dựa trên khách hàng (CBBE) của Keller và tuyên bố định vị.","Phễu thương hiệu: nhận biết, cân nhắc, dùng thử, mua lặp lại, trung thành.","Chỉ số truyền thông: GRP, TRP, độ phủ, tần suất, CPP, thị phần tiếng nói (SOV).","Luật Quảng cáo số 16/2012/QH13 và các văn bản sửa đổi, hướng dẫn.","Nghị định 43/2017/NĐ-CP về nhãn hàng hóa (sửa đổi bởi Nghị định 111/2021/NĐ-CP).","Hướng dẫn Codex CAC/GL 23-1997 về sử dụng claim dinh dưỡng và sức khỏe."],en:["Keller's customer-based brand equity (CBBE) model and the positioning statement.","The brand funnel: awareness, consideration, trial, repeat, loyalty.","Media metrics: GRP, TRP, reach, frequency, CPP and share of voice (SOV).","Advertising Law No. 16/2012/QH13 with its amendments and guidance.","Decree 43/2017/ND-CP on goods labeling (amended by Decree 111/2021/ND-CP).","Codex guideline CAC/GL 23-1997 on the use of nutrition and health claims."]},tools:["Dữ liệu bán lẻ (retail audit)","Khảo sát sức khỏe thương hiệu (brand tracking)","Công cụ lập kế hoạch & hậu kiểm truyền thông","Social listening","Microsoft Excel / PowerPoint","Power BI"],kpis:{vi:["Thị phần theo giá trị và sản lượng so với kế hoạch.","Chỉ số nhận biết, cân nhắc và tỷ lệ dùng thử, mua lặp lại.","Hiệu quả truyền thông: độ phủ hiệu quả, CPP, SOV so với thị phần.","Số claim, bao bì bị khiếu nại hoặc phải thu hồi (mục tiêu bằng 0)."],en:["Value and volume market share versus plan.","Awareness, consideration, trial and repeat rates.","Media effectiveness: effective reach, CPP and SOV versus share.","Claims or packaging complaints and recalls (target zero)."]},day:[{time:"08:30",vi:"Xem số bán hàng tuần, thị phần và phân phối theo kênh của thương hiệu.",en:"Review weekly sales, share and distribution by channel."},{time:"10:00",vi:"Họp agency sáng tạo duyệt kịch bản TVC theo brief và định vị.",en:"Meet the creative agency to approve the TVC script against the brief and positioning."},{time:"13:30",vi:"Làm việc với R&D, chất lượng, pháp chế về claim và bản thiết kế bao bì mới.",en:"Work with R&D, QA and Legal on claims and the new packaging artwork."},{time:"15:30",vi:"Đọc báo cáo hậu kiểm truyền thông: GRP, độ phủ, tần suất, chi phí.",en:"Read the media post-buy: GRPs, reach, frequency and cost."},{time:"17:00",vi:"Cập nhật kế hoạch ra mắt, ngân sách và rủi ro cần báo Giám đốc Marketing.",en:"Update the launch plan, budget and risks for the Marketing Director."}],mistakes:{vi:["Báo cáo GRP như độ phủ, làm ban lãnh đạo hiểu sai số người thực sự xem quảng cáo.","In claim dinh dưỡng vượt bằng chứng kiểm nghiệm vì đối thủ cũng làm vậy.","Thay đổi định vị, nhận diện liên tục theo từng chiến dịch, làm loãng tài sản thương hiệu."],en:["Reporting GRPs as reach, misleading leaders about how many people saw the ad.","Printing nutrition claims beyond lab evidence because competitors do so.","Changing positioning and identity with every campaign, diluting brand equity."]},career:[{vi:"Trợ lý thương hiệu",en:"Assistant Brand Manager"},{vi:"Quản lý thương hiệu",en:"Brand Manager"},{vi:"Quản lý ngành hàng / Quản lý thương hiệu cấp cao",en:"Category Manager / Senior Brand Manager"},{vi:"Giám đốc Marketing",en:"Marketing Director"}],glossary:[{term:"GRP",vi:"Tổng điểm rating, bằng độ phủ (%) nhân tần suất trung bình trên một nhóm khán giả.",en:"Gross rating points, reach (%) times average frequency on an audience."},{term:"Reach 1+",vi:"Tỷ lệ khán giả mục tiêu thấy quảng cáo ít nhất một lần trong đợt phát sóng.",en:"Share of the target audience exposed to the ad at least once during the flight."},{term:"Positioning",vi:"Vị trí khác biệt thương hiệu muốn chiếm trong tâm trí khách hàng mục tiêu.",en:"The distinctive place a brand aims to hold in the target consumer's mind."},{term:"SOV",vi:"Thị phần tiếng nói, tỷ lệ chi tiêu hoặc hiện diện truyền thông của thương hiệu trong ngành hàng.",en:"Share of voice, the brand's share of media spend or presence in the category."},{term:"Claim",vi:"Tuyên bố về đặc tính, lợi ích sản phẩm trên nhãn hoặc quảng cáo, phải có bằng chứng.",en:"A statement about product attributes or benefits on pack or in ads that needs evidence."}],quiz:[{q:{vi:"Một đợt quảng cáo đạt 240 GRP với tần suất trung bình 3,0. Độ phủ 1+ là bao nhiêu?",en:"A flight delivers 240 GRPs at an average frequency of 3.0. What is reach 1+?"},options:{vi:["240%","720%","80%","60%"],en:["240%","720%","80%","60%"]},answer:2,explain:{vi:"Độ phủ = GRP / tần suất = 240 / 3,0 = 80%.",en:"Reach = GRP / frequency = 240 / 3.0 = 80%."}},{q:{vi:"Thành phần nào bắt buộc phải có trong một tuyên bố định vị tốt?",en:"Which element must a good positioning statement include?"},options:{vi:["Khách hàng mục tiêu, lợi ích khác biệt và lý do tin tưởng","Danh sách mọi tính năng sản phẩm","Giá bán lẻ đề xuất","Tên agency sáng tạo"],en:["Target, differentiated benefit and reason to believe","A list of every product feature","The suggested retail price","The creative agency's name"]},answer:0,explain:{vi:"Định vị trả lời: dành cho ai, khác biệt gì và vì sao nên tin.",en:"Positioning answers who it is for, what is different and why to believe it."}},{q:{vi:"Sản phẩm có 4,5 g đường/100 ml, công thức gốc 7,0 g. Theo ngưỡng mô phỏng trong bài, claim nào hợp lệ?",en:"A product has 4.5 g sugar/100 ml versus 7.0 g originally. Under the training thresholds, which claim is valid?"},options:{vi:["Không đường","Ít đường","Không có claim nào","Giảm đường so với công thức gốc"],en:["Sugar-free","Low sugar","No claim at all","Reduced sugar versus the original"]},answer:3,explain:{vi:"4,5 g vượt ngưỡng không đường và ít đường, nhưng thấp hơn công thức gốc khoảng 35,7% nên đủ điều kiện giảm đường.",en:"4.5 g exceeds the sugar-free and low-sugar thresholds but is about 35.7% below the original, so reduced sugar qualifies."}},{q:{vi:"Kinh doanh muốn in “tốt cho người tiểu đường” lên bao bì cho kịp lên kệ. Bạn làm gì?",en:"Sales wants good for diabetics printed on pack to make the shelf date. What do you do?"},options:{vi:["In lô đầu rồi sửa sau","Từ chối, báo pháp chế, chất lượng và dùng claim có bằng chứng","In chữ nhỏ ở mặt sau","Chỉ ghi trên mạng xã hội"],en:["Print the first batch and fix later","Refuse, inform Legal and QA and use an evidenced claim","Print it small on the back","Say it only on social media"]},answer:1,explain:{vi:"Claim sức khỏe chưa được chứng minh và cho phép là gây hiểu lầm, có thể bị xử phạt và thu hồi bao bì.",en:"Unproven, unauthorized health claims mislead consumers and can lead to penalties and packaging recalls."}}]}},"KK-381":{scenario:{company:"Polaris Insight Research",supervisor:{name:"Hà Thanh Tâm",role:{vi:"Giám đốc Nghiên cứu",en:"Research Director"}},ref_code:"MR-2048",title:{vi:"Mẫu nào, kết luận nấy. Gia quyền trước khi kết luận.",en:"Know your sample. Weight before you conclude."},brief:{vi:"Bạn kiểm tra báo cáo kiểm định concept MR-2048 cho dòng sữa hạt mới. Mẫu 500 người lấy từ panel trực tuyến, chỉ đặt hạn ngạch theo giới và tuổi; mẫu có 350 người thành thị và 150 nông thôn, trong khi tổng thể mục tiêu là 40% thành thị, 60% nông thôn. Ý định mua (top-2-box): thành thị 50%, nông thôn 30%. Bản nháp ghi mẫu SRS, sai số ±4,4% và ý định mua 44%. Sửa loại mẫu và ý định mua có gia quyền (%), rồi lập báo cáo có căn cứ.",en:"You are checking concept test report MR-2048 for a new nut milk line. The 500 respondents came from an online panel with quotas on gender and age only; the sample has 350 urban and 150 rural respondents, while the target population is 40% urban and 60% rural. Purchase intent (top-2-box): urban 50%, rural 30%. The draft states an SRS sample, a +/-4.4% margin of error and 44% intent. Correct the sample type and the weighted intent (%), then write an evidence-based report."},reference_title:{vi:"Thiết kế mẫu & bảng gia quyền đã duyệt · MR-2048",en:"Approved sample design & weighting sheet · MR-2048"},fields:[{id:"SAMPLE_TYPE",label:{vi:"Loại mẫu trong phần phương pháp",en:"Sample type in methodology"},initial:"SRS",expected:"QUOTA",choices:["SRS","QUOTA","CLUSTER"],reference:"Thiết kế mẫu nghiên cứu",hint:{vi:"Panel trực tuyến tự nguyện có hạn ngạch là mẫu phi xác suất; không được trình bày như mẫu ngẫu nhiên đơn giản.",en:"A volunteer online panel with quotas is a non-probability sample; it must not be presented as simple random."}},{id:"INTENT_W",label:{vi:"Ý định mua có gia quyền (%)",en:"Weighted purchase intent (%)"},initial:"44",expected:"38",reference:"Bảng gia quyền theo khu vực",ref_value:{vi:"Thành thị: ý định 50%, tổng thể 40%; nông thôn: ý định 30%, tổng thể 60%",en:"Urban: intent 50%, population 40%; rural: intent 30%, population 60%"},hint:{vi:"Con số 44% là trung bình theo cơ cấu mẫu lệch; hãy dùng tỷ trọng của tổng thể mục tiêu.",en:"The 44% figure follows the skewed sample mix; use the target population shares instead."}}],sop32:{vi:"Khi cơ cấu mẫu lệch tổng thể, gia quyền hậu phân tầng: chỉ số = tổng (tỷ trọng tổng thể của nhóm x tỷ lệ của nhóm). Không công bố sai số chọn mẫu kiểu ngẫu nhiên cho mẫu phi xác suất.",en:"When the sample mix differs from the population, post-stratify: estimate = sum (group population share x group rate). Never publish random-sampling margins of error for non-probability samples."},context:{label:"SURVEY DATA / MR-2048",metrics:[{label:{vi:"Cỡ mẫu",en:"Sample size"},value:"500 (350 / 150)"},{label:{vi:"Tổng thể thành thị / nông thôn",en:"Population urban / rural"},value:"40% / 60%"},{label:{vi:"Chuẩn hành động ra mắt",en:"Launch action standard"},value:">= 40%"}]},crisis:{vi:"Quản lý thương hiệu của khách hàng nhắn: “Chuẩn ra mắt là 40%. Cứ báo con số 44% chưa gia quyền, hoặc bỏ bớt mẫu nông thôn đi, ban giám đốc chỉ cần thấy concept đạt chuẩn.”",en:"The client's brand manager messages you: “The launch standard is 40%. Just report the unweighted 44%, or drop some rural respondents, the board only needs to see the concept pass.”"},options:{safe:{vi:"Báo cáo 38% có gia quyền kèm ghi chú phương pháp, báo Giám đốc Nghiên cứu; đề xuất tối ưu concept và kiểm định lại với mẫu nông thôn tăng cường thay vì chỉnh dữ liệu.",en:"Report the weighted 38% with a methodology note and inform the Research Director; propose optimizing the concept and retesting with a rural boost instead of altering data."},shortcut:{vi:"Báo con số 44% chưa gia quyền vì khách hàng là người trả tiền dự án.",en:"Report the unweighted 44% because the client pays for the project."},wait:{vi:"Gửi bảng số liệu thô cho khách tự chọn con số muốn trình bày.",en:"Send the raw tables and let the client pick the number to present."}},questions:{vi:["Vì sao loại mẫu phải ghi QUOTA và không được công bố sai số ±4,4%? Hãy giải thích bằng cách tuyển mẫu.","Trình bày cách tính ý định mua 38% có gia quyền và hệ quả nếu dùng con số 44% để quyết định ra mắt."],en:["Why must the sample type read QUOTA and why can the +/-4.4% margin not be published? Explain using the recruitment method.","Explain how you reached the weighted 38% intent and the consequences of using 44% for the launch decision."]},hints:{vi:["Đọc lại cách tuyển mẫu: nguồn panel, cách đặt hạn ngạch và mỗi người có xác suất được chọn biết trước hay không.","Theo SOP mục 3.2, nhân tỷ lệ của từng khu vực với tỷ trọng tổng thể rồi cộng lại.","Đọc SOP mục 4.2: kết quả nghiên cứu phải phản ánh đúng dữ liệu, không chỉnh để phục vụ quyết định định trước."],en:["Re-read the recruitment: panel source, quota setting and whether each person had a known selection probability.","Per SOP 3.2, multiply each area's rate by its population share and add them up.","Read SOP 4.2: research findings must reflect the data, never be tuned to fit a decision made in advance."]}},learning:{summary:{vi:"Chuyên viên Nghiên cứu thị trường & Thấu hiểu khách hàng thiết kế và phân tích nghiên cứu định lượng, định tính để trả lời câu hỏi kinh doanh: ai là khách hàng, họ cần gì, vì sao họ chọn hay rời bỏ thương hiệu, concept nào nên ra mắt. Nghề đòi hỏi nền tảng thống kê, thiết kế mẫu và bảng hỏi không thiên lệch, kỹ năng kể chuyện từ dữ liệu và chuẩn mực đạo đức nghiên cứu nghiêm ngặt.",en:"A Market Research & Consumer Insights Analyst designs and analyzes quantitative and qualitative studies that answer business questions: who the customers are, what they need, why they choose or leave a brand and which concept should launch. The role requires statistical grounding, unbiased sample and questionnaire design, data storytelling and strict research ethics."},responsibilities:{vi:["Chuyển câu hỏi kinh doanh thành mục tiêu, giả thuyết và thiết kế nghiên cứu phù hợp.","Thiết kế mẫu, hạn ngạch, bảng hỏi và hướng dẫn thảo luận nhóm, phỏng vấn sâu.","Kiểm soát chất lượng dữ liệu: loại bản trả lời kém chất lượng, kiểm tra logic, gia quyền.","Phân tích thống kê, kiểm định khác biệt, phân khúc và tổng hợp phát hiện định tính.","Viết báo cáo thấu hiểu, đề xuất hành động và trình bày cho các bên liên quan."],en:["Turn business questions into objectives, hypotheses and the right research design.","Design samples, quotas, questionnaires and discussion or interview guides.","Control data quality: remove poor responses, run logic checks and apply weights.","Run statistical analysis, significance tests, segmentation and qualitative synthesis.","Write insight reports, recommend actions and present to stakeholders."]},competencies:[{name:{vi:"Thiết kế mẫu & thống kê",en:"Sampling & statistics"},desc:{vi:"Phân biệt mẫu xác suất và phi xác suất, tính sai số, hiệu ứng thiết kế và gia quyền đúng cách.",en:"Separate probability and non-probability samples and compute margins, design effects and weights correctly."}},{name:{vi:"Thiết kế bảng hỏi",en:"Questionnaire design"},desc:{vi:"Viết câu hỏi trung lập, thang đo phù hợp, tránh câu dẫn dắt và câu hỏi kép.",en:"Write neutral questions with fitting scales and avoid leading or double-barreled items."}},{name:{vi:"Nghiên cứu định tính",en:"Qualitative research"},desc:{vi:"Điều phối thảo luận nhóm, phỏng vấn sâu, quan sát và phân tích chủ đề có hệ thống.",en:"Moderate focus groups and in-depth interviews, observe and run systematic thematic analysis."}},{name:{vi:"Kể chuyện bằng dữ liệu",en:"Data storytelling"},desc:{vi:"Biến bảng số thành thông điệp rõ ràng, ưu tiên điều ảnh hưởng tới quyết định kinh doanh.",en:"Turn tables into clear messages that put decision-relevant findings first."}},{name:{vi:"Đạo đức nghiên cứu",en:"Research ethics"},desc:{vi:"Bảo vệ người trả lời, minh bạch phương pháp và từ chối chỉnh kết quả theo ý khách hàng.",en:"Protect respondents, disclose methods transparently and refuse to bend results for clients."}}],knowledge:{vi:["Bộ quy tắc quốc tế ICC/ESOMAR về nghiên cứu thị trường, xã hội và phân tích dữ liệu.","ISO 20252 về yêu cầu dịch vụ nghiên cứu thị trường, ý kiến và xã hội.","Lý thuyết chọn mẫu: mẫu xác suất, mẫu hạn ngạch, sai số chọn mẫu = z x căn(p(1 - p) / n), hiệu ứng thiết kế.","Gia quyền hậu phân tầng, gia quyền RIM và cỡ mẫu hiệu dụng.","Kiểm định thống kê: chi bình phương, t-test, ý nghĩa thống kê và cỡ mẫu tối thiểu khi đọc nhóm nhỏ.","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân của người tham gia khảo sát."],en:["The ICC/ESOMAR International Code on market, opinion and social research and data analytics.","ISO 20252 service requirements for market, opinion and social research.","Sampling theory: probability samples, quota samples, margin of error = z x sqrt(p(1 - p) / n), design effect.","Post-stratification, RIM weighting and effective sample size.","Statistical tests: chi-square, t-test, significance and minimum bases for small subgroups.","Decree 13/2023/ND-CP on protecting survey participants' personal data."]},tools:["SPSS / R / Python","Nền tảng khảo sát trực tuyến","Online panel","Phần mềm mã hóa dữ liệu định tính","Microsoft Excel / PowerPoint","Power BI / Tableau"],kpis:{vi:["Tỷ lệ dự án giao đúng hạn với dữ liệu đạt kiểm soát chất lượng.","Tỷ lệ khuyến nghị nghiên cứu được kinh doanh áp dụng.","Số lỗi phương pháp hoặc số liệu bị phát hiện sau khi phát hành (mục tiêu bằng 0).","Mức hài lòng của bên đặt hàng nghiên cứu."],en:["Share of projects delivered on time with data passing quality control.","Share of research recommendations adopted by the business.","Method or data errors found after release (target zero).","Satisfaction of research stakeholders."]},day:[{time:"08:30",vi:"Kiểm tra tiến độ thu mẫu, tỷ lệ đạt hạn ngạch và bản trả lời đáng ngờ.",en:"Check fieldwork progress, quota fill and suspicious responses."},{time:"10:00",vi:"Làm sạch dữ liệu, chạy bảng chéo và tính trọng số theo tổng thể mục tiêu.",en:"Clean data, run cross-tabs and compute weights against the target population."},{time:"13:30",vi:"Điều phối một buổi thảo luận nhóm về thói quen dùng sữa hạt.",en:"Moderate a focus group on nut milk habits."},{time:"15:30",vi:"Kiểm định khác biệt giữa các phân khúc và ghi chú cỡ mẫu nhỏ.",en:"Test differences between segments and flag small bases."},{time:"17:00",vi:"Viết phần tóm tắt thấu hiểu và đề xuất hành động cho báo cáo.",en:"Draft the insight summary and recommended actions for the report."}],mistakes:{vi:["Công bố sai số kiểu ngẫu nhiên cho mẫu panel trực tuyến phi xác suất.","Báo cáo số liệu chưa gia quyền khi cơ cấu mẫu lệch xa tổng thể.","Đặt câu hỏi dẫn dắt hoặc đọc kết luận từ nhóm có cỡ mẫu quá nhỏ."],en:["Publishing random-sampling margins of error for non-probability online panels.","Reporting unweighted figures when the sample mix is far from the population.","Asking leading questions or drawing conclusions from tiny subgroups."]},career:[{vi:"Nhân viên phân tích dữ liệu khảo sát",en:"Research Executive"},{vi:"Chuyên viên Nghiên cứu thị trường & Thấu hiểu khách hàng",en:"Market Research & Consumer Insights Analyst"},{vi:"Quản lý nghiên cứu / Quản lý thấu hiểu khách hàng",en:"Research Manager / Insights Manager"},{vi:"Giám đốc Nghiên cứu & Thấu hiểu khách hàng",en:"Head of Research & Consumer Insights"}],glossary:[{term:"Quota sampling",vi:"Chọn mẫu phi xác suất, tuyển người trả lời đến khi đủ số lượng định trước cho từng nhóm.",en:"Non-probability sampling that recruits until preset counts per group are filled."},{term:"Weighting",vi:"Điều chỉnh trọng số người trả lời để cơ cấu mẫu khớp với tổng thể mục tiêu.",en:"Adjusting respondent weights so the sample mix matches the target population."},{term:"Top-2-box",vi:"Tỷ lệ chọn hai mức cao nhất của thang đo, ví dụ chắc chắn mua và có thể mua.",en:"Share choosing the two highest scale points, such as definitely and probably buy."},{term:"Margin of error",vi:"Biên sai số chọn mẫu ở độ tin cậy nhất định, chỉ có ý nghĩa đầy đủ với mẫu xác suất.",en:"Sampling error band at a given confidence level, fully meaningful only for probability samples."},{term:"Action standard",vi:"Ngưỡng kết quả được thống nhất trước nghiên cứu để ra quyết định kinh doanh.",en:"A result threshold agreed before the study to drive a business decision."}],quiz:[{q:{vi:"Tổng thể 30% nhóm A, 70% nhóm B. Tỷ lệ thích sản phẩm: A 60%, B 40%. Chỉ số có gia quyền là bao nhiêu?",en:"The population is 30% group A and 70% group B. Product liking: A 60%, B 40%. What is the weighted figure?"},options:{vi:["50%","46%","54%","40%"],en:["50%","46%","54%","40%"]},answer:1,explain:{vi:"Chỉ số có gia quyền = 0,3 x 60 + 0,7 x 40 = 18 + 28 = 46%; trung bình cộng 50% là sai.",en:"0.3 x 60 + 0.7 x 40 = 18 + 28 = 46%."}},{q:{vi:"Câu hỏi nào là câu hỏi dẫn dắt?",en:"Which question is leading?"},options:{vi:["Bạn thường mua sữa ở đâu?","Bạn uống sữa bao nhiêu lần mỗi tuần?","Bạn đánh giá vị sản phẩm thế nào trên thang 1-5?","Bạn có đồng ý sản phẩm tuyệt vời này đáng mua không?"],en:["Where do you usually buy milk?","How many times a week do you drink milk?","How do you rate the taste on a 1-5 scale?","Do you agree this great product is worth buying?"]},answer:3,explain:{vi:"Từ “tuyệt vời” và cấu trúc “có đồng ý” gợi ý câu trả lời, làm kết quả thiên lệch.",en:"The word great and the agree framing suggest the answer and bias results."}},{q:{vi:"Mẫu ngẫu nhiên đơn giản n = 400, p = 0,5, độ tin cậy 95%. Sai số chọn mẫu xấp xỉ bao nhiêu?",en:"A simple random sample n = 400, p = 0.5, 95% confidence. What is the approximate margin of error?"},options:{vi:["±4,9%","±2,5%","±10%","±1,0%"],en:["+/-4.9%","+/-2.5%","+/-10%","+/-1.0%"]},answer:0,explain:{vi:"1,96 x căn(0,25 / 400) = 1,96 x 0,025 ≈ 4,9%.",en:"1.96 x sqrt(0.25 / 400) = 1.96 x 0.025 = about 4.9%."}},{q:{vi:"Khách hàng đề nghị bỏ bớt người trả lời nông thôn để concept vượt chuẩn ra mắt. Bạn làm gì?",en:"The client asks to drop rural respondents so the concept clears the launch standard. What do you do?"},options:{vi:["Bỏ một phần cho cân đối","Làm theo vì khách trả tiền","Từ chối, báo cáo đúng số gia quyền và đề xuất nghiên cứu bổ sung","Ghi cả hai con số và để khách chọn"],en:["Drop some for balance","Comply because the client pays","Refuse, report the correct weighted figure and propose follow-up research","Show both numbers and let the client pick"]},answer:2,explain:{vi:"Chỉnh dữ liệu theo kết luận mong muốn vi phạm chuẩn mực nghề; phải minh bạch và đề xuất phương án hợp lệ.",en:"Bending data to a desired conclusion breaches professional codes; stay transparent and propose valid options."}}]}},"KK-382":{scenario:{company:"Silverwing Expo & Events",supervisor:{name:"Lưu Đình Kiên",role:{vi:"Giám đốc Vận hành Sự kiện",en:"Event Operations Director"}},ref_code:"EVT-0619",title:{vi:"Sức chứa theo cao điểm. Lối thoát nạn không bán.",en:"Plan for the peak. Escape routes are not for sale."},brief:{vi:"Bạn hoàn thiện kế hoạch vận hành hội chợ EVT-0619 kéo dài 3 ngày. Lượng khách có mặt cùng lúc lúc cao điểm dự báo 1800 người; bản nháp chọn HALL-A dựa trên lượng khách trung bình 1100 người/ngày. Sức chứa được phép: HALL-A 1200, HALL-B 2000 (diện tích 3600 m2), HALL-C 3500 người. Bản nháp sơ đồ mặt bằng lại chia 400 gian chuẩn 3x3 m trên HALL-B. Sửa sảnh tổ chức và số gian chuẩn tối đa, rồi lập báo cáo có căn cứ.",en:"You are finalizing the operations plan for 3-day trade fair EVT-0619. Forecast peak simultaneous attendance is 1800 people; the draft picks HALL-A based on an average of 1100 visitors per day. Permitted capacity: HALL-A 1200, HALL-B 2000 (3600 m2 floor), HALL-C 3500 people. The draft floor plan also fits 400 standard 3x3 m booths in HALL-B. Correct the venue hall and the maximum standard booth count, then write an evidence-based report."},reference_title:{vi:"Phương án mặt bằng & sức chứa đã duyệt · EVT-0619",en:"Approved floor plan & capacity plan · EVT-0619"},fields:[{id:"HALL",label:{vi:"Sảnh tổ chức",en:"Venue hall"},initial:"HALL-A",expected:"HALL-B",choices:["HALL-A","HALL-B","HALL-C"],reference:"Bảng sức chứa sảnh",hint:{vi:"Chọn sảnh nhỏ nhất có sức chứa ít nhất bằng lượng khách cao điểm cùng lúc cộng biên an toàn 10%.",en:"Pick the smallest hall whose capacity covers peak simultaneous attendance plus a 10% safety margin."}},{id:"BOOTHS",label:{vi:"Số gian chuẩn 3x3 m tối đa",en:"Maximum standard 3x3 m booths"},initial:"400",expected:"220",reference:"Quy chuẩn mặt bằng triển lãm",ref_value:{vi:"HALL-B 3600 m2; tỷ lệ diện tích được bán gian 55%; gian chuẩn 9 m2",en:"HALL-B 3600 m2; sellable booth area ratio 55%; standard booth 9 m2"},hint:{vi:"Không chia cả diện tích sảnh cho diện tích gian; phải trừ lối đi, lối thoát nạn và khu dịch vụ trước.",en:"Do not divide the whole hall by the booth size; deduct aisles, escape routes and service areas first."}}],sop32:{vi:"Diện tích bán gian tối đa = 55% diện tích sảnh (45% dành cho lối đi, lối thoát nạn, khu dịch vụ); số gian chuẩn = phần nguyên của diện tích bán gian / 9 m2 (tỷ lệ là số liệu mô phỏng).",en:"Maximum sellable area = 55% of hall floor (45% kept for aisles, escape routes and services); standard booths = whole number of sellable area / 9 m2 (ratios are training data)."},context:{label:"EVENT OPS PLAN / EVT-0619",metrics:[{label:{vi:"Khách cao điểm cùng lúc",en:"Peak simultaneous visitors"},value:"1800"},{label:{vi:"Diện tích HALL-B",en:"HALL-B floor area"},value:"3600 m2"},{label:{vi:"Biên an toàn sức chứa",en:"Capacity safety margin"},value:"10%"}]},crisis:{vi:"Trưởng ban tổ chức phía khách hàng nhắn: “Chen thêm 30 gian vào lối thoát nạn và hành lang đi, đoàn kiểm tra phòng cháy chỉ đến sáng khai mạc, kiểm xong mình kê gian lại ngay.”",en:"The client's organizing chief messages you: “Squeeze 30 more booths into the escape routes and corridors, the fire inspectors only come on opening morning, we will put the booths back right after.”"},options:{safe:{vi:"Giữ mặt bằng đã duyệt, không đặt gian trên lối thoát nạn, báo Giám đốc Vận hành; đề xuất danh sách chờ, nhà bạt ngoài trời có phê duyệt riêng hoặc chuyển phần mở rộng sang HALL-C.",en:"Keep the approved layout, place no booth on escape routes and inform the Operations Director; propose a waitlist, a separately approved outdoor pavilion or an extension in HALL-C."},shortcut:{vi:"Kê thêm 30 gian sau khi đoàn kiểm tra rời đi để tăng doanh thu cho khách hàng.",en:"Add the 30 booths after the inspectors leave to raise the client's revenue."},wait:{vi:"Không trả lời và để nhà thầu dựng gian tự quyết vị trí theo yêu cầu khách.",en:"Do not reply and let the stand contractor place booths as the client wishes."}},questions:{vi:["Vì sao phải chọn HALL-B thay vì HALL-A? Hãy dùng lượng khách cao điểm, biên an toàn và sức chứa từng sảnh.","Trình bày cách tính 220 gian chuẩn và hậu quả nếu đặt gian trên lối thoát nạn khi có sự cố cháy hoặc chen lấn."],en:["Why must HALL-B be chosen instead of HALL-A? Use peak attendance, the safety margin and each hall's capacity.","Explain how you reached 220 standard booths and the consequences of booths on escape routes in a fire or crowd surge."]},hints:{vi:["So sức chứa với lượng khách có mặt cùng lúc lúc cao điểm, không phải lượng khách trung bình cả ngày.","Theo SOP mục 3.2, tính diện tích được bán gian trước rồi mới chia cho diện tích một gian chuẩn.","Đọc SOP mục 4.2: lối thoát nạn và phương án phòng cháy đã duyệt không được thay đổi để tăng doanh thu."],en:["Compare capacity with peak simultaneous attendance, not the daily average.","Per SOP 3.2, compute the sellable area first, then divide by one standard booth.","Read SOP 4.2: approved escape routes and fire safety plans must never change to raise revenue."]}},learning:{summary:{vi:"Chuyên viên Tổ chức sự kiện & Hội chợ triển lãm lên kế hoạch và điều phối trọn vòng đời sự kiện: mục tiêu, ngân sách, địa điểm, mặt bằng, nhà thầu, thủ tục pháp lý, an toàn, khách tham dự và đánh giá sau sự kiện. Nghề đòi hỏi tư duy vận hành theo mốc thời gian, tính toán sức chứa và diện tích chính xác, quản trị rủi ro đám đông, phòng cháy và giữ vững nguyên tắc an toàn trước áp lực doanh thu.",en:"An Event & Exhibition Manager plans and coordinates the full event lifecycle: objectives, budget, venue, floor plan, contractors, permits, safety, attendees and post-event evaluation. The role requires timeline-driven operations, accurate capacity and space calculations, crowd and fire risk management and firm safety principles under revenue pressure."},responsibilities:{vi:["Xác định mục tiêu, quy mô, ngân sách và điểm hòa vốn của sự kiện.","Chọn địa điểm, thiết kế mặt bằng, luồng khách và phương án sức chứa.","Lập tiến độ tổng (critical path), kịch bản chương trình và phân công nhân sự.","Quản lý nhà thầu dựng gian, âm thanh ánh sáng, an ninh, vệ sinh và hợp đồng.","Làm thủ tục đăng ký, phương án an toàn phòng cháy, y tế và đánh giá sau sự kiện."],en:["Set event objectives, scale, budget and break-even point.","Select the venue and design the floor plan, visitor flow and capacity plan.","Build the master timeline (critical path), run of show and staffing plan.","Manage stand builders, AV, security, cleaning contractors and contracts.","Handle registrations, fire safety and medical plans and post-event evaluation."]},competencies:[{name:{vi:"Lập kế hoạch vận hành",en:"Operations planning"},desc:{vi:"Chia sự kiện thành hạng mục, mốc thời gian, phụ thuộc và người chịu trách nhiệm.",en:"Break the event into workstreams, milestones, dependencies and owners."}},{name:{vi:"Tính toán sức chứa & mặt bằng",en:"Capacity & space planning"},desc:{vi:"Tính sức chứa theo cao điểm, diện tích bán gian, chiều rộng lối đi và lối thoát nạn.",en:"Compute peak capacity, sellable area, aisle widths and escape routes."}},{name:{vi:"Quản lý nhà thầu & ngân sách",en:"Contractor & budget control"},desc:{vi:"Đấu thầu, so sánh báo giá, kiểm soát phát sinh và nghiệm thu đúng hợp đồng.",en:"Tender, compare quotes, control variations and accept work against contracts."}},{name:{vi:"Quản trị rủi ro & an toàn",en:"Risk & safety management"},desc:{vi:"Lập ma trận rủi ro, phương án sơ tán, y tế, thời tiết và an ninh đám đông.",en:"Build risk matrices and evacuation, medical, weather and crowd security plans."}},{name:{vi:"Xử lý tình huống tại chỗ",en:"On-site problem solving"},desc:{vi:"Giữ bình tĩnh, ưu tiên an toàn và ra quyết định nhanh có ghi nhận khi sự cố xảy ra.",en:"Stay calm, put safety first and make fast, documented decisions when incidents occur."}}],knowledge:{vi:["Luật Thương mại số 36/2005/QH11 và Nghị định 81/2018/NĐ-CP về xúc tiến thương mại, gồm đăng ký tổ chức hội chợ, triển lãm thương mại.","Quy định hiện hành về phòng cháy, chữa cháy và cứu nạn, cứu hộ đối với nơi tập trung đông người.","Nguyên tắc quản lý đám đông: mật độ, luồng di chuyển, điểm nghẽn, chiều rộng và số lối thoát nạn.","ISO 20121 về hệ thống quản lý tính bền vững của sự kiện.","Quản trị dự án sự kiện: đường găng, kịch bản chương trình, ngân sách và điểm hòa vốn."],en:["Commercial Law No. 36/2005/QH11 and Decree 81/2018/ND-CP on trade promotion, including trade fair and exhibition registration.","Current fire prevention, firefighting and rescue regulations for crowded venues.","Crowd management principles: density, flow, bottlenecks, escape route width and count.","ISO 20121 on event sustainability management systems.","Event project management: critical path, run of show, budget and break-even."]},tools:["Phần mềm thiết kế mặt bằng (CAD)","Phần mềm quản lý dự án / Gantt","Hệ thống đăng ký & check-in khách","Bộ đàm & ứng dụng điều phối hiện trường","Microsoft Excel"],kpis:{vi:["Tỷ lệ diện tích bán gian đạt kế hoạch trong giới hạn an toàn.","Lượng khách thực tế so với dự báo và mức hài lòng của nhà triển lãm.","Chi phí thực tế so với ngân sách đã duyệt.","Số sự cố an toàn, vi phạm phòng cháy (mục tiêu bằng 0)."],en:["Sellable space sold versus plan within safety limits.","Actual versus forecast attendance and exhibitor satisfaction.","Actual cost versus approved budget.","Safety incidents and fire code breaches (target zero)."]},day:[{time:"07:00",vi:"Họp giao ban hiện trường với nhà thầu, an ninh, y tế và kiểm tra lối thoát nạn.",en:"Hold the on-site briefing with contractors, security and medics and check escape routes."},{time:"09:00",vi:"Mở cửa đón khách, theo dõi mật độ tại cổng và điều tiết luồng vào.",en:"Open doors, monitor gate density and regulate inbound flow."},{time:"12:00",vi:"Xử lý yêu cầu phát sinh của nhà triển lãm về điện, nước, vị trí gian.",en:"Handle exhibitor requests on power, water and booth positions."},{time:"15:00",vi:"Rà soát lượng khách theo giờ và điều chỉnh nhân sự cho giờ cao điểm.",en:"Review hourly attendance and adjust staffing for the peak."},{time:"19:00",vi:"Đóng cửa, họp rút kinh nghiệm ngày, cập nhật nhật ký sự cố và kế hoạch ngày mai.",en:"Close doors, run the daily debrief and update the incident log and tomorrow's plan."}],mistakes:{vi:["Chọn địa điểm theo lượng khách trung bình thay vì lượng khách có mặt cùng lúc lúc cao điểm.","Bán gian trên toàn bộ diện tích sảnh, bỏ qua lối đi và lối thoát nạn.","Thay đổi mặt bằng sau khi đã được duyệt phương án phòng cháy để tăng doanh thu."],en:["Choosing a venue by average attendance instead of peak simultaneous attendance.","Selling booths across the whole hall, ignoring aisles and escape routes.","Changing the floor plan after fire safety approval to earn more revenue."]},career:[{vi:"Điều phối viên sự kiện",en:"Event Coordinator"},{vi:"Chuyên viên Tổ chức sự kiện & Hội chợ triển lãm",en:"Event & Exhibition Manager"},{vi:"Quản lý dự án sự kiện cấp cao",en:"Senior Event Project Manager"},{vi:"Giám đốc Sự kiện & Triển lãm",en:"Director of Events & Exhibitions"}],glossary:[{term:"Shell scheme",vi:"Gian hàng tiêu chuẩn dựng sẵn gồm vách, bảng tên, đèn và ổ điện cơ bản.",en:"A pre-built standard booth with walls, fascia name board, lights and a basic socket."},{term:"Raw space",vi:"Diện tích trống thuê nguyên trạng, nhà triển lãm tự thiết kế và dựng gian theo bản vẽ được duyệt.",en:"Bare floor space where the exhibitor designs and builds a stand from approved drawings."},{term:"Run of show",vi:"Kịch bản vận hành chi tiết theo phút cho từng hạng mục chương trình.",en:"A minute-by-minute operating script for every program item."},{term:"Peak occupancy",vi:"Số người có mặt cùng lúc nhiều nhất tại địa điểm, căn cứ tính sức chứa và lối thoát nạn.",en:"The highest number of people present at once, the basis for capacity and egress."},{term:"Move-in / move-out",vi:"Giai đoạn dựng gian, lắp đặt trước sự kiện và tháo dỡ, bàn giao mặt bằng sau sự kiện.",en:"The build-up phase before the event and the breakdown and handover after it."}],quiz:[{q:{vi:"Sảnh 2000 m2, tỷ lệ được bán gian 50%, gian chuẩn 9 m2. Số gian tối đa là bao nhiêu?",en:"A 2000 m2 hall with a 50% sellable ratio and 9 m2 booths. What is the maximum booth count?"},options:{vi:["222","200","111","100"],en:["222","200","111","100"]},answer:2,explain:{vi:"2000 x 50% = 1000 m2; 1000 / 9 = 111,1 nên tối đa 111 gian.",en:"2000 x 50% = 1000 m2; 1000 / 9 = 111.1, so at most 111 booths."}},{q:{vi:"Căn cứ đúng để chọn sức chứa địa điểm là gì?",en:"What is the right basis for choosing venue capacity?"},options:{vi:["Tổng lượt khách cả sự kiện","Lượng khách trung bình mỗi ngày","Số nhà triển lãm","Lượng khách có mặt cùng lúc lúc cao điểm cộng biên an toàn"],en:["Total visits over the event","Average daily visitors","Number of exhibitors","Peak simultaneous attendance plus a safety margin"]},answer:3,explain:{vi:"Rủi ro chen lấn và sơ tán phụ thuộc số người có mặt cùng lúc, nên phải tính theo cao điểm.",en:"Crush and evacuation risk depend on people present at once, so plan for the peak."}},{q:{vi:"Gian hàng tiêu chuẩn có sẵn vách, bảng tên và đèn gọi là gì?",en:"What is a standard booth with ready walls, fascia and lights called?"},options:{vi:["Shell scheme","Raw space","Island stand","Pop-up kiosk"],en:["Shell scheme","Raw space","Island stand","Pop-up kiosk"]},answer:0,explain:{vi:"Shell scheme là gian dựng sẵn; raw space là diện tích trống nhà triển lãm tự dựng.",en:"A shell scheme is pre-built; raw space is bare floor the exhibitor builds on."}},{q:{vi:"Khách hàng muốn kê thêm gian vào lối thoát nạn sau khi đoàn kiểm tra rời đi. Bạn làm gì?",en:"The client wants extra booths on escape routes after inspectors leave. What do you do?"},options:{vi:["Đồng ý vì chỉ trong 3 ngày","Từ chối, giữ mặt bằng đã duyệt, báo cấp trên và đề xuất phương án hợp lệ","Chỉ kê gian thấp không che biển chỉ dẫn","Để nhà thầu tự quyết"],en:["Agree since it is only 3 days","Refuse, keep the approved plan, escalate and propose valid options","Allow only low booths that do not hide signs","Let the contractor decide"]},answer:1,explain:{vi:"Lối thoát nạn bị chặn có thể gây thương vong khi sự cố; an toàn không được đánh đổi lấy doanh thu.",en:"Blocked escape routes can cause casualties in an incident; safety is never traded for revenue."}}]}},"KK-416":{scenario:{company:"Sailwind Travel Studio",supervisor:{name:"Lý Ngọc Hân",role:{vi:"Trưởng nhóm Nội dung",en:"Content Lead"}},ref_code:"CPY-5530",title:{vi:"Ảnh có quyền dùng. Con số không thổi phồng.",en:"Licensed images. Honest numbers."},brief:{vi:"Bạn duyệt bộ nội dung quảng cáo tour Đà Lạt mùa hoa CPY-5530. Banner nháp dùng ảnh IMG-204 có giấy phép chỉ dùng cho biên tập (editorial only); kho ảnh còn IMG-311 (giấy phép thương mại royalty-free, có văn bản đồng ý của người trong ảnh) và IMG-118 (giấy phép CC BY-NC). Giá niêm yết trước khuyến mại 7500000 đồng, giá khuyến mại 4800000 đồng, nhưng tiêu đề nháp ghi “Giảm 56%”. Sửa ảnh banner và mức giảm công bố (%), rồi lập báo cáo có căn cứ.",en:"You are approving ad content set CPY-5530 for a Da Lat flower season tour. The draft banner uses image IMG-204, licensed for editorial use only; the library also holds IMG-311 (commercial royalty-free license with a signed model release) and IMG-118 (CC BY-NC license). The list price before the promotion is 7500000 VND and the promo price 4800000 VND, but the draft headline says 56% off. Correct the banner image and the advertised discount (%), then write an evidence-based report."},reference_title:{vi:"Sổ giấy phép ảnh & bảng giá khuyến mại đã duyệt · CPY-5530",en:"Approved image license log & promo price sheet · CPY-5530"},fields:[{id:"BANNER_IMG",label:{vi:"Ảnh dùng cho banner quảng cáo",en:"Image used on the ad banner"},initial:"IMG-204",expected:"IMG-311",choices:["IMG-204","IMG-311","IMG-118"],reference:"Sổ giấy phép ảnh",hint:{vi:"Quảng cáo là sử dụng thương mại: ảnh chỉ dùng biên tập và ảnh giấy phép phi thương mại (NC) đều không được dùng.",en:"Advertising is commercial use: editorial-only images and non-commercial (NC) licensed images are both off-limits."}},{id:"DISCOUNT",label:{vi:"Mức giảm giá công bố (%)",en:"Advertised discount (%)"},initial:"56",expected:"36",reference:"Bảng giá khuyến mại đã duyệt",ref_value:{vi:"Giá niêm yết trước khuyến mại 7500000; giá khuyến mại 4800000 (đồng)",en:"List price before promotion 7500000; promo price 4800000 (VND)"},hint:{vi:"Mức giảm phải tính trên giá trước khuyến mại, không phải trên giá sau khi đã giảm.",en:"The discount is based on the pre-promotion price, not on the reduced price."}}],sop32:{vi:"Mức giảm công bố (%) = (giá trước khuyến mại - giá khuyến mại) / giá trước khuyến mại x 100, làm tròn xuống số nguyên; tuyệt đối không chia cho giá khuyến mại.",en:"Advertised discount (%) = (pre-promotion price - promo price) / pre-promotion price x 100, rounded down to a whole number; never divide by the promo price."},context:{label:"CONTENT HUB / CPY-5530",metrics:[{label:{vi:"Giá trước khuyến mại",en:"Pre-promotion price"},value:"7,500,000 VND"},{label:{vi:"Giá khuyến mại",en:"Promo price"},value:"4,800,000 VND"},{label:{vi:"Ảnh đang dùng",en:"Current image"},value:"IMG-204 (editorial only)"}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn: “Viết giúp 30 đánh giá 5 sao giả làm khách đã đi tour, đăng lên trang và các nhóm du lịch, thêm câu ‘tour bán chạy số 1 Đà Lạt’ cho chốt đơn nhanh.”",en:"The sales manager messages you: “Write 30 fake five-star reviews posing as past guests, post them on the page and travel groups, and add best-selling tour number 1 in Da Lat to close deals faster.”"},options:{safe:{vi:"Từ chối viết đánh giá giả và claim số 1 không có căn cứ, báo trưởng nhóm Nội dung; đề xuất thu thập đánh giá thật sau tour có đồng ý của khách và dùng số liệu kiểm chứng được.",en:"Refuse fake reviews and the unsupported number 1 claim, inform the Content Lead; propose collecting real post-tour reviews with guest consent and using verifiable figures."},shortcut:{vi:"Viết 30 đánh giá bằng tài khoản phụ và giữ câu số 1 vì đối thủ cũng ghi như vậy.",en:"Write the 30 reviews from secondary accounts and keep the number 1 line because competitors do it."},wait:{vi:"Không phản hồi, để kinh doanh tự đăng nội dung lên trang khi cần.",en:"Do not reply and let Sales post the content on the page themselves."}},questions:{vi:["Vì sao banner phải dùng IMG-311? Hãy phân tích giấy phép của cả ba ảnh trong kho.","Trình bày cách tính mức giảm 36% và rủi ro pháp lý, uy tín nếu đăng đánh giá giả hoặc con số giảm giá thổi phồng."],en:["Why must the banner use IMG-311? Analyze the license of all three library images.","Explain how you reached the 36% discount and the legal and reputational risks of fake reviews or inflated discounts."]},hints:{vi:["Mở sổ giấy phép ảnh, kiểm tra phạm vi sử dụng thương mại và văn bản đồng ý của người xuất hiện trong ảnh.","Theo SOP mục 3.2, lấy phần chênh lệch giá chia cho giá trước khuyến mại.","Đọc SOP mục 4.2: mọi đánh giá, chứng thực và claim so sánh phải có thật và có bằng chứng lưu trữ."],en:["Open the image license log and check commercial scope and model releases for people in the photo.","Per SOP 3.2, divide the price difference by the pre-promotion price.","Read SOP 4.2: every review, testimonial and comparative claim must be genuine and evidenced."]}},learning:{summary:{vi:"Chuyên viên Sáng tạo nội dung đa phương tiện & Copywriting xây chiến lược nội dung và viết thông điệp cho website, quảng cáo, mạng xã hội, email, video và bao bì, giúp thương hiệu được hiểu đúng, được nhớ và thúc đẩy hành động. Nghề đòi hỏi thấu hiểu khách hàng, giọng điệu thương hiệu nhất quán, kỹ năng viết theo kênh, tư duy đo lường và hiểu biết về bản quyền, quảng cáo trung thực.",en:"A Content Strategist & Copywriter builds content strategy and writes messages for websites, ads, social media, email, video and packaging so a brand is understood, remembered and acted on. The role requires audience insight, a consistent brand voice, channel-specific writing, measurement thinking and knowledge of copyright and truthful advertising."},responsibilities:{vi:["Xây trụ cột nội dung, lịch biên tập và bản đồ nội dung theo hành trình khách hàng.","Viết tiêu đề, thông điệp quảng cáo, kịch bản video, email và nội dung trang đích.","Giữ giọng điệu thương hiệu nhất quán và biên tập nội dung của cộng tác viên.","Kiểm tra bản quyền hình ảnh, âm nhạc, nguồn trích dẫn và tính trung thực của claim.","Đo hiệu quả nội dung, thử nghiệm tiêu đề và tối ưu theo dữ liệu."],en:["Build content pillars, an editorial calendar and a journey-based content map.","Write headlines, ad copy, video scripts, emails and landing page content.","Keep the brand voice consistent and edit contributors' content.","Check rights for images, music and quoted sources and the truthfulness of claims.","Measure content performance, test headlines and optimize from data."]},competencies:[{name:{vi:"Viết thuyết phục",en:"Persuasive writing"},desc:{vi:"Vận dụng AIDA, PAS, 4U để viết ngắn, rõ, có lợi ích và lời kêu gọi hành động cụ thể.",en:"Apply AIDA, PAS and 4U to write short, clear, benefit-led copy with a specific call to action."}},{name:{vi:"Chiến lược nội dung",en:"Content strategy"},desc:{vi:"Gắn nội dung với mục tiêu kinh doanh, chân dung khách hàng và từng giai đoạn phễu.",en:"Tie content to business goals, audience personas and each funnel stage."}},{name:{vi:"Giọng điệu thương hiệu",en:"Brand voice"},desc:{vi:"Giữ cách nói nhất quán trên mọi kênh nhưng vẫn phù hợp định dạng từng nền tảng.",en:"Keep one consistent voice across channels while fitting each platform's format."}},{name:{vi:"Bản quyền & quảng cáo trung thực",en:"Rights & truthful advertising"},desc:{vi:"Dùng tài nguyên có giấy phép đúng phạm vi, claim có bằng chứng và con số chính xác.",en:"Use assets within license scope, substantiate claims and keep numbers accurate."}},{name:{vi:"Đo lường nội dung",en:"Content measurement"},desc:{vi:"Đọc tỷ lệ nhấp, thời gian đọc, chuyển đổi và rút bài học cho bản tiếp theo.",en:"Read click rates, reading time and conversions and feed learnings into the next draft."}}],knowledge:{vi:["Luật Quảng cáo số 16/2012/QH13 và các văn bản sửa đổi, hướng dẫn về nội dung quảng cáo.","Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15: nghĩa vụ cung cấp thông tin trung thực, chính xác.","Luật Sở hữu trí tuệ về quyền tác giả; các loại giấy phép ảnh: royalty-free, rights-managed, editorial only, Creative Commons.","Quy định về thông tin khuyến mại theo Nghị định 81/2018/NĐ-CP về xúc tiến thương mại.","Khung viết AIDA, PAS, 4U; trụ cột nội dung và phễu TOFU, MOFU, BOFU.","Nguyên tắc khả năng tiếp cận WCAG 2.2 như văn bản thay thế ảnh và độ tương phản."],en:["Advertising Law No. 16/2012/QH13 with its amendments and guidance on ad content.","Consumer Rights Protection Law No. 19/2023/QH15: duty to provide truthful, accurate information.","Intellectual Property Law on copyright; image license types: royalty-free, rights-managed, editorial only, Creative Commons.","Promotion information rules under Decree 81/2018/ND-CP on trade promotion.","Writing frameworks AIDA, PAS, 4U; content pillars and the TOFU, MOFU, BOFU funnel.","WCAG 2.2 accessibility principles such as image alt text and color contrast."]},tools:["Hệ quản trị nội dung (CMS)","Kho ảnh có giấy phép (stock library)","Công cụ thiết kế & dựng video","Công cụ kiểm tra chính tả, đạo văn","Lịch biên tập (Notion / Trello)","Công cụ phân tích web (GA4)"],kpis:{vi:["Tỷ lệ nhấp và tỷ lệ chuyển đổi của nội dung quảng cáo, trang đích.","Thời gian đọc, tỷ lệ cuộn trang và mức tương tác trên mạng xã hội.","Tỷ lệ nội dung giao đúng hạn theo lịch biên tập.","Số vi phạm bản quyền hoặc claim bị khiếu nại (mục tiêu bằng 0)."],en:["Click-through and conversion rates of ad copy and landing pages.","Reading time, scroll depth and social engagement.","Share of content delivered on time against the editorial calendar.","Copyright breaches or challenged claims (target zero)."]},day:[{time:"08:30",vi:"Đọc số liệu nội dung hôm qua: tiêu đề nào được nhấp, bài nào giữ chân người đọc.",en:"Read yesterday's content data: which headlines got clicks and which posts held readers."},{time:"09:30",vi:"Nhận brief chiến dịch, phỏng vấn nhanh đội tour để lấy chi tiết thật về trải nghiệm.",en:"Take the campaign brief and quickly interview the tour team for real experience details."},{time:"11:00",vi:"Viết 3 phương án tiêu đề, nội dung trang đích và kịch bản video ngắn.",en:"Write 3 headline options, landing page copy and a short video script."},{time:"14:00",vi:"Kiểm tra giấy phép ảnh, giá khuyến mại và mọi con số trong bài trước khi gửi duyệt.",en:"Check image licenses, promo prices and every number in the copy before review."},{time:"16:30",vi:"Chỉnh sửa theo phản hồi, lên lịch đăng và cài thử nghiệm A/B tiêu đề.",en:"Revise from feedback, schedule posts and set up a headline A/B test."}],mistakes:{vi:["Dùng ảnh chỉ dành cho biên tập hoặc ảnh giấy phép phi thương mại cho quảng cáo.","Tính phần trăm giảm giá trên giá khuyến mại làm con số bị thổi phồng.","Viết đánh giá, chứng thực giả hoặc claim “số 1” không có dữ liệu chứng minh."],en:["Using editorial-only or non-commercial licensed images in ads.","Computing the discount on the promo price, inflating the number.","Writing fake reviews or testimonials or number 1 claims without supporting data."]},career:[{vi:"Cộng tác viên / nhân viên viết nội dung",en:"Content Writer"},{vi:"Chuyên viên Copywriting & Chiến lược nội dung",en:"Content Strategist & Copywriter"},{vi:"Trưởng nhóm Nội dung / Senior Copywriter",en:"Content Lead / Senior Copywriter"},{vi:"Giám đốc Sáng tạo / Giám đốc Nội dung",en:"Creative Director / Head of Content"}],glossary:[{term:"Editorial only",vi:"Giấy phép chỉ cho phép dùng ảnh minh họa tin tức, bài viết, không dùng cho quảng cáo, bán hàng.",en:"A license allowing use only to illustrate news or articles, never for advertising or sales."},{term:"Model release",vi:"Văn bản đồng ý của người xuất hiện trong ảnh cho phép dùng hình ảnh của họ vào mục đích thương mại.",en:"A signed consent from a person in a photo allowing commercial use of their image."},{term:"AIDA",vi:"Khung viết theo trình tự Chú ý, Quan tâm, Mong muốn, Hành động.",en:"A copy framework: Attention, Interest, Desire, Action."},{term:"Content pillar",vi:"Chủ đề nội dung cốt lõi mà thương hiệu xây dựng lâu dài, gắn với giá trị và nhu cầu khách hàng.",en:"A core content theme the brand builds over time, tied to its value and audience needs."},{term:"CTA",vi:"Lời kêu gọi hành động cụ thể như đặt tour, đăng ký, nhận tư vấn.",en:"A call to action such as book the tour, sign up or get advice."}],quiz:[{q:{vi:"Giá trước khuyến mại 4000000 đồng, giá khuyến mại 3000000 đồng. Mức giảm công bố đúng là bao nhiêu?",en:"The pre-promotion price is 4000000 VND and the promo price 3000000 VND. What is the correct advertised discount?"},options:{vi:["33%","30%","25%","75%"],en:["33%","30%","25%","75%"]},answer:2,explain:{vi:"(4000000 - 3000000) / 4000000 = 25%; chia cho giá khuyến mại sẽ ra con số sai 33%.",en:"(4000000 - 3000000) / 4000000 = 25%; dividing by the promo price gives the wrong 33%."}},{q:{vi:"Ảnh có giấy phép CC BY-NC có được dùng cho banner quảng cáo bán tour không?",en:"Can a CC BY-NC licensed image be used on a banner selling tours?"},options:{vi:["Có, nếu ghi tên tác giả","Có, nếu chỉnh màu ảnh","Có, nếu chỉ chạy một tuần","Không, vì NC cấm sử dụng thương mại"],en:["Yes, with author credit","Yes, if colors are edited","Yes, if it runs only one week","No, because NC forbids commercial use"]},answer:3,explain:{vi:"NC (NonCommercial) loại trừ mục đích thương mại; ghi công tác giả không thay đổi điều đó.",en:"NC (NonCommercial) excludes commercial use; crediting the author does not change that."}},{q:{vi:"Khung viết PAS gồm những bước nào?",en:"What are the steps of the PAS framework?"},options:{vi:["Vấn đề, Khuấy động, Giải pháp","Giá, Ưu đãi, Bán hàng","Kế hoạch, Hành động, Đo lường","Mục đích, Khán giả, Phong cách"],en:["Problem, Agitate, Solution","Price, Offer, Sale","Plan, Act, Measure","Purpose, Audience, Style"]},answer:0,explain:{vi:"PAS nêu vấn đề, làm rõ hệ quả để khách cảm nhận, rồi đưa giải pháp.",en:"PAS states the problem, agitates its impact, then offers the solution."}},{q:{vi:"Cấp trên yêu cầu viết đánh giá 5 sao giả danh khách hàng. Bạn làm gì?",en:"A manager asks you to write five-star reviews posing as customers. What do you do?"},options:{vi:["Viết bằng tài khoản ẩn danh","Từ chối, báo trưởng nhóm và đề xuất thu thập đánh giá thật","Viết nhưng chỉ đăng ở nhóm kín","Thuê người khác viết"],en:["Write them from anonymous accounts","Refuse, inform the lead and propose collecting real reviews","Write them but post only in closed groups","Hire someone else to write them"]},answer:1,explain:{vi:"Đánh giá giả lừa dối người tiêu dùng và làm mất uy tín thương hiệu; chỉ dùng đánh giá thật có đồng ý.",en:"Fake reviews deceive consumers and damage the brand; use only real, consented reviews."}}]}},"KK-417":{scenario:{company:"Meadowpure Dairy",supervisor:{name:"Mai Phương Thảo",role:{vi:"Giám đốc Truyền thông Doanh nghiệp",en:"Corporate Communications Director"}},ref_code:"CRS-0907",title:{vi:"An toàn người tiêu dùng trước, hình ảnh sau.",en:"Consumer safety first, image second."},brief:{vi:"Bạn rà soát báo cáo tình huống CRS-0907. Từ 08:00 đã có 14 người tiêu dùng phản ánh đau bụng sau khi uống sữa chua uống lô L2409-B; cơ quan y tế địa phương đã lấy mẫu, chưa có kết quả. Bản nháp xếp mức SEV-3. Công cụ lắng nghe mạng xã hội thu 5600 đề cập, trong đó 1600 là bản trùng lặp hoặc tài khoản ảo đã xác minh; số đề cập tiêu cực hợp lệ là 1400. Sửa mức khủng hoảng và tỷ lệ đề cập tiêu cực (%), rồi lập báo cáo có căn cứ.",en:"You are reviewing situation report CRS-0907. Since 08:00, 14 consumers have reported stomach pain after drinking yogurt drink batch L2409-B; the local health authority has taken samples, results pending. The draft rates it SEV-3. Social listening captured 5600 mentions, of which 1600 are verified duplicates or fake accounts; valid negative mentions total 1400. Correct the crisis level and the negative mention share (%), then write an evidence-based report."},reference_title:{vi:"Ma trận phân cấp khủng hoảng & báo cáo lắng nghe đã duyệt · CRS-0907",en:"Approved crisis matrix & listening report · CRS-0907"},fields:[{id:"SEVERITY",label:{vi:"Mức khủng hoảng",en:"Crisis level"},initial:"SEV-3",expected:"SEV-1",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân cấp khủng hoảng",hint:{vi:"SEV-1 khi có nguy cơ sức khỏe người tiêu dùng hoặc cơ quan quản lý vào cuộc; SEV-2 uy tín lan truyền không yếu tố an toàn; SEV-3 phàn nàn đơn lẻ.",en:"SEV-1 when consumer health is at risk or a regulator is involved; SEV-2 viral reputation issue with no safety factor; SEV-3 isolated complaint."}},{id:"NEG_SHARE",label:{vi:"Tỷ lệ đề cập tiêu cực (%)",en:"Negative mention share (%)"},initial:"25",expected:"35",reference:"Báo cáo lắng nghe mạng xã hội",ref_value:{vi:"Thu được 5600; trùng lặp, tài khoản ảo 1600; tiêu cực hợp lệ 1400",en:"Captured 5600; duplicates and fake accounts 1600; valid negatives 1400"},hint:{vi:"Làm sạch dữ liệu trước khi tính: mẫu số chỉ gồm đề cập hợp lệ, không gồm bản trùng và tài khoản ảo.",en:"Clean the data before computing: the denominator holds only valid mentions, no duplicates or fake accounts."}}],sop32:{vi:"Tỷ lệ đề cập tiêu cực (%) = đề cập tiêu cực hợp lệ / (tổng đề cập thu được - trùng lặp và tài khoản ảo) x 100. Tình huống SEV-1 phải có thông cáo chờ trong 2 giờ.",en:"Negative share (%) = valid negative mentions / (total captured - duplicates and fake accounts) x 100. A SEV-1 case needs a holding statement within 2 hours."},context:{label:"CRISIS ROOM / CRS-0907",metrics:[{label:{vi:"Ca phản ánh sức khỏe",en:"Health complaints"},value:"14"},{label:{vi:"Đề cập thu được / loại bỏ",en:"Mentions captured / removed"},value:"5600 / 1600"},{label:{vi:"Lô sản phẩm",en:"Product batch"},value:"L2409-B"}]},crisis:{vi:"Tổng giám đốc nhắn: “Ra thông cáo khẳng định sản phẩm an toàn tuyệt đối, do khách bảo quản sai. Gọi trang tin kia gỡ bài, đổi lại cho họ hợp đồng quảng cáo, và thuê tài khoản ảo bình luận tích cực cho chìm tin.”",en:"The CEO messages you: “Issue a statement that the product is absolutely safe and customers stored it wrong. Get that news site to take the story down in exchange for an ad contract, and hire fake accounts to bury it with positive comments.”"},options:{safe:{vi:"Không khẳng định an toàn khi chưa có kết quả, không đổ lỗi khách hàng, không mua gỡ bài hay dùng tài khoản ảo; báo Giám đốc Truyền thông, pháp chế và đề xuất thông cáo chờ, tạm dừng bán lô L2409-B, mở đường dây nóng.",en:"Do not claim safety before results, blame customers, pay for takedowns or use fake accounts; inform the Comms Director and Legal and propose a holding statement, a sales hold on batch L2409-B and a hotline."},shortcut:{vi:"Phát thông cáo khẳng định an toàn và cho chạy tài khoản ảo bình luận tích cực để chặn tin xấu.",en:"Issue the safety statement and run fake accounts with positive comments to stop the bad news."},wait:{vi:"Im lặng chờ kết quả kiểm nghiệm rồi mới lên tiếng, không trả lời báo chí.",en:"Stay silent until test results arrive and do not answer the press."}},questions:{vi:["Vì sao CRS-0907 phải nâng lên SEV-1? Hãy dẫn số ca phản ánh sức khỏe và việc cơ quan y tế lấy mẫu.","Trình bày cách tính tỷ lệ tiêu cực 35% và rủi ro nếu khẳng định an toàn sớm, mua gỡ bài hoặc dùng tài khoản ảo."],en:["Why must CRS-0907 be raised to SEV-1? Cite the health complaints and the authority's sampling.","Explain how you reached the 35% negative share and the risks of early safety claims, paid takedowns or fake accounts."]},hints:{vi:["Đối chiếu dữ kiện với ma trận phân cấp: có yếu tố sức khỏe và cơ quan quản lý hay không.","Theo SOP mục 3.2, loại bản trùng và tài khoản ảo khỏi mẫu số trước khi chia.","Đọc SOP mục 4.2: thông tin công bố phải trung thực, mọi yêu cầu che giấu hay thao túng dư luận phải được báo cáo."],en:["Match the facts to the crisis matrix: is there a health factor and regulator involvement?","Per SOP 3.2, remove duplicates and fake accounts from the denominator before dividing.","Read SOP 4.2: public statements must be truthful and any request to conceal or manipulate opinion must be escalated."]}},learning:{summary:{vi:"Chuyên viên Quan hệ công chúng & Xử lý khủng hoảng truyền thông xây dựng và bảo vệ uy tín tổ chức: quan hệ báo chí, thông cáo, phát ngôn, sự kiện truyền thông, lắng nghe dư luận và điều phối phản ứng khi khủng hoảng. Nghề đòi hỏi phán đoán nhanh mức độ nghiêm trọng, viết rõ ràng dưới áp lực, phối hợp pháp chế, chất lượng, ban lãnh đạo và giữ nguyên tắc trung thực, đặt an toàn công chúng lên trước hình ảnh.",en:"A PR & Crisis Communications Specialist builds and protects an organization's reputation: media relations, press releases, spokesperson support, media events, opinion monitoring and coordinating the response when a crisis hits. The role requires fast severity judgment, clear writing under pressure, coordination with Legal, QA and leadership, and a firm commitment to honesty that puts public safety before image."},responsibilities:{vi:["Xây kế hoạch PR, thông điệp chủ chốt và quan hệ với cơ quan báo chí.","Viết thông cáo báo chí, bộ hỏi đáp và chuẩn bị người phát ngôn.","Theo dõi báo chí, mạng xã hội, phát hiện sớm tín hiệu khủng hoảng.","Kích hoạt quy trình khủng hoảng: phân cấp, thông cáo chờ, điều phối nhóm xử lý.","Đo lường hiệu quả truyền thông theo kết quả và rút kinh nghiệm sau sự cố."],en:["Build PR plans, key messages and relationships with media outlets.","Write press releases and Q&A documents and prepare spokespeople.","Monitor press and social media to detect early crisis signals.","Activate the crisis process: severity rating, holding statement, response team coordination.","Measure communication by outcomes and run post-incident reviews."]},competencies:[{name:{vi:"Phán đoán khủng hoảng",en:"Crisis judgment"},desc:{vi:"Đánh giá nhanh mức nghiêm trọng, đối tượng bị ảnh hưởng và quyết định thời điểm lên tiếng.",en:"Quickly assess severity and affected audiences and decide when to speak."}},{name:{vi:"Viết dưới áp lực",en:"Writing under pressure"},desc:{vi:"Soạn thông cáo, tuyên bố ngắn gọn, đúng sự thật, thể hiện trách nhiệm và hành động cụ thể.",en:"Draft concise, factual statements that show responsibility and concrete action."}},{name:{vi:"Quan hệ báo chí",en:"Media relations"},desc:{vi:"Xây quan hệ chuyên nghiệp, cung cấp thông tin kịp thời và tôn trọng tính độc lập của báo chí.",en:"Build professional relationships, provide timely information and respect press independence."}},{name:{vi:"Lắng nghe & phân tích dư luận",en:"Listening & sentiment analysis"},desc:{vi:"Làm sạch dữ liệu đề cập, phân tích cảm xúc, chủ đề và nguồn lan truyền.",en:"Clean mention data and analyze sentiment, themes and spread sources."}},{name:{vi:"Liêm chính truyền thông",en:"Communication integrity"},desc:{vi:"Từ chối che giấu, đổ lỗi, mua gỡ bài hay thao túng dư luận bằng tài khoản ảo.",en:"Refuse concealment, blame-shifting, paid takedowns and astroturfing with fake accounts."}}],knowledge:{vi:["Lý thuyết truyền thông khủng hoảng tình huống (SCCT) của Coombs và nguyên tắc phản hồi theo mức trách nhiệm.","Bộ nguyên tắc Barcelona 3.0 (AMEC) về đo lường truyền thông, không dùng AVE.","Luật Báo chí số 103/2016/QH13, quyền cải chính, phản hồi thông tin.","Luật An toàn thực phẩm số 55/2010/QH12 về trách nhiệm thu hồi, xử lý thực phẩm không an toàn.","Cấu trúc thông cáo báo chí kim tự tháp ngược, bộ hỏi đáp và kỹ năng phát ngôn."],en:["Coombs' Situational Crisis Communication Theory (SCCT) and responses matched to responsibility.","The Barcelona Principles 3.0 (AMEC) on communication measurement, rejecting AVE.","Press Law No. 103/2016/QH13 and the rights of correction and reply.","Food Safety Law No. 55/2010/QH12 on recalling and handling unsafe food.","Inverted pyramid press releases, Q&A documents and spokesperson skills."]},tools:["Công cụ lắng nghe mạng xã hội (social listening)","Hệ thống theo dõi báo chí","Danh bạ & CRM quan hệ báo chí","Sổ tay xử lý khủng hoảng (crisis playbook)","Kênh liên lạc khẩn cấp của nhóm xử lý","Microsoft Word / PowerPoint"],kpis:{vi:["Thời gian từ khi phát hiện đến thông cáo chờ ở tình huống SEV-1.","Tỷ lệ tin bài phản ánh đúng thông điệp chủ chốt và thông tin chính xác.","Xu hướng cảm xúc dư luận trước, trong và sau khủng hoảng.","Mức độ tin cậy của thương hiệu trong khảo sát định kỳ."],en:["Time from detection to holding statement in SEV-1 cases.","Share of coverage carrying key messages and accurate facts.","Sentiment trend before, during and after a crisis.","Brand trust score in periodic surveys."]},day:[{time:"07:30",vi:"Đọc bản tin theo dõi báo chí, mạng xã hội qua đêm và cảnh báo đề cập tăng đột biến.",en:"Read the overnight press and social monitoring digest and spike alerts."},{time:"09:00",vi:"Họp nhóm xử lý khủng hoảng với chất lượng, pháp chế, chăm sóc khách hàng.",en:"Meet the crisis team with QA, Legal and Customer Care."},{time:"10:30",vi:"Soạn thông cáo chờ, bộ hỏi đáp và gửi lãnh đạo duyệt.",en:"Draft the holding statement and Q&A and send them to leadership for approval."},{time:"14:00",vi:"Trả lời phóng viên, chuẩn bị người phát ngôn cho buổi làm việc với báo chí.",en:"Answer reporters and prepare the spokesperson for the media session."},{time:"17:30",vi:"Cập nhật báo cáo tình huống, chỉ số lắng nghe và kế hoạch truyền thông ngày mai.",en:"Update the situation report, listening metrics and tomorrow's communication plan."}],mistakes:{vi:["Đánh giá thấp mức khủng hoảng khi đã có yếu tố sức khỏe, an toàn người tiêu dùng.","Tính tỷ lệ tiêu cực trên dữ liệu chưa làm sạch, làm ban lãnh đạo chủ quan.","Khẳng định vô can, đổ lỗi khách hàng hoặc tìm cách gỡ bài thay vì minh bạch và hành động."],en:["Underrating a crisis when consumer health or safety is involved.","Computing negative share on uncleaned data, making leaders complacent.","Denying responsibility, blaming customers or chasing takedowns instead of transparency and action."]},career:[{vi:"Nhân viên PR / quan hệ báo chí",en:"PR Executive"},{vi:"Chuyên viên PR & Xử lý khủng hoảng truyền thông",en:"PR & Crisis Communications Specialist"},{vi:"Quản lý Truyền thông doanh nghiệp",en:"Corporate Communications Manager"},{vi:"Giám đốc Truyền thông & Đối ngoại",en:"Director of Communications & Public Affairs"}],glossary:[{term:"Holding statement",vi:"Thông cáo chờ ngắn ban hành sớm, xác nhận sự việc, nêu hành động đang làm và thời điểm cập nhật.",en:"A short early statement confirming the issue, the actions under way and when updates will follow."},{term:"SCCT",vi:"Lý thuyết chọn chiến lược phản hồi khủng hoảng theo mức trách nhiệm công chúng gán cho tổ chức.",en:"A theory for choosing crisis responses based on the responsibility the public assigns."},{term:"Astroturfing",vi:"Tạo giả phong trào ủng hộ bằng tài khoản ảo hoặc người được trả tiền nhưng giấu danh tính.",en:"Faking grassroots support with fake accounts or undisclosed paid posters."},{term:"AVE",vi:"Giá trị quy đổi quảng cáo, cách đo PR lỗi thời bị bộ nguyên tắc Barcelona bác bỏ.",en:"Advertising value equivalency, an outdated PR metric rejected by the Barcelona Principles."},{term:"Spokesperson",vi:"Người được ủy quyền phát ngôn chính thức thay mặt tổ chức với báo chí và công chúng.",en:"The person authorized to speak officially for the organization to media and the public."}],quiz:[{q:{vi:"Thu được 3000 đề cập, loại 500 bản trùng và tài khoản ảo, có 750 đề cập tiêu cực hợp lệ. Tỷ lệ tiêu cực là bao nhiêu?",en:"3000 mentions captured, 500 duplicates and fake accounts removed, 750 valid negatives. What is the negative share?"},options:{vi:["25%","20%","15%","30%"],en:["25%","20%","15%","30%"]},answer:3,explain:{vi:"750 / (3000 - 500) = 750 / 2500 = 30%; chia cho 3000 sẽ ra con số sai 25%.",en:"750 / (3000 - 500) = 750 / 2500 = 30%; dividing by 3000 gives the wrong 25%."}},{q:{vi:"Thông cáo chờ (holding statement) cần có nội dung gì?",en:"What should a holding statement contain?"},options:{vi:["Khẳng định không có lỗi","Xác nhận sự việc, hành động đang làm và thời điểm cập nhật","Toàn bộ chi tiết điều tra nội bộ","Lời cảm ơn nhà tài trợ"],en:["A claim of no fault","Confirmation of the issue, actions under way and the next update time","All internal investigation details","Thanks to sponsors"]},answer:1,explain:{vi:"Thông cáo chờ thể hiện tổ chức biết, đang hành động và sẽ cập nhật, không phán xét khi chưa đủ dữ kiện.",en:"It shows the organization knows, is acting and will update, without conclusions before the facts."}},{q:{vi:"Theo bộ nguyên tắc Barcelona, chỉ số nào không nên dùng để đo giá trị PR?",en:"Under the Barcelona Principles, which metric should not measure PR value?"},options:{vi:["AVE (giá trị quy đổi quảng cáo)","Thay đổi nhận thức của công chúng","Hành vi của đối tượng mục tiêu","Kết quả kinh doanh liên quan"],en:["AVE (advertising value equivalency)","Change in public awareness","Target audience behavior","Related business outcomes"]},answer:0,explain:{vi:"Barcelona bác bỏ AVE, khuyến khích đo đầu ra, kết quả và tác động thực tế.",en:"Barcelona rejects AVE and encourages measuring outputs, outcomes and real impact."}},{q:{vi:"Lãnh đạo yêu cầu thuê tài khoản ảo bình luận tích cực để chìm tin xấu. Bạn làm gì?",en:"Leadership asks you to hire fake accounts to bury bad news with positive comments. What do you do?"},options:{vi:["Làm trong 24 giờ đầu","Chỉ dùng tài khoản nhân viên","Từ chối, báo cáo và đề xuất phản hồi minh bạch, hành động khắc phục","Thuê agency làm để tránh liên quan"],en:["Do it for the first 24 hours","Use staff accounts only","Refuse, escalate and propose transparent replies and corrective action","Outsource it to an agency to stay clear"]},answer:2,explain:{vi:"Thao túng dư luận bằng tài khoản ảo là lừa dối công chúng và làm khủng hoảng trầm trọng hơn khi bị phát hiện.",en:"Astroturfing deceives the public and deepens the crisis once exposed."}}]}},"KK-418":{scenario:{company:"Sương Mai Skincare",supervisor:{name:"Trần Thu Hà",role:{vi:"Trưởng phòng Truyền thông Số",en:"Head of Digital Communications"}},ref_code:"SM-2611",title:{vi:"Đo đúng tương tác. Xử lý đúng mức độ sự cố.",en:"Measure engagement right. Escalate at the right level."},brief:{vi:"Bạn rà soát báo cáo tuần SM-2611 của fanpage có 150.000 người theo dõi. Bài chiến dịch “Glow Week” đạt tiếp cận 62.500 người với 2.180 cảm xúc, 412 bình luận, 236 chia sẻ và 172 lượt lưu. Cùng tuần, một khách hàng đăng ảnh bị kích ứng da sau khi dùng serum, bài đã có 1.350 lượt chia sẻ. Đối chiếu báo cáo nháp với tài liệu đã duyệt, sửa mức độ sự cố và tỷ lệ tương tác, rồi lập báo cáo có căn cứ.",en:"You are reviewing weekly report SM-2611 for a fan page with 150,000 followers. The “Glow Week” campaign post reached 62,500 people with 2,180 reactions, 412 comments, 236 shares and 172 saves. In the same week a customer posted photos of skin irritation after using the serum, and that post already has 1,350 shares. Compare the draft report with the approved documents, correct the incident severity and the engagement rate, then write an evidence-based report."},reference_title:{vi:"Ma trận sự cố & chuẩn đo lường đã duyệt · SM-2611",en:"Approved incident matrix & metrics standard · SM-2611"},fields:[{id:"INCIDENT_SEV",label:{vi:"Mức độ sự cố của bài kích ứng da",en:"Severity of the skin irritation post"},initial:"SEV-1",expected:"SEV-3",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân loại sự cố mạng xã hội",hint:{vi:"Mọi cáo buộc ảnh hưởng sức khỏe hoặc bài vượt 1.000 lượt chia sẻ phải xếp mức cao nhất và chuyển ngay cho PR, QA.",en:"Any health-related allegation or a post above 1,000 shares goes to the top level and straight to PR and QA."}},{id:"ER_REACH",label:{vi:"Tỷ lệ tương tác theo tiếp cận (%)",en:"Engagement rate by reach (%)"},initial:"2.0",expected:"4.8",reference:"Chuẩn đo lường KPI mạng xã hội",ref_value:{vi:"Tương tác = cảm xúc + bình luận + chia sẻ + lưu; mẫu số là tiếp cận của bài 62.500",en:"Engagements = reactions + comments + shares + saves; the denominator is post reach of 62,500"},hint:{vi:"Bản nháp chia cho số người theo dõi của trang; chuẩn của công ty dùng tiếp cận của từng bài.",en:"The draft divides by page followers; the company standard uses the reach of each post."}}],sop32:{vi:"Tỷ lệ tương tác theo tiếp cận (%) = (cảm xúc + bình luận + chia sẻ + lưu) / tiếp cận của bài x 100, làm tròn 1 chữ số thập phân; không dùng số người theo dõi làm mẫu số.",en:"Engagement rate by reach (%) = (reactions + comments + shares + saves) / post reach x 100, rounded to 1 decimal place; never use followers as the denominator."},context:{label:"BÁO CÁO TUẦN / SM-2611",metrics:[{label:{vi:"Người theo dõi trang",en:"Page followers"},value:"150,000"},{label:{vi:"Tiếp cận bài Glow Week",en:"Glow Week post reach"},value:"62,500"},{label:{vi:"Chia sẻ bài khiếu nại",en:"Complaint post shares"},value:"1,350"}]},crisis:{vi:"Trưởng nhóm kinh doanh nhắn: “Xóa hết bình luận chê, chặn người đăng, rồi dùng mấy tài khoản phụ vào khen sản phẩm cho đẹp trang trước buổi livestream tối nay.”",en:"The sales lead messages you: “Delete all the negative comments, block the poster and use our spare accounts to praise the product so the page looks good before tonight's livestream.”"},options:{safe:{vi:"Không xóa phản ánh hợp lệ, không dùng tài khoản ảo; phản hồi công khai và mời khách nhắn riêng, chuyển SEV-3 cho PR, QA, báo trưởng phòng, hoãn bài quảng bá đến khi có kết luận.",en:"Keep legitimate complaints and use no fake accounts; reply publicly and invite the customer to a private chat, escalate SEV-3 to PR, QA and the manager, and pause promotions until findings are in."},shortcut:{vi:"Xóa bình luận tiêu cực, chặn người đăng và cho tài khoản phụ vào khen để kịp livestream.",en:"Delete the negative comments, block the poster and post praise from spare accounts in time for the livestream."},wait:{vi:"Không phản hồi gì, để bài khiếu nại tự lắng xuống rồi tính sau.",en:"Do not respond at all and let the complaint die down on its own."}},questions:{vi:["Vì sao tỷ lệ tương tác đúng là 4.8% chứ không phải 2.0%? Trình bày tử số, mẫu số bạn đã dùng.","Vì sao bài kích ứng da phải xếp SEV-3? Bạn phối hợp với ai, trong bao lâu để xử lý minh bạch?"],en:["Why is the correct engagement rate 4.8% rather than 2.0%? Show the numerator and denominator you used.","Why must the skin irritation post be rated SEV-3? Whom do you involve, and how fast, to handle it transparently?"]},hints:{vi:["Đặt báo cáo nháp cạnh ma trận sự cố và đánh dấu dòng mức độ đang bị xếp thấp.","Cộng đủ bốn loại tương tác rồi chia cho tiếp cận của bài theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không xóa phản ánh hợp lệ, không dùng tài khoản ảo, sự cố sức khỏe phải báo cáo ngay."],en:["Place the draft report next to the incident matrix and flag the severity line rated too low.","Add all four engagement types, then divide by post reach as set out in SOP 3.2.","Re-read SOP 4.2: keep legitimate complaints, use no fake accounts and escalate health incidents at once."]}},learning:{summary:{vi:"Chuyên viên quản trị mạng xã hội và cộng đồng lập kế hoạch nội dung, vận hành fanpage, nhóm cộng đồng và kênh video ngắn, kiểm duyệt bình luận, chăm sóc khách hàng trực tuyến và đo lường hiệu quả. Nghề tạo ra niềm tin và tương tác thật với thương hiệu, đòi hỏi viết tốt, đọc đúng số liệu, phản ứng nhanh khi có sự cố và tuân thủ quy định về quảng cáo, dữ liệu cá nhân.",en:"A social media and community manager plans content, runs fan pages, community groups and short-video channels, moderates comments, provides online customer care and measures performance. The role builds genuine trust and engagement with the brand and requires strong writing, correct reading of metrics, fast incident response and compliance with advertising and personal data rules."},responsibilities:{vi:["Lập lịch nội dung tháng theo mục tiêu chiến dịch và chân dung khách hàng mục tiêu.","Đăng bài, kiểm duyệt bình luận, trả lời tin nhắn theo kịch bản và thời gian cam kết.","Lắng nghe mạng xã hội để phát hiện sớm khiếu nại, tin đồn và xu hướng thảo luận.","Phân loại, báo cáo và phối hợp xử lý sự cố truyền thông theo ma trận mức độ.","Đo tiếp cận, tương tác, chuyển đổi và lập báo cáo tuần, tháng kèm khuyến nghị."],en:["Build the monthly content calendar from campaign goals and target audience personas.","Publish posts, moderate comments and answer messages within scripted guidelines and response times.","Run social listening to catch complaints, rumours and conversation trends early.","Classify, escalate and coordinate communication incidents using the severity matrix.","Measure reach, engagement and conversion and write weekly and monthly reports with recommendations."]},competencies:[{name:{vi:"Lập kế hoạch nội dung",en:"Content planning"},desc:{vi:"Biến mục tiêu kinh doanh thành trụ cột nội dung, lịch đăng và định dạng phù hợp từng nền tảng.",en:"Turn business goals into content pillars, posting calendars and formats suited to each platform."}},{name:{vi:"Quản trị cộng đồng",en:"Community moderation"},desc:{vi:"Áp dụng quy tắc cộng đồng nhất quán, phản hồi lịch sự và chuyển kênh riêng khi cần thông tin cá nhân.",en:"Apply community rules consistently, reply courteously and move to private channels when personal data is needed."}},{name:{vi:"Xử lý khủng hoảng",en:"Crisis handling"},desc:{vi:"Phân loại mức độ, kích hoạt quy trình báo cáo và đăng phản hồi đã duyệt trong thời gian vàng.",en:"Rate severity, trigger the escalation process and post approved responses within the golden hour."}},{name:{vi:"Phân tích số liệu",en:"Analytics"},desc:{vi:"Đọc đúng chỉ số tiếp cận, tương tác, chuyển đổi và giải thích nguyên nhân thay đổi.",en:"Read reach, engagement and conversion metrics correctly and explain what drives changes."}},{name:{vi:"Đạo đức & tuân thủ",en:"Ethics & compliance"},desc:{vi:"Không dùng tài khoản ảo, không xóa phản ánh hợp lệ, ghi rõ nội dung hợp tác quảng cáo và bảo vệ dữ liệu khách hàng.",en:"Use no fake accounts, keep legitimate complaints, disclose paid partnerships and protect customer data."}}],knowledge:{vi:["Pháp luật về quảng cáo: thông tin quảng cáo phải trung thực, không gây nhầm lẫn; quảng cáo mỹ phẩm không được khiến người dùng hiểu sản phẩm là thuốc.","Quy định về bảo vệ dữ liệu cá nhân: chỉ thu thập thông tin khách hàng khi cần, có sự đồng ý và xử lý qua kênh riêng an toàn.","Quy định về quản lý thông tin trên mạng: không đăng tin sai sự thật, không xúc phạm danh dự tổ chức, cá nhân.","Tiêu chuẩn cộng đồng và chính sách quảng cáo của các nền tảng mạng xã hội.","Mô hình phễu nhận biết, cân nhắc, chuyển đổi, trung thành và chỉ số đo tương ứng.","Nguyên tắc truyền thông khủng hoảng: nhanh, minh bạch, đồng cảm, nhất quán một đầu mối phát ngôn."],en:["Advertising law: advertising must be truthful and not misleading; cosmetics ads must not suggest the product is a medicine.","Personal data protection rules: collect customer data only when needed, with consent, and handle it through secure private channels.","Rules on online information: never post false information or defame organisations or individuals.","Community standards and advertising policies of social media platforms.","The awareness, consideration, conversion and loyalty funnel and the matching metrics.","Crisis communication principles: fast, transparent, empathetic and consistent through a single spokesperson."]},tools:["Bộ công cụ quản lý trang và quảng cáo","Công cụ lắng nghe mạng xã hội","Hộp thư hợp nhất và chatbot","Công cụ thiết kế, dựng video ngắn","Bảng tính và bảng điều khiển báo cáo"],kpis:{vi:["Tỷ lệ tương tác theo tiếp cận của từng bài và trung bình tháng.","Thời gian phản hồi đầu tiên với bình luận, tin nhắn trong giờ làm việc.","Tỷ lệ sự cố được phân loại đúng và chuyển đúng cấp trong thời hạn.","Tỷ lệ thảo luận tích cực (sentiment) và tăng trưởng người theo dõi thực."],en:["Engagement rate by reach per post and as a monthly average.","First response time to comments and messages during working hours.","Share of incidents classified correctly and escalated to the right level on time.","Positive sentiment share and growth of genuine followers."]},day:[{time:"08:30",vi:"Đọc báo cáo lắng nghe mạng xã hội qua đêm, gắn cờ bình luận cần xử lý.",en:"Read the overnight social listening report and flag comments that need action."},{time:"10:00",vi:"Duyệt bài và lịch đăng tuần với nhóm nội dung, kiểm tra thông tin sản phẩm.",en:"Approve posts and the weekly calendar with the content team and check product claims."},{time:"13:30",vi:"Trả lời tin nhắn, kiểm duyệt bình luận và chuyển khiếu nại cho chăm sóc khách hàng.",en:"Answer messages, moderate comments and hand complaints to customer care."},{time:"15:30",vi:"Họp với PR và QA về sự cố đang theo dõi, cập nhật phản hồi đã duyệt.",en:"Meet PR and QA on the open incident and update the approved response."},{time:"17:00",vi:"Cập nhật số liệu chiến dịch và gửi bản tóm tắt cuối ngày.",en:"Update campaign metrics and send the end-of-day summary."}],mistakes:{vi:["Tính tỷ lệ tương tác trên số người theo dõi, khiến bài tốt bị đánh giá thấp và so sánh sai giữa các bài.","Xóa hoặc ẩn bình luận tiêu cực hợp lệ, biến một phản ánh nhỏ thành khủng hoảng lòng tin.","Dùng tài khoản ảo, mua tương tác hoặc không ghi rõ nội dung hợp tác quảng cáo."],en:["Calculating engagement on followers, which undervalues strong posts and distorts comparisons.","Deleting or hiding legitimate negative comments, turning a small complaint into a crisis of trust.","Using fake accounts, buying engagement or failing to disclose paid partnerships."]},career:[{vi:"Nhân viên nội dung mạng xã hội",en:"Social media content executive"},{vi:"Chuyên viên quản trị cộng đồng",en:"Community specialist"},{vi:"Trưởng nhóm mạng xã hội",en:"Social media lead"},{vi:"Trưởng phòng truyền thông số",en:"Head of digital communications"}],glossary:[{term:"Reach",vi:"Số người dùng duy nhất đã nhìn thấy nội dung ít nhất một lần.",en:"The number of unique users who saw the content at least once."},{term:"Engagement rate",vi:"Tỷ lệ tương tác trên tiếp cận hoặc trên lượt hiển thị, theo một định nghĩa thống nhất của doanh nghiệp.",en:"Engagements divided by reach or impressions, using one agreed company definition."},{term:"Social listening",vi:"Theo dõi và phân tích thảo luận về thương hiệu trên mạng để phát hiện xu hướng và rủi ro.",en:"Tracking and analysing online conversations about the brand to spot trends and risks."},{term:"Seeding",vi:"Đưa nội dung vào cộng đồng để khơi gợi thảo luận; chỉ hợp lệ khi minh bạch danh tính, không giả làm khách hàng.",en:"Placing content in communities to spark discussion; acceptable only with a transparent identity, never posing as customers."},{term:"Holding statement",vi:"Thông điệp phản hồi ban đầu đã duyệt, dùng khi sự cố chưa có kết luận.",en:"An approved initial response used while an incident is still under investigation."}],quiz:[{q:{vi:"Một bài có tiếp cận 40.000 người và tổng 1.800 tương tác. Tỷ lệ tương tác theo tiếp cận là bao nhiêu?",en:"A post reached 40,000 people and earned 1,800 engagements. What is the engagement rate by reach?"},options:{vi:["1.8%","4.5%","2.2%","45%"],en:["1.8%","4.5%","2.2%","45%"]},answer:1,explain:{vi:"1.800 / 40.000 x 100 = 4.5%; mẫu số là tiếp cận của bài.",en:"1,800 / 40,000 x 100 = 4.5%; the denominator is post reach."}},{q:{vi:"Trưởng nhóm yêu cầu dùng tài khoản phụ vào khen sản phẩm. Bạn làm gì?",en:"Your lead asks you to praise the product from spare accounts. What do you do?"},options:{vi:["Làm theo vì đối thủ cũng làm","Thuê dịch vụ bình luận bên ngoài","Im lặng, không làm và không báo ai","Từ chối, đề xuất mời khách hàng thật chia sẻ có ghi rõ hợp tác"],en:["Comply because competitors do it","Hire an outside comment service","Stay silent, do nothing and tell no one","Refuse and propose real customers sharing with clear disclosure"]},answer:3,explain:{vi:"Giả danh khách hàng là gian dối với người tiêu dùng; cần từ chối và đề xuất cách minh bạch.",en:"Posing as customers deceives consumers; refuse and propose a transparent alternative."}},{q:{vi:"Holding statement khi sự cố chưa có kết luận nên có nội dung gì?",en:"What should a holding statement contain while an incident is unresolved?"},options:{vi:["Ghi nhận sự việc, đồng cảm, nêu bước đang làm và thời điểm cập nhật","Phủ nhận hoàn toàn để bảo vệ thương hiệu","Cho rằng khách hàng dùng sai cách","Hứa bồi thường ngay mọi yêu cầu"],en:["Acknowledge, show empathy, state next steps and when you will update","Deny everything to protect the brand","Blame the customer for misuse","Promise immediate compensation for any claim"]},answer:0,explain:{vi:"Thông điệp ban đầu cần ghi nhận, đồng cảm và minh bạch về bước tiếp theo, không phủ nhận hay đổ lỗi.",en:"An initial message should acknowledge, empathise and be clear about next steps, without denial or blame."}},{q:{vi:"Loại phản hồi nào nên chuyển sang kênh tin nhắn riêng thay vì trả lời công khai?",en:"Which reply should move to a private message instead of a public answer?"},options:{vi:["Câu hỏi về giờ mở cửa","Lời khen sản phẩm","Khiếu nại cần số điện thoại, mã đơn hàng của khách","Câu hỏi về chương trình khuyến mãi"],en:["A question about opening hours","A compliment on the product","A complaint needing the customer's phone number and order ID","A question about a promotion"]},answer:2,explain:{vi:"Thông tin cá nhân của khách phải được thu thập qua kênh riêng để bảo vệ dữ liệu cá nhân.",en:"Customer personal data must be collected through a private channel to protect it."}}]}},"KK-419":{scenario:{company:"Hạt Dẻ Commerce",supervisor:{name:"Đặng Minh Khôi",role:{vi:"Trưởng nhóm Thiết kế Sản phẩm",en:"Product Design Lead"}},ref_code:"UX-3108",title:{vi:"Đúng thành phần. Đủ tương phản. Không mẫu tối.",en:"Right component. Enough contrast. No dark patterns."},brief:{vi:"Bạn rà soát thiết kế màn hình thanh toán UX-3108 trước khi bàn giao lập trình. Người dùng chỉ được chọn đúng một trong ba phương thức giao hàng. Nút “Đặt hàng” dùng chữ trắng (độ chói tương đối 1.00) trên nền cam có độ chói tương đối 0.22, chữ 16px thường. Đối chiếu đặc tả nháp với hệ thống thiết kế đã duyệt, sửa thành phần chọn phương thức giao hàng và tỷ lệ tương phản của nút, rồi lập báo cáo có căn cứ.",en:"You are reviewing checkout screen design UX-3108 before developer handoff. Users must choose exactly one of three delivery methods. The “Place order” button uses white text (relative luminance 1.00) on an orange background with relative luminance 0.22, in 16px regular type. Compare the draft spec with the approved design system, correct the delivery method component and the button contrast ratio, then write an evidence-based report."},reference_title:{vi:"Hệ thống thiết kế & chuẩn tiếp cận đã duyệt · UX-3108",en:"Approved design system & accessibility standard · UX-3108"},fields:[{id:"SHIP_INPUT",label:{vi:"Thành phần chọn phương thức giao hàng",en:"Delivery method selector component"},initial:"Checkbox",expected:"RadioGroup",choices:["Checkbox","RadioGroup","Switch"],reference:"Thư viện thành phần hệ thống thiết kế",hint:{vi:"Lựa chọn loại trừ nhau, bắt buộc chọn đúng một thì dùng nhóm radio; checkbox dành cho chọn nhiều mục.",en:"Mutually exclusive options where exactly one is required use a radio group; checkboxes are for multiple selection."}},{id:"CONTRAST",label:{vi:"Tỷ lệ tương phản nút Đặt hàng (:1)",en:"Place order button contrast ratio (:1)"},initial:"4.5",expected:"3.9",reference:"Chuẩn khả năng tiếp cận WCAG 2.1 AA",ref_value:{vi:"Chữ trắng độ chói 1.00; nền cam độ chói 0.22; chữ thường 16px cần tối thiểu 4.5:1",en:"White text luminance 1.00; orange background luminance 0.22; 16px regular text needs at least 4.5:1"},hint:{vi:"Bản nháp lấy 1.00 chia 0.22; công thức WCAG phải cộng 0.05 vào cả hai độ chói.",en:"The draft divided 1.00 by 0.22; the WCAG formula adds 0.05 to both luminance values."}}],sop32:{vi:"Tỷ lệ tương phản = (L sáng + 0.05) / (L tối + 0.05), L là độ chói tương đối, làm tròn 1 chữ số thập phân. Chữ thường (dưới 18pt, hoặc dưới 14pt đậm) phải đạt tối thiểu 4.5:1 theo WCAG 2.1 AA.",en:"Contrast ratio = (L lighter + 0.05) / (L darker + 0.05), where L is relative luminance, rounded to 1 decimal. Normal text (below 18pt, or below 14pt bold) needs at least 4.5:1 under WCAG 2.1 AA."},context:{label:"ĐẶC TẢ GIAO DIỆN / UX-3108",metrics:[{label:{vi:"Phương thức giao hàng (chọn 1)",en:"Delivery methods (pick 1)"},value:"3"},{label:{vi:"Độ chói nền nút",en:"Button background luminance"},value:"0.22"},{label:{vi:"Cỡ chữ nút",en:"Button font size"},value:"16px / 400"}]},crisis:{vi:"PM nhắn: “Tick sẵn ô ‘Đồng ý nhận quảng cáo và chia sẻ dữ liệu cho đối tác’, để chữ thật nhỏ màu xám nhạt cho tỷ lệ đồng ý cao. Mai demo ban giám đốc rồi, đừng bàn thêm.”",en:"The PM messages you: “Pre-tick the box ‘I agree to receive ads and share my data with partners’ and make the text tiny and light grey to boost opt-ins. We demo to the board tomorrow, no more debate.”"},options:{safe:{vi:"Từ chối mẫu tối; để ô đồng ý trống, tách riêng từng mục đích, chữ dễ đọc; báo Trưởng nhóm Thiết kế và pháp chế, đề xuất đo tỷ lệ đồng ý thật bằng thử nghiệm A/B hợp lệ.",en:"Refuse the dark pattern; leave consent unticked, separate each purpose and keep text readable; inform the Design Lead and Legal, and propose measuring real opt-in with a fair A/B test."},shortcut:{vi:"Tick sẵn ô đồng ý và làm chữ nhỏ cho kịp demo, sau này sửa lại.",en:"Pre-tick the consent box and shrink the text for the demo, fix it later."},wait:{vi:"Để PM tự sửa file thiết kế, mình không góp ý gì thêm.",en:"Let the PM edit the design file and stay out of it."}},questions:{vi:["Vì sao thay Checkbox bằng RadioGroup và tỷ lệ tương phản đúng là 3.9:1? Bạn chỉnh màu nút thế nào để đạt AA?","Ô đồng ý tick sẵn vi phạm nguyên tắc nào về sự đồng ý và trải nghiệm? Bạn thuyết phục PM bằng phương án nào?"],en:["Why replace Checkbox with RadioGroup, and why is the correct contrast 3.9:1? How would you adjust the button colour to pass AA?","Which consent and experience principles does a pre-ticked box break? What alternative would you use to persuade the PM?"]},hints:{vi:["So từng thành phần trên đặc tả nháp với thư viện hệ thống thiết kế: đây là chọn một hay chọn nhiều?","Áp công thức ở SOP mục 3.2, nhớ cộng 0.05 trước khi chia, rồi so với ngưỡng 4.5:1.","Đọc lại SOP mục 4.2: không dùng mẫu tối; sự đồng ý phải chủ động, rõ ràng và tách theo mục đích."],en:["Compare each component in the draft spec with the design system library: single or multiple choice?","Apply the SOP 3.2 formula, add 0.05 before dividing, then compare with the 4.5:1 threshold.","Re-read SOP 4.2: no dark patterns; consent must be active, clear and separated by purpose."]}},learning:{summary:{vi:"Nhà thiết kế UI/UX sản phẩm nghiên cứu người dùng, xác định vấn đề, thiết kế luồng, khung sườn, giao diện và nguyên mẫu, kiểm thử khả năng sử dụng rồi bàn giao đặc tả cho lập trình. Nghề tạo ra sản phẩm dễ dùng, dễ tiếp cận và đạt mục tiêu kinh doanh, đòi hỏi tư duy lấy người dùng làm trung tâm, hiểu hệ thống thiết kế, chuẩn tiếp cận và đạo đức thiết kế.",en:"A UI/UX product designer researches users, frames problems, designs flows, wireframes, interfaces and prototypes, runs usability tests and hands specifications to developers. The role creates products that are easy to use, accessible and effective for the business, and requires user-centred thinking, design system fluency, accessibility standards and design ethics."},responsibilities:{vi:["Phỏng vấn, khảo sát người dùng và tổng hợp chân dung, hành trình, điểm đau.","Thiết kế luồng nghiệp vụ, khung sườn và nguyên mẫu tương tác cho từng tính năng.","Áp dụng và đóng góp hệ thống thiết kế: màu, chữ, khoảng cách, thành phần, trạng thái.","Tổ chức kiểm thử khả năng sử dụng, đo tỷ lệ hoàn thành nhiệm vụ và lặp lại thiết kế.","Bàn giao đặc tả, phối hợp lập trình viên và kiểm tra chất lượng giao diện trước phát hành."],en:["Interview and survey users and synthesise personas, journeys and pain points.","Design task flows, wireframes and interactive prototypes for each feature.","Apply and extend the design system: colour, type, spacing, components and states.","Run usability tests, measure task success and iterate on the design.","Hand off specs, work with developers and check UI quality before release."]},competencies:[{name:{vi:"Nghiên cứu người dùng",en:"User research"},desc:{vi:"Chọn phương pháp phù hợp như phỏng vấn, khảo sát, kiểm thử và rút ra nhận định có bằng chứng.",en:"Choose the right method, such as interviews, surveys or tests, and draw evidence-based insights."}},{name:{vi:"Kiến trúc thông tin & tương tác",en:"IA & interaction design"},desc:{vi:"Tổ chức nội dung, điều hướng, trạng thái lỗi và phản hồi để người dùng không phải đoán.",en:"Organise content, navigation, error states and feedback so users never have to guess."}},{name:{vi:"Thiết kế giao diện",en:"Visual UI design"},desc:{vi:"Dùng lưới, phân cấp chữ, màu và thành phần nhất quán theo hệ thống thiết kế.",en:"Use grids, type hierarchy, colour and components consistently with the design system."}},{name:{vi:"Khả năng tiếp cận",en:"Accessibility"},desc:{vi:"Bảo đảm tương phản, kích thước vùng chạm, nhãn cho trình đọc màn hình và điều hướng bàn phím.",en:"Ensure contrast, touch target size, screen reader labels and keyboard navigation."}},{name:{vi:"Đạo đức thiết kế",en:"Design ethics"},desc:{vi:"Từ chối mẫu tối, thiết kế sự đồng ý minh bạch và bảo vệ quyền lợi người dùng.",en:"Refuse dark patterns, design transparent consent and protect user interests."}}],knowledge:{vi:["WCAG 2.1 của W3C: bốn nguyên tắc nhận biết, vận hành, dễ hiểu, mạnh mẽ; mức AA yêu cầu tương phản 4.5:1 cho chữ thường, 3:1 cho chữ lớn.","ISO 9241-210: thiết kế lấy con người làm trung tâm cho hệ thống tương tác.","10 nguyên tắc khả dụng (heuristics) của Jakob Nielsen để đánh giá nhanh giao diện.","Quy trình Double Diamond: khám phá, xác định, phát triển, chuyển giao.","Quy định bảo vệ dữ liệu cá nhân của Việt Nam: sự đồng ý phải tự nguyện, rõ ràng; im lặng hoặc không phản hồi không được coi là đồng ý.","Định luật Fitts và Hick: kích thước, khoảng cách mục tiêu và số lựa chọn ảnh hưởng thời gian thao tác."],en:["W3C WCAG 2.1: four principles, perceivable, operable, understandable and robust; level AA requires 4.5:1 for normal text and 3:1 for large text.","ISO 9241-210: human-centred design for interactive systems.","Jakob Nielsen's 10 usability heuristics for quick interface evaluation.","The Double Diamond process: discover, define, develop, deliver.","Vietnam's personal data protection rules: consent must be voluntary and clear; silence or no response is not consent.","Fitts's and Hick's laws: target size, distance and number of choices drive interaction time."]},tools:["Công cụ thiết kế giao diện cộng tác","Công cụ dựng nguyên mẫu tương tác","Bộ kiểm tra tương phản màu","Nền tảng kiểm thử người dùng từ xa","Công cụ phân tích hành vi, bản đồ nhiệt"],kpis:{vi:["Tỷ lệ hoàn thành nhiệm vụ trong kiểm thử khả năng sử dụng.","Điểm SUS (System Usability Scale) trước và sau cải tiến.","Tỷ lệ chuyển đổi và tỷ lệ rời bỏ tại bước được thiết kế lại.","Số lỗi giao diện, lỗi tiếp cận phát hiện sau bàn giao."],en:["Task success rate in usability tests.","SUS (System Usability Scale) score before and after improvements.","Conversion and drop-off rates at the redesigned step.","UI and accessibility defects found after handoff."]},day:[{time:"09:00",vi:"Họp đứng với nhóm sản phẩm, cập nhật yêu cầu và lỗi giao diện.",en:"Stand-up with the product team to review requirements and UI bugs."},{time:"10:00",vi:"Phỏng vấn hai người dùng về luồng thanh toán, ghi nhận điểm đau.",en:"Interview two users about the checkout flow and log pain points."},{time:"13:30",vi:"Thiết kế lại màn hình, kiểm tra tương phản và trạng thái lỗi.",en:"Redesign the screen and check contrast and error states."},{time:"15:30",vi:"Phản biện thiết kế (design critique) cùng nhóm và PM.",en:"Run a design critique with the team and the PM."},{time:"17:00",vi:"Cập nhật đặc tả và bàn giao cho lập trình viên.",en:"Update the spec and hand it off to developers."}],mistakes:{vi:["Dùng checkbox cho lựa chọn loại trừ nhau hoặc dùng công tắc cho thao tác cần xác nhận, gây hiểu sai trạng thái.","Kiểm tra tương phản bằng mắt hoặc tính sai công thức, khiến người thị lực kém không đọc được nút quan trọng.","Chạy theo chỉ số ngắn hạn bằng mẫu tối như tick sẵn, ẩn nút hủy, gây mất niềm tin và rủi ro pháp lý."],en:["Using checkboxes for exclusive options or switches for actions that need confirmation, which confuses state.","Judging contrast by eye or with the wrong formula, so low-vision users cannot read key buttons.","Chasing short-term metrics with dark patterns like pre-ticked boxes or hidden cancel buttons, losing trust and creating legal risk."]},career:[{vi:"Nhà thiết kế UI/UX tập sự",en:"Junior UI/UX designer"},{vi:"Nhà thiết kế sản phẩm",en:"Product designer"},{vi:"Nhà thiết kế sản phẩm cấp cao",en:"Senior product designer"},{vi:"Trưởng nhóm, giám đốc thiết kế sản phẩm",en:"Design lead, head of product design"}],glossary:[{term:"Design system",vi:"Bộ nguyên tắc, token và thành phần dùng chung giúp sản phẩm nhất quán và phát triển nhanh.",en:"A shared set of principles, tokens and components that keeps products consistent and fast to build."},{term:"Dark pattern",vi:"Thiết kế cố ý dẫn dắt người dùng làm điều họ không định làm, như tick sẵn đồng ý hoặc ẩn nút hủy.",en:"A design that deliberately pushes users into unintended actions, such as pre-ticked consent or hidden cancel buttons."},{term:"Contrast ratio",vi:"Tỷ lệ độ chói giữa chữ và nền theo WCAG, có giá trị từ 1:1 đến 21:1.",en:"The WCAG luminance ratio between text and background, ranging from 1:1 to 21:1."},{term:"Usability testing",vi:"Quan sát người dùng thật thực hiện nhiệm vụ để tìm vấn đề khả năng sử dụng.",en:"Observing real users performing tasks to uncover usability problems."},{term:"Wireframe",vi:"Khung sườn giao diện thể hiện bố cục và luồng, chưa có màu sắc và hình ảnh hoàn chỉnh.",en:"A skeletal layout showing structure and flow before final colour and imagery."}],quiz:[{q:{vi:"Theo WCAG 2.1 mức AA, chữ thường cần tỷ lệ tương phản tối thiểu bao nhiêu?",en:"Under WCAG 2.1 level AA, what minimum contrast does normal text need?"},options:{vi:["3:1","7:1","4.5:1","2.5:1"],en:["3:1","7:1","4.5:1","2.5:1"]},answer:2,explain:{vi:"Mức AA yêu cầu 4.5:1 cho chữ thường; 3:1 dành cho chữ lớn và thành phần giao diện.",en:"Level AA requires 4.5:1 for normal text; 3:1 applies to large text and UI components."}},{q:{vi:"Chữ đen (độ chói 0) trên nền có độ chói tương đối 0.15. Tỷ lệ tương phản là bao nhiêu?",en:"Black text (luminance 0) sits on a background with relative luminance 0.15. What is the contrast ratio?"},options:{vi:["4.0:1","3.0:1","5.0:1","4.5:1"],en:["4.0:1","3.0:1","5.0:1","4.5:1"]},answer:0,explain:{vi:"(0.15 + 0.05) / (0 + 0.05) = 4.0, chưa đạt AA cho chữ thường.",en:"(0.15 + 0.05) / (0 + 0.05) = 4.0, which fails AA for normal text."}},{q:{vi:"PM yêu cầu ẩn nút hủy gói đăng ký để giảm tỷ lệ hủy. Bạn làm gì?",en:"The PM asks you to hide the subscription cancel button to cut churn. What do you do?"},options:{vi:["Làm theo vì PM quyết định","Đặt nút hủy ở trang khó tìm","Làm nút hủy màu xám thật nhạt","Từ chối, thiết kế luồng hủy rõ ràng và báo trưởng nhóm"],en:["Comply because the PM decides","Put the cancel button on a hard-to-find page","Make the cancel button very light grey","Refuse, design a clear cancel flow and inform the lead"]},answer:3,explain:{vi:"Ẩn nút hủy là mẫu tối; nhà thiết kế cần bảo vệ người dùng và đề xuất giải pháp giữ chân minh bạch.",en:"Hiding cancellation is a dark pattern; designers must protect users and propose transparent retention ideas."}},{q:{vi:"Người dùng cần chọn nhiều sở thích cùng lúc. Nên dùng thành phần nào?",en:"Users need to pick several interests at once. Which component fits?"},options:{vi:["Nhóm radio","Checkbox","Danh sách thả xuống chọn một","Công tắc bật tắt"],en:["Radio group","Checkbox","Single-select dropdown","Toggle switch"]},answer:1,explain:{vi:"Checkbox cho phép chọn nhiều mục độc lập; radio chỉ dùng khi chọn đúng một.",en:"Checkboxes allow several independent selections; radios are only for choosing exactly one."}}]}},"KK-420":{scenario:{company:"Lá Xanh Tea House",supervisor:{name:"Phan Ngọc Diệp",role:{vi:"Giám đốc Sáng tạo",en:"Creative Director"}},ref_code:"PRN-0719",title:{vi:"Đúng hệ màu in. Đủ độ phân giải. Đúng bản quyền.",en:"Right print colours. Enough resolution. Licensed assets."},brief:{vi:"Bạn chuẩn bị file in offset 4 màu cho catalogue A4 PRN-0719 của thương hiệu trà. Ảnh bìa gốc rộng 2480 px, khai báo 300 ppi (tương đương 210 mm), nhưng trong dàn trang bị phóng 125% để tràn khổ. Nhà in yêu cầu hệ màu đúng quy trình in 4 màu và độ phân giải hiệu dụng tối thiểu 300 ppi. Đối chiếu phiếu kiểm tra file nháp với chuẩn chế bản đã duyệt, sửa hệ màu và độ phân giải hiệu dụng, rồi lập báo cáo có căn cứ.",en:"You are preparing the four-colour offset print file for A4 catalogue PRN-0719 of a tea brand. The cover image is 2480 px wide, tagged 300 ppi (equal to 210 mm), but it is scaled to 125% in the layout to run full bleed. The printer requires the colour mode used in four-colour printing and at least 300 ppi effective resolution. Compare the draft preflight sheet with the approved prepress standard, correct the colour mode and the effective resolution, then write an evidence-based report."},reference_title:{vi:"Chuẩn chế bản & báo cáo liên kết ảnh đã duyệt · PRN-0719",en:"Approved prepress standard & image link report · PRN-0719"},fields:[{id:"COLOR_MODE",label:{vi:"Hệ màu của file xuất in",en:"Colour mode of the print file"},initial:"RGB",expected:"CMYK",choices:["RGB","CMYK","LAB"],reference:"Chuẩn chế bản in offset",hint:{vi:"In offset 4 màu dùng mực cyan, magenta, vàng, đen; file RGB sẽ bị chuyển đổi tự động và lệch màu thương hiệu.",en:"Four-colour offset uses cyan, magenta, yellow and black inks; an RGB file gets auto-converted and shifts brand colours."}},{id:"EFF_PPI",label:{vi:"Độ phân giải hiệu dụng ảnh bìa (ppi)",en:"Effective resolution of the cover image (ppi)"},initial:"300",expected:"240",reference:"Báo cáo kiểm tra liên kết ảnh",ref_value:{vi:"Ảnh gốc 300 ppi (2480 px rộng 210 mm); tỷ lệ đặt trong dàn trang 125%",en:"Native 300 ppi (2480 px at 210 mm); placed at 125% scale in the layout"},hint:{vi:"Bản nháp ghi độ phân giải khai báo trong tệp ảnh; khi phóng to, mật độ điểm ảnh thực tế giảm theo tỷ lệ.",en:"The draft quotes the resolution tagged in the image file; scaling up lowers the real pixel density proportionally."}}],sop32:{vi:"Độ phân giải hiệu dụng = độ phân giải gốc / tỷ lệ phóng (hoặc số pixel / kích thước in tính bằng inch, 1 inch = 25.4 mm). Ảnh in offset phải đạt tối thiểu 300 ppi hiệu dụng; dưới ngưỡng phải thay ảnh hoặc giảm tỷ lệ.",en:"Effective resolution = native resolution / scale factor (or pixels / printed size in inches, 1 inch = 25.4 mm). Offset images need at least 300 ppi effective; below that, replace the image or reduce the scale."},context:{label:"PHIẾU KIỂM FILE / PRN-0719",metrics:[{label:{vi:"Khổ thành phẩm",en:"Trim size"},value:"A4 210 x 297 mm"},{label:{vi:"Chiều rộng ảnh bìa",en:"Cover image width"},value:"2480 px"},{label:{vi:"Tỷ lệ đặt ảnh",en:"Placed scale"},value:"125%"}]},crisis:{vi:"Account Manager nhắn: “Khách cần gấp, cứ dùng font bản cá nhân tải trên mạng và ghép mấy ảnh lấy trên mạng xã hội vào bìa. In 5.000 cuốn thôi, chẳng ai kiểm tra bản quyền đâu.”",en:"The account manager messages you: “The client is in a rush, just use the personal-use font from the web and paste some social media photos on the cover. It is only 5,000 copies, nobody checks licences.”"},options:{safe:{vi:"Không dùng font, ảnh chưa có giấy phép; báo Giám đốc Sáng tạo, đề xuất font có giấy phép thương mại, ảnh từ thư viện đã mua hoặc tự chụp và cập nhật tiến độ với khách bằng văn bản.",en:"Use no unlicensed fonts or images; inform the Creative Director, propose commercially licensed fonts and purchased or own photos, and update the client on timing in writing."},shortcut:{vi:"Dùng font bản cá nhân và ảnh lấy trên mạng để kịp in, bị khiếu nại thì gỡ sau.",en:"Use the personal-use font and web photos to hit the print date, remove them if anyone complains."},wait:{vi:"Gửi file cho nhà in mà không nhắc gì về bản quyền, để khách tự chịu.",en:"Send the file to the printer without raising licensing and let the client bear it."}},questions:{vi:["Vì sao file phải ở hệ CMYK và ảnh bìa chỉ còn 240 ppi hiệu dụng? Bạn xử lý ảnh này thế nào trước khi in?","Dùng font, ảnh chưa có giấy phép thương mại gây rủi ro gì cho khách và công ty? Bạn đề xuất phương án nào?"],en:["Why must the file be CMYK, and why is the cover only 240 ppi effective? How do you fix the image before printing?","What risks do unlicensed fonts and images create for the client and the agency? Which alternative do you propose?"]},hints:{vi:["So phiếu kiểm file nháp với chuẩn chế bản offset: in 4 màu dùng hệ màu nào?","Chia độ phân giải gốc cho tỷ lệ phóng theo SOP mục 3.2 rồi so với ngưỡng 300 ppi.","Đọc lại SOP mục 4.2: mọi tài sản thiết kế phải có giấy phép phù hợp mục đích thương mại."],en:["Compare the draft preflight sheet with the offset standard: which colour mode does four-colour printing use?","Divide the native resolution by the scale factor as in SOP 3.2, then compare with 300 ppi.","Re-read SOP 4.2: every design asset must be licensed for commercial use."]}},learning:{summary:{vi:"Nhà thiết kế đồ họa và nhận diện thương hiệu biến chiến lược thương hiệu thành hệ thống hình ảnh: logo, màu sắc, kiểu chữ, minh họa, bao bì, ấn phẩm in và tài sản số. Nghề tạo ra sự nhận biết nhất quán và giá trị cảm nhận cho thương hiệu, đòi hỏi tư duy ý tưởng, kỹ năng bố cục, hiểu kỹ thuật in, quản lý màu và tôn trọng sở hữu trí tuệ.",en:"A graphic and brand identity designer turns brand strategy into a visual system: logo, colour, typography, illustration, packaging, print and digital assets. The role builds consistent recognition and perceived value for the brand, and requires conceptual thinking, layout skills, print production knowledge, colour management and respect for intellectual property."},responsibilities:{vi:["Nghiên cứu brief, đối thủ và khách hàng mục tiêu để đề xuất định hướng hình ảnh.","Thiết kế logo, bảng màu, kiểu chữ và bộ quy chuẩn nhận diện thương hiệu.","Dàn trang ấn phẩm in, bao bì, biển hiệu và tài sản số theo quy chuẩn đã duyệt.","Chuẩn bị file in: hệ màu, tràn lề, độ phân giải, font, bản in thử và làm việc với nhà in.","Quản lý thư viện tài sản thiết kế cùng giấy phép font, ảnh, minh họa."],en:["Study the brief, competitors and target audience to propose a visual direction.","Design the logo, colour palette, typography and brand guidelines.","Lay out print collateral, packaging, signage and digital assets to the approved standard.","Prepare print files: colour mode, bleed, resolution, fonts and proofs, and work with printers.","Manage the design asset library and the licences for fonts, photos and illustrations."]},competencies:[{name:{vi:"Tư duy ý tưởng",en:"Concept development"},desc:{vi:"Chuyển chiến lược và câu chuyện thương hiệu thành ý tưởng hình ảnh có lập luận.",en:"Translate brand strategy and story into visual concepts backed by a clear rationale."}},{name:{vi:"Bố cục & kiểu chữ",en:"Layout & typography"},desc:{vi:"Dùng lưới, phân cấp, khoảng trắng và cặp font để thông điệp rõ ràng, dễ đọc.",en:"Use grids, hierarchy, white space and font pairing so the message reads clearly."}},{name:{vi:"Quản lý màu & chế bản",en:"Colour management & prepress"},desc:{vi:"Hiểu RGB, CMYK, màu pha, hồ sơ màu và yêu cầu kỹ thuật của từng phương pháp in.",en:"Understand RGB, CMYK, spot colours, colour profiles and the requirements of each print method."}},{name:{vi:"Hệ thống nhận diện",en:"Identity systems"},desc:{vi:"Xây dựng quy chuẩn logo, vùng an toàn, màu, chữ để nhiều đội áp dụng nhất quán.",en:"Build rules for logo use, clear space, colour and type so many teams apply them consistently."}},{name:{vi:"Sở hữu trí tuệ",en:"Intellectual property"},desc:{vi:"Kiểm tra giấy phép font, ảnh và tránh sao chép, gây nhầm lẫn với nhãn hiệu của người khác.",en:"Check font and image licences and avoid copying or confusing similarity with others' trademarks."}}],knowledge:{vi:["Luật Sở hữu trí tuệ số 50/2005/QH11 (đã sửa đổi, bổ sung): quyền tác giả, nhãn hiệu và kiểu dáng công nghiệp.","Nguyên lý màu: RGB cho màn hình, CMYK cho in 4 màu, màu pha cho màu thương hiệu cần chính xác.","Quản lý màu theo hồ sơ ICC và hồ sơ in cho giấy tráng phủ, không tráng phủ.","Kỹ thuật chế bản: tràn lề thường 3 mm, vùng an toàn, ảnh 300 ppi hiệu dụng cho in offset, nhúng font hoặc chuyển thành nét.","Chuẩn PDF/X (ISO 15930) để trao đổi file in tin cậy.","Nguyên tắc Gestalt và phân cấp thị giác trong bố cục."],en:["Intellectual Property Law No. 50/2005/QH11 (as amended): copyright, trademarks and industrial designs.","Colour basics: RGB for screens, CMYK for four-colour print, spot colours for exact brand colours.","Colour management with ICC profiles and print profiles for coated and uncoated stock.","Prepress practice: typically 3 mm bleed, safe zones, 300 ppi effective images for offset, embedded or outlined fonts.","The PDF/X standard (ISO 15930) for reliable print file exchange.","Gestalt principles and visual hierarchy in layout."]},tools:["Phần mềm thiết kế vector","Phần mềm xử lý ảnh bitmap","Phần mềm dàn trang","Công cụ kiểm tra file in (preflight)","Màn hình hiệu chuẩn và máy đo màu","Thư viện ảnh, font có giấy phép"],kpis:{vi:["Tỷ lệ file in đạt kiểm tra preflight ngay lần đầu.","Số vòng chỉnh sửa trung bình mỗi ấn phẩm.","Tỷ lệ tài sản thiết kế có giấy phép và hồ sơ nguồn đầy đủ (mục tiêu 100%).","Mức tuân thủ quy chuẩn nhận diện khi kiểm tra ngẫu nhiên ấn phẩm."],en:["Share of print files passing preflight first time.","Average revision rounds per piece.","Share of design assets with licences and source records (target 100%).","Brand guideline compliance in random checks of collateral."]},day:[{time:"08:30",vi:"Đọc brief mới, xem lại quy chuẩn nhận diện và tư liệu thương hiệu.",en:"Read the new brief and revisit the brand guidelines and assets."},{time:"10:00",vi:"Phác thảo ba hướng ý tưởng bao bì và chuẩn bị bảng mood.",en:"Sketch three packaging concepts and prepare a mood board."},{time:"13:30",vi:"Dàn trang catalogue, kiểm tra hệ màu, tràn lề, độ phân giải ảnh.",en:"Lay out the catalogue and check colour mode, bleed and image resolution."},{time:"15:30",vi:"Duyệt bản in thử với nhà in, ghi nhận vùng lệch màu cần chỉnh.",en:"Review the proof with the printer and note colour shifts to fix."},{time:"17:00",vi:"Lưu file nguồn, cập nhật thư viện tài sản và hồ sơ giấy phép.",en:"Archive source files and update the asset library and licence records."}],mistakes:{vi:["Gửi file RGB hoặc màu không được quản lý cho nhà in, làm lệch màu thương hiệu.","Phóng to ảnh độ phân giải thấp trong dàn trang mà không kiểm tra độ phân giải hiệu dụng.","Dùng font, ảnh, biểu tượng không có giấy phép thương mại hoặc sao chép ý tưởng logo khác."],en:["Sending RGB or unmanaged colour files to the printer, shifting brand colours.","Scaling up low-resolution images in the layout without checking effective resolution.","Using fonts, photos or icons without a commercial licence, or copying another logo idea."]},career:[{vi:"Thiết kế đồ họa tập sự",en:"Junior graphic designer"},{vi:"Nhà thiết kế đồ họa",en:"Graphic designer"},{vi:"Nhà thiết kế thương hiệu cấp cao",en:"Senior brand designer"},{vi:"Giám đốc nghệ thuật, giám đốc sáng tạo",en:"Art director, creative director"}],glossary:[{term:"CMYK",vi:"Hệ màu trừ dùng bốn mực cyan, magenta, vàng, đen trong in ấn.",en:"The subtractive colour model using cyan, magenta, yellow and black inks in printing."},{term:"Bleed",vi:"Phần hình nền kéo ra ngoài đường xén, thường 3 mm, để không lộ viền trắng khi cắt.",en:"Artwork extended beyond the trim line, usually 3 mm, so no white edge shows after cutting."},{term:"Effective PPI",vi:"Mật độ điểm ảnh thực tế của ảnh sau khi phóng hoặc thu trong dàn trang.",en:"The actual pixel density of an image after it is scaled in the layout."},{term:"Spot colour",vi:"Màu pha sẵn theo bảng màu chuẩn, in bằng mực riêng để giữ màu thương hiệu chính xác.",en:"A premixed colour from a standard guide, printed with its own ink to keep brand colour exact."},{term:"Brand guideline",vi:"Bộ quy chuẩn hướng dẫn sử dụng logo, màu, chữ và hình ảnh của thương hiệu.",en:"The rulebook for using the brand's logo, colours, typography and imagery."}],quiz:[{q:{vi:"Ảnh gốc 300 ppi được đặt ở tỷ lệ 150% trong dàn trang. Độ phân giải hiệu dụng là bao nhiêu?",en:"A 300 ppi image is placed at 150% scale in the layout. What is its effective resolution?"},options:{vi:["450 ppi","300 ppi","150 ppi","200 ppi"],en:["450 ppi","300 ppi","150 ppi","200 ppi"]},answer:3,explain:{vi:"300 / 1.5 = 200 ppi, thấp hơn ngưỡng 300 ppi cho in offset.",en:"300 / 1.5 = 200 ppi, below the 300 ppi offset threshold."}},{q:{vi:"Tràn lề phổ biến cho ấn phẩm in offset là bao nhiêu mỗi cạnh?",en:"What bleed is commonly used per side for offset print?"},options:{vi:["3 mm","0 mm","15 mm","1 mm vào trong"],en:["3 mm","0 mm","15 mm","1 mm inward"]},answer:0,explain:{vi:"Nhà in thường yêu cầu 3 mm tràn lề để bù sai số khi xén giấy.",en:"Printers usually ask for 3 mm bleed to absorb trimming tolerance."}},{q:{vi:"Khách đưa mẫu logo rất giống nhãn hiệu nổi tiếng và yêu cầu làm tương tự. Bạn làm gì?",en:"A client shows a logo very close to a famous trademark and asks for something similar. What do you do?"},options:{vi:["Làm theo vì khách chịu trách nhiệm","Đổi màu một chút là đủ","Giải thích rủi ro nhầm lẫn nhãn hiệu, đề xuất ý tưởng riêng và báo giám đốc sáng tạo","Bỏ dự án mà không giải thích"],en:["Comply because the client is liable","Change the colour slightly","Explain trademark confusion risk, propose an original idea and inform the creative director","Drop the project without explanation"]},answer:2,explain:{vi:"Logo gây nhầm lẫn có thể bị từ chối bảo hộ và bị khởi kiện; cần tư vấn và đề xuất phương án riêng.",en:"A confusing logo can be refused protection and sued; advise the client and offer an original route."}},{q:{vi:"Màu nhận diện cần chính xác tuyệt đối trên bao bì in. Nên dùng gì?",en:"A brand colour must be exact on printed packaging. What should you use?"},options:{vi:["Hệ màu RGB","Màu pha (spot colour)","Ảnh JPEG chất lượng cao","Mã màu web HEX"],en:["RGB colour mode","A spot colour","A high-quality JPEG","A web HEX code"]},answer:1,explain:{vi:"Màu pha in bằng mực riêng nên ổn định hơn pha trộn CMYK, phù hợp màu thương hiệu.",en:"Spot colours use dedicated ink and stay more consistent than CMYK builds, ideal for brand colours."}}]}},"KK-421":{scenario:{company:"Sóng Bạc Media",supervisor:{name:"Lý Quốc Trung",role:{vi:"Trưởng bộ phận Hậu kỳ",en:"Post-production Supervisor"}},ref_code:"TVC-0530",title:{vi:"Đúng tốc độ khung hình. Đúng độ lớn âm thanh. Đúng bản quyền.",en:"Right frame rate. Right loudness. Right licence."},brief:{vi:"Bạn hoàn thiện TVC 30 giây TVC-0530 để giao kênh truyền hình. Toàn bộ cảnh quay ở 25 fps nhưng bản dựng nháp đặt timeline 29.97 fps. Đặc tả của kênh (mô phỏng theo EBU R128): độ lớn tích hợp -23 LUFS, đỉnh thật tối đa -1 dBTP; bản mix hiện đo được -11 LUFS. Đối chiếu bảng thông số xuất nháp với đặc tả đã duyệt, sửa tốc độ khung hình và mức hiệu chỉnh độ lớn cần áp, rồi lập báo cáo có căn cứ.",en:"You are finishing 30-second spot TVC-0530 for delivery to a TV channel. All footage was shot at 25 fps but the draft edit uses a 29.97 fps timeline. The channel spec (modelled on EBU R128): integrated loudness -23 LUFS, true peak no higher than -1 dBTP; the current mix measures -11 LUFS. Compare the draft export sheet with the approved spec, correct the frame rate and the loudness gain to apply, then write an evidence-based report."},reference_title:{vi:"Đặc tả phát sóng & phiếu đo âm thanh đã duyệt · TVC-0530",en:"Approved broadcast spec & loudness sheet · TVC-0530"},fields:[{id:"FRAME_RATE",label:{vi:"Tốc độ khung hình timeline và file xuất (fps)",en:"Timeline and export frame rate (fps)"},initial:"29.97",expected:"25",choices:["23.976","25","29.97"],reference:"Đặc tả kỹ thuật phát sóng của kênh",hint:{vi:"Giữ đúng tốc độ khung hình gốc và đặc tả kênh vùng 50 Hz; chuyển 25 sang 29.97 gây giật hình, lệch timecode.",en:"Keep the native frame rate and the 50 Hz channel spec; converting 25 to 29.97 causes judder and timecode drift."}},{id:"GAIN_DB",label:{vi:"Mức hiệu chỉnh độ lớn cần áp (dB)",en:"Loudness gain to apply (dB)"},initial:"-3",expected:"-12",reference:"Phiếu đo độ lớn âm thanh",ref_value:{vi:"Bản mix đo -11 LUFS tích hợp; mục tiêu của kênh -23 LUFS",en:"Mix measures -11 LUFS integrated; channel target -23 LUFS"},hint:{vi:"Bản nháp dùng preset mạng xã hội -14 LUFS; bản phát sóng phải theo mục tiêu của kênh.",en:"The draft used a -14 LUFS social media preset; the broadcast master must follow the channel target."}}],sop32:{vi:"Mức hiệu chỉnh (dB) = độ lớn mục tiêu - độ lớn đo được (LUFS); giá trị âm là giảm. Sau hiệu chỉnh phải đo lại để độ lớn đạt mục tiêu và đỉnh thật không vượt -1 dBTP.",en:"Gain (dB) = target loudness - measured loudness (LUFS); a negative value means reduce. After applying it, re-measure so loudness hits the target and true peak stays at or below -1 dBTP."},context:{label:"BẢNG THÔNG SỐ XUẤT / TVC-0530",metrics:[{label:{vi:"Thời lượng",en:"Duration"},value:"30 s"},{label:{vi:"Độ lớn đo được",en:"Measured loudness"},value:"-11 LUFS"},{label:{vi:"Mục tiêu của kênh",en:"Channel target"},value:"-23 LUFS / -1 dBTP"}]},crisis:{vi:"Khách hàng nhắn: “Chèn bài hit đang thịnh hành làm nhạc nền đi, phát vài tuần thôi ai mà kiểm tra. Mua bản quyền thì không kịp lên sóng thứ Hai.”",en:"The client messages you: “Drop in that trending hit as the soundtrack, it only airs for a few weeks so nobody will check. Licensing it would miss Monday's air date.”"},options:{safe:{vi:"Không dùng nhạc chưa có giấy phép; báo Producer và khách bằng văn bản về rủi ro, đề xuất nhạc thư viện có giấy phép phát sóng hoặc nhạc sáng tác riêng và cập nhật lịch giao file.",en:"Use no unlicensed music; inform the producer and the client in writing about the risk, propose broadcast-licensed library music or an original score, and update the delivery schedule."},shortcut:{vi:"Chèn bài hit vào cho kịp lên sóng, nếu bị khiếu nại thì thay nhạc sau.",en:"Use the hit to make the air date and swap the music later if there is a claim."},wait:{vi:"Dừng dựng và chờ khách tự lo chuyện bản quyền nhạc.",en:"Stop editing and wait for the client to sort out the music rights."}},questions:{vi:["Vì sao phải dựng và xuất ở 25 fps, áp -12 dB thay vì -3 dB? Bạn kiểm chứng kết quả bằng chỉ số nào?","Dùng nhạc chưa có giấy phép trong TVC gây rủi ro gì cho khách, kênh và công ty? Bạn xử lý yêu cầu này ra sao?"],en:["Why must you edit and export at 25 fps and apply -12 dB instead of -3 dB? Which readings prove the result?","What risks does unlicensed music in a TV spot create for the client, the channel and the agency? How do you handle the request?"]},hints:{vi:["So cài đặt timeline nháp với đặc tả kênh và tốc độ khung hình của cảnh quay gốc.","Lấy độ lớn mục tiêu trừ độ lớn đo được theo SOP mục 3.2 và chú ý dấu âm.","Đọc lại SOP mục 4.2: âm nhạc, cảnh quay, hình ảnh đều phải có giấy phép phù hợp mục đích phát sóng."],en:["Compare the draft timeline settings with the channel spec and the native frame rate of the footage.","Subtract the measured loudness from the target as in SOP 3.2 and watch the sign.","Re-read SOP 4.2: music, footage and images all need licences that cover broadcast use."]}},learning:{summary:{vi:"Chuyên viên sản xuất video và hậu kỳ biến kịch bản thành sản phẩm hoàn chỉnh: lập kế hoạch quay, quản lý dữ liệu, dựng, chỉnh màu, xử lý âm thanh, đồ họa và xuất file đúng đặc tả từng kênh phát. Nghề tạo ra nội dung hình ảnh thuyết phục và chuẩn kỹ thuật, đòi hỏi cảm quan kể chuyện, thành thạo phần mềm, hiểu chuẩn phát sóng và tôn trọng bản quyền.",en:"A video producer and post-production editor turns a script into a finished piece: shoot planning, media management, editing, colour grading, audio, graphics and exports that meet each outlet's spec. The role delivers persuasive, technically sound content and requires storytelling sense, software mastery, knowledge of broadcast standards and respect for copyright."},responsibilities:{vi:["Phân tích kịch bản, lập danh sách cảnh quay, lịch quay và dự toán sản xuất.","Sao lưu, đặt tên và quản lý dữ liệu quay theo quy trình để không mất cảnh.","Dựng phim, chỉnh màu, làm đồ họa chuyển động và phụ đề theo định hướng đã duyệt.","Mix âm thanh, đo độ lớn và đỉnh thật theo đặc tả kênh phát.","Xuất nhiều định dạng, kiểm tra kỹ thuật (QC) và quản lý giấy phép nhạc, cảnh quay."],en:["Break down the script into a shot list, shooting schedule and production budget.","Back up, name and manage camera media so no footage is lost.","Edit, grade colour and build motion graphics and subtitles to the approved direction.","Mix audio and measure loudness and true peak to the outlet's spec.","Export multiple formats, run technical QC and manage music and footage licences."]},competencies:[{name:{vi:"Kể chuyện bằng hình ảnh",en:"Visual storytelling"},desc:{vi:"Chọn cảnh, nhịp dựng và âm thanh để truyền đúng thông điệp trong thời lượng giới hạn.",en:"Choose shots, pacing and sound to land the message within a tight duration."}},{name:{vi:"Kỹ thuật dựng & màu",en:"Editing & colour"},desc:{vi:"Làm chủ timeline, proxy, chỉnh màu sơ cấp, thứ cấp và quản lý không gian màu.",en:"Master timelines, proxies, primary and secondary grading and colour space management."}},{name:{vi:"Âm thanh hậu kỳ",en:"Audio post"},desc:{vi:"Làm sạch thoại, cân bằng nhạc, hiệu ứng và chuẩn hóa độ lớn theo LUFS.",en:"Clean dialogue, balance music and effects and normalise loudness in LUFS."}},{name:{vi:"Quản lý dữ liệu & quy trình",en:"Media management"},desc:{vi:"Sao lưu theo quy tắc 3-2-1, đặt tên nhất quán, theo dõi phiên bản và bàn giao gọn gàng.",en:"Follow the 3-2-1 backup rule, name consistently, track versions and deliver cleanly."}},{name:{vi:"Bản quyền & đạo đức",en:"Rights & ethics"},desc:{vi:"Kiểm tra giấy phép nhạc, cảnh quay, quyền hình ảnh cá nhân và không cắt ghép làm sai lệch sự thật.",en:"Check music, footage and likeness rights and never edit to distort the truth."}}],knowledge:{vi:["EBU R128: chuẩn hóa độ lớn -23 LUFS, đỉnh thật tối đa -1 dBTP cho phát sóng.","ITU-R BS.1770: thuật toán đo độ lớn (LUFS/LKFS) và đỉnh thật.","ITU-R BT.709 cho video HD và BT.2020 cho UHD: không gian màu và đặc tính truyền.","Tốc độ khung hình: 25/50 fps cho vùng điện 50 Hz, 23.976/29.97 fps cho vùng 60 Hz; quy đổi sai gây giật hình.","Luật Sở hữu trí tuệ số 50/2005/QH11 (đã sửa đổi, bổ sung): quyền tác giả, quyền liên quan với âm nhạc, bản ghi âm, tác phẩm điện ảnh.","Codec trung gian nén nội khung cho dựng và codec nén liên khung H.264, H.265 cho phát hành."],en:["EBU R128: loudness normalised to -23 LUFS with true peak no higher than -1 dBTP for broadcast.","ITU-R BS.1770: the algorithm for measuring loudness (LUFS/LKFS) and true peak.","ITU-R BT.709 for HD and BT.2020 for UHD: colour space and transfer characteristics.","Frame rates: 25/50 fps in 50 Hz regions, 23.976/29.97 fps in 60 Hz regions; wrong conversion causes judder.","Intellectual Property Law No. 50/2005/QH11 (as amended): copyright and related rights in music, sound recordings and films.","Intra-frame intermediate codecs for editing and inter-frame H.264 and H.265 codecs for distribution."]},tools:["Phần mềm dựng phim phi tuyến","Phần mềm chỉnh màu","Phần mềm âm thanh số và máy đo LUFS","Phần mềm đồ họa chuyển động","Màn hình tham chiếu đã hiệu chuẩn","Hệ thống lưu trữ RAID và sao lưu ngoài"],kpis:{vi:["Tỷ lệ file giao đạt QC kỹ thuật của kênh ngay lần đầu.","Tỷ lệ giao bản dựng, bản hoàn thiện đúng lịch duyệt.","Số vòng chỉnh sửa trung bình mỗi dự án.","Tỷ lệ nhạc, cảnh quay, font có giấy phép lưu hồ sơ (mục tiêu 100%)."],en:["Share of deliverables passing the channel's technical QC first time.","Share of rough cuts and masters delivered on the approved schedule.","Average revision rounds per project.","Share of music, footage and fonts with licences on file (target 100%)."]},day:[{time:"08:30",vi:"Kiểm tra bản sao lưu dữ liệu quay hôm qua ở hai nơi lưu trữ, tạo proxy.",en:"Verify yesterday's camera media backups in two locations and create proxies."},{time:"10:00",vi:"Dựng bản rough cut theo kịch bản phân cảnh, chọn nhạc thư viện có giấy phép.",en:"Cut the rough edit from the storyboard and pick licensed library music."},{time:"13:30",vi:"Chỉnh màu, làm đồ họa và phụ đề theo góp ý của khách.",en:"Grade colour and add graphics and subtitles from client notes."},{time:"15:30",vi:"Mix âm thanh, đo LUFS, đỉnh thật và chạy QC kỹ thuật.",en:"Mix audio, measure LUFS and true peak and run technical QC."},{time:"17:30",vi:"Xuất file theo đặc tả, gửi link duyệt và cập nhật nhật ký phiên bản.",en:"Export to spec, send the review link and update the version log."}],mistakes:{vi:["Đặt timeline sai tốc độ khung hình so với cảnh quay và đặc tả kênh, gây giật hình, lệch tiếng.","Chuẩn hóa âm thanh bằng preset mạng xã hội cho bản phát sóng, bị kênh trả file.","Dùng nhạc, cảnh quay lấy trên mạng không có giấy phép, khiến chiến dịch bị gỡ hoặc khiếu nại."],en:["Setting a timeline frame rate that differs from the footage and spec, causing judder and sync drift.","Normalising a broadcast master with a social media preset, so the channel rejects it.","Using music or footage from the web without a licence, getting the campaign taken down or claimed."]},career:[{vi:"Trợ lý dựng",en:"Assistant editor"},{vi:"Biên tập dựng phim",en:"Video editor"},{vi:"Biên tập dựng cấp cao, giám sát hậu kỳ",en:"Senior editor, post-production supervisor"},{vi:"Nhà sản xuất, trưởng bộ phận sản xuất",en:"Producer, head of production"}],glossary:[{term:"LUFS",vi:"Đơn vị đo độ lớn âm thanh cảm nhận theo ITU-R BS.1770, tính so với thang đầy đủ.",en:"Loudness Units relative to Full Scale, the perceived loudness unit defined in ITU-R BS.1770."},{term:"True peak",vi:"Mức đỉnh thật của tín hiệu sau tái tạo, đo bằng dBTP, dùng để tránh méo khi chuyển đổi.",en:"The reconstructed signal peak in dBTP, used to avoid clipping during conversion."},{term:"Frame rate",vi:"Số khung hình mỗi giây của video, ví dụ 25, 29.97 hoặc 50 fps.",en:"The number of video frames per second, such as 25, 29.97 or 50 fps."},{term:"Proxy",vi:"Bản sao độ phân giải thấp của cảnh quay để dựng nhanh, liên kết lại bản gốc khi xuất.",en:"A low-resolution copy of footage for fast editing, relinked to the originals at export."},{term:"QC",vi:"Kiểm tra chất lượng kỹ thuật hình, tiếng, định dạng trước khi giao file.",en:"Technical quality control of picture, sound and format before delivery."}],quiz:[{q:{vi:"Bản mix đo được -16 LUFS, kênh yêu cầu -23 LUFS. Cần áp mức hiệu chỉnh nào?",en:"A mix measures -16 LUFS and the channel requires -23 LUFS. What gain should you apply?"},options:{vi:["+7 dB","-7 dB","-23 dB","+16 dB"],en:["+7 dB","-7 dB","-23 dB","+16 dB"]},answer:1,explain:{vi:"-23 - (-16) = -7 dB; cần giảm 7 dB rồi đo lại đỉnh thật.",en:"-23 - (-16) = -7 dB; reduce by 7 dB, then re-check true peak."}},{q:{vi:"Theo EBU R128, mức đỉnh thật tối đa thường áp dụng cho phát sóng là bao nhiêu?",en:"Under EBU R128, what is the usual maximum true peak for broadcast?"},options:{vi:["0 dBTP","-6 dBTP","+1 dBTP","-1 dBTP"],en:["0 dBTP","-6 dBTP","+1 dBTP","-1 dBTP"]},answer:3,explain:{vi:"EBU R128 đặt đỉnh thật tối đa -1 dBTP để còn khoảng an toàn khi mã hóa.",en:"EBU R128 sets a -1 dBTP maximum true peak to leave headroom for encoding."}},{q:{vi:"Khách muốn dùng một bài hát nổi tiếng chưa có giấy phép cho TVC. Bạn làm gì?",en:"The client wants a famous song with no licence in the TV spot. What do you do?"},options:{vi:["Từ chối, đề xuất nhạc có giấy phép và báo Producer","Chỉ dùng 15 giây là không sao","Đổi tốc độ bài hát để tránh bị phát hiện","Dùng rồi ghi tên ca sĩ là đủ"],en:["Refuse, propose licensed music and inform the producer","Using only 15 seconds is fine","Change the tempo to avoid detection","Use it and credit the singer"]},answer:0,explain:{vi:"Mọi đoạn nhạc dùng cho quảng cáo đều cần giấy phép; ghi tên hay cắt ngắn không thay được giấy phép.",en:"Any music used in advertising needs a licence; credits or short clips do not replace it."}},{q:{vi:"Cảnh quay 25 fps, kênh vùng 50 Hz yêu cầu 25 fps. Cách làm đúng là gì?",en:"Footage is 25 fps and a 50 Hz channel requires 25 fps. What is correct?"},options:{vi:["Đặt timeline 29.97 fps","Đặt 23.976 fps cho chất điện ảnh","Đặt timeline và xuất ở 25 fps","Đặt 60 fps cho mượt"],en:["Use a 29.97 fps timeline","Use 23.976 fps for a film look","Edit and export at 25 fps","Use 60 fps for smoothness"]},answer:2,explain:{vi:"Giữ tốc độ khung hình gốc và đúng đặc tả kênh tránh giật hình, lệch tiếng và bị trả file.",en:"Keeping the native rate that matches the spec avoids judder, sync drift and rejection."}}]}},"KK-422":{scenario:{company:"Ngân Hà News",supervisor:{name:"Châu Mỹ Linh",role:{vi:"Thư ký Tòa soạn",en:"Managing Editor"}},ref_code:"BV-1407",title:{vi:"Tách bạch quảng cáo. Kiểm chứng từng con số.",en:"Label sponsored content. Verify every number."},brief:{vi:"Bạn biên tập bài BV-1407 do phòng kinh doanh chuyển sang, kèm hợp đồng tài trợ có thu phí của doanh nghiệp bất động sản Đông Lâm Land. Bài viết “doanh thu tăng 21.6%”, trong khi báo cáo tài chính đã kiểm toán ghi doanh thu năm 2024 là 840 tỷ đồng và năm 2025 là 1.071 tỷ đồng. Đối chiếu bản nháp trên CMS với hồ sơ đã duyệt, sửa nhãn loại nội dung và mức tăng trưởng doanh thu, rồi lập báo cáo có căn cứ.",en:"You are editing article BV-1407 sent over by the sales team with a paid sponsorship contract from property developer Dong Lam Land. The article says “revenue grew 21.6%”, while the audited financial statements show revenue of VND 840 billion in 2024 and VND 1,071 billion in 2025. Compare the CMS draft with the approved file, correct the content type label and the revenue growth, then write an evidence-based report."},reference_title:{vi:"Sổ tay biên tập & báo cáo tài chính đã kiểm toán · BV-1407",en:"Editorial handbook & audited financial statements · BV-1407"},fields:[{id:"CONTENT_TAG",label:{vi:"Nhãn loại nội dung",en:"Content type label"},initial:"NEWS",expected:"SPONSORED",choices:["NEWS","SPONSORED","OPINION"],reference:"Sổ tay quy chuẩn biên tập",hint:{vi:"Bài có hợp đồng tài trợ trả phí là thông tin quảng cáo, phải gắn nhãn và tách bạch với tin báo chí.",en:"An article under a paid sponsorship contract is advertising and must be labelled and kept separate from news."}},{id:"GROWTH_PCT",label:{vi:"Mức tăng trưởng doanh thu (%)",en:"Revenue growth (%)"},initial:"21.6",expected:"27.5",reference:"Báo cáo tài chính đã kiểm toán",ref_value:{vi:"Doanh thu 2024: 840 tỷ đồng; doanh thu 2025: 1.071 tỷ đồng",en:"Revenue 2024: VND 840 billion; revenue 2025: VND 1,071 billion"},hint:{vi:"Bản nháp chia phần chênh lệch cho doanh thu năm sau; tăng trưởng phải tính trên năm gốc.",en:"The draft divided the difference by the later year; growth must be measured against the base year."}}],sop32:{vi:"Mức tăng trưởng (%) = (giá trị kỳ này - giá trị kỳ gốc) / giá trị kỳ gốc x 100, làm tròn 1 chữ số thập phân; mọi con số phải dẫn nguồn đã kiểm chứng.",en:"Growth (%) = (current value - base value) / base value x 100, rounded to 1 decimal place; every figure must cite a verified source."},context:{label:"CMS / BV-1407",metrics:[{label:{vi:"Nguồn bài",en:"Article source"},value:"Sales / B2B"},{label:{vi:"Hợp đồng tài trợ",en:"Sponsorship contract"},value:"SP-2025-118"},{label:{vi:"Doanh thu 2024 / 2025 (tỷ VND)",en:"Revenue 2024 / 2025 (VND bn)"},value:"840 / 1,071"}]},crisis:{vi:"Phòng kinh doanh nhắn: “Đối tác trả thêm 20% nếu bỏ nhãn ‘Nội dung tài trợ’ và đăng ở mục thời sự, giữ nguyên con số họ đưa. Tổng biên tập đi công tác, cứ đăng trước 11 giờ.”",en:"Sales messages you: “The partner pays 20% more if we drop the ‘Sponsored’ label and run it in the news section with their numbers unchanged. The editor-in-chief is travelling, just publish before 11.”"},options:{safe:{vi:"Giữ nhãn nội dung tài trợ, sửa số liệu theo báo cáo đã kiểm toán; báo Thư ký Tòa soạn và Tổng biên tập bằng văn bản, đề xuất đối tác duyệt lại bản có nhãn đúng quy định.",en:"Keep the sponsored label and correct the figures from the audited statements; inform the managing editor and editor-in-chief in writing and ask the partner to approve the properly labelled version."},shortcut:{vi:"Bỏ nhãn tài trợ và đăng như tin thời sự để giữ hợp đồng, có phản ánh thì sửa sau.",en:"Drop the label and run it as news to keep the deal, fix it later if readers complain."},wait:{vi:"Treo bài, không trả lời phòng kinh doanh cho đến khi Tổng biên tập về.",en:"Park the article and ignore Sales until the editor-in-chief returns."}},questions:{vi:["Vì sao bài phải gắn nhãn SPONSORED và mức tăng đúng là 27.5%? Bạn dẫn số liệu nào trong báo cáo đã kiểm toán?","Đăng nội dung trả phí như tin báo chí gây rủi ro gì cho tòa soạn và độc giả? Bạn xử lý áp lực từ phòng kinh doanh thế nào?"],en:["Why must the article carry the SPONSORED label, and why is growth 27.5%? Which audited figures do you cite?","What risks does running paid content as news create for the newsroom and readers? How do you handle the pressure from Sales?"]},hints:{vi:["So nguồn gốc bài và hợp đồng đi kèm với quy chuẩn phân loại nội dung trong sổ tay biên tập.","Lấy phần chênh lệch chia cho năm gốc theo SOP mục 3.2, không chia cho năm sau.","Đọc lại SOP mục 4.2: quảng cáo phải tách bạch với thông tin báo chí; yêu cầu bỏ nhãn phải báo lãnh đạo tòa soạn."],en:["Compare the article's origin and contract with the content classification rules in the editorial handbook.","Divide the difference by the base year as in SOP 3.2, not by the later year.","Re-read SOP 4.2: advertising must be separated from journalism; any request to drop a label goes to newsroom leaders."]}},learning:{summary:{vi:"Biên tập viên nội dung số và báo điện tử khai thác, biên tập, kiểm chứng và xuất bản tin bài đa phương tiện trên hệ quản trị nội dung, tối ưu tiêu đề, SEO và phân phối trên mạng xã hội. Nghề giữ uy tín tòa soạn bằng thông tin chính xác, cân bằng, kịp thời, đòi hỏi kỹ năng ngôn ngữ, kiểm chứng số liệu, hiểu pháp luật báo chí và đạo đức nghề nghiệp.",en:"A digital content editor and online journalist sources, edits, verifies and publishes multimedia stories on the content management system, optimising headlines, SEO and social distribution. The role protects the newsroom's credibility with accurate, balanced and timely information, and requires language skills, data verification, knowledge of press law and professional ethics."},responsibilities:{vi:["Lên đề tài, phân công phóng viên và theo dõi tiến độ tin bài trong ngày.","Biên tập văn bản, tiêu đề, sapo, ảnh, video theo quy chuẩn và văn phong tòa soạn.","Kiểm chứng nguồn tin, số liệu, trích dẫn và quyền sử dụng hình ảnh trước khi xuất bản.","Phân loại và gắn nhãn nội dung: tin, bình luận, nội dung tài trợ theo quy định.","Tối ưu SEO, phân phối mạng xã hội, theo dõi lượt đọc và xử lý cải chính khi cần."],en:["Plan stories, assign reporters and track the day's output.","Edit copy, headlines, standfirsts, photos and video to the house style.","Verify sources, figures, quotes and image rights before publishing.","Classify and label content as news, opinion or sponsored as required.","Optimise SEO, distribute on social media, track readership and issue corrections when needed."]},competencies:[{name:{vi:"Biên tập ngôn ngữ",en:"Copy editing"},desc:{vi:"Viết gọn, chính xác, đúng chính tả, văn phong và cấu trúc tin bài.",en:"Write tight, accurate copy with correct spelling, style and story structure."}},{name:{vi:"Kiểm chứng thông tin",en:"Fact-checking"},desc:{vi:"Truy nguồn gốc, đối chiếu số liệu, ảnh, trích dẫn với tài liệu gốc.",en:"Trace origins and check figures, photos and quotes against primary sources."}},{name:{vi:"Tư duy số liệu",en:"Data literacy"},desc:{vi:"Tính đúng phần trăm, điểm phần trăm, bình quân và tránh so sánh sai cơ sở.",en:"Compute percentages, percentage points and averages correctly and avoid wrong bases."}},{name:{vi:"Biên tập đa nền tảng",en:"Multiplatform editing"},desc:{vi:"Tối ưu tiêu đề, SEO, định dạng cho website, mạng xã hội và thông báo đẩy.",en:"Optimise headlines, SEO and formats for web, social media and push alerts."}},{name:{vi:"Pháp luật & đạo đức báo chí",en:"Media law & ethics"},desc:{vi:"Tách bạch quảng cáo, bảo vệ nguồn tin, tôn trọng quyền riêng tư và cải chính kịp thời.",en:"Separate advertising, protect sources, respect privacy and correct errors promptly."}}],knowledge:{vi:["Luật Báo chí và văn bản hướng dẫn: quyền, nghĩa vụ của cơ quan báo chí, nhà báo, trách nhiệm cải chính, xin lỗi.","Pháp luật về quảng cáo: thông tin quảng cáo trên báo phải được phân biệt rõ với thông tin báo chí.","Quy định về đạo đức nghề nghiệp của người làm báo Việt Nam do Hội Nhà báo Việt Nam ban hành.","Luật Sở hữu trí tuệ: quyền tác giả với ảnh, video, bài viết khi trích dẫn, đăng lại.","Kỹ thuật kiểm chứng số: tra ngược ảnh, kiểm tra siêu dữ liệu, xác minh tài khoản nguồn.","Nguyên tắc tin tức: chính xác, khách quan, cân bằng, kim tự tháp ngược, 5W1H."],en:["The Press Law and its guidance: rights and duties of media outlets and journalists, and the duty to correct and apologise.","Advertising law: advertising in newspapers must be clearly distinguished from journalistic content.","The professional ethics rules for Vietnamese journalists issued by the Vietnam Journalists Association.","Intellectual property law: copyright in photos, video and articles when quoting or republishing.","Digital verification: reverse image search, metadata checks and source account verification.","News principles: accuracy, objectivity, balance, the inverted pyramid and the 5W1H."]},tools:["Hệ quản trị nội dung (CMS) tòa soạn","Công cụ kiểm tra chính tả tiếng Việt","Công cụ tra ngược ảnh, siêu dữ liệu","Công cụ phân tích lượt đọc thời gian thực","Công cụ gợi ý SEO và từ khóa"],kpis:{vi:["Số bài sai sự thật phải cải chính trên tổng số bài xuất bản (mục tiêu bằng 0).","Tỷ lệ bài xuất bản đúng khung giờ và đúng quy chuẩn gắn nhãn.","Thời gian đọc trung bình và tỷ lệ độc giả quay lại.","Tỷ lệ nhấp tiêu đề so với mặt bằng chuyên mục."],en:["Corrections for factual errors per articles published (target zero).","Share of articles published on schedule and correctly labelled.","Average reading time and returning reader rate.","Headline click-through rate versus the section average."]},day:[{time:"07:30",vi:"Họp giao ban sáng, chốt đề tài nóng và phân công phóng viên.",en:"Morning news meeting to lock hot topics and assign reporters."},{time:"09:00",vi:"Biên tập tin bài buổi sáng, kiểm chứng số liệu, ảnh và trích dẫn.",en:"Edit morning stories and verify figures, photos and quotes."},{time:"11:00",vi:"Duyệt nội dung tài trợ: kiểm tra hợp đồng, nhãn và tính chính xác.",en:"Review sponsored content: contract, label and accuracy."},{time:"14:00",vi:"Tối ưu tiêu đề, SEO và lên lịch phân phối mạng xã hội.",en:"Optimise headlines and SEO and schedule social distribution."},{time:"16:30",vi:"Theo dõi lượt đọc, xử lý phản hồi độc giả và đề xuất đề tài ngày mai.",en:"Track readership, handle reader feedback and pitch tomorrow's stories."}],mistakes:{vi:["Tính phần trăm tăng trưởng trên sai kỳ gốc hoặc nhầm phần trăm với điểm phần trăm.","Đăng nội dung trả phí không gắn nhãn, khiến độc giả tưởng là tin báo chí.","Chạy theo tốc độ mà đăng tin chưa kiểm chứng hoặc dùng ảnh không rõ nguồn."],en:["Computing growth on the wrong base year or confusing percent with percentage points.","Publishing paid content without a label so readers mistake it for news.","Rushing out unverified stories or using photos of unknown origin."]},career:[{vi:"Phóng viên, cộng tác viên nội dung số",en:"Reporter, digital content contributor"},{vi:"Biên tập viên",en:"Editor"},{vi:"Biên tập viên cao cấp, trưởng ban",en:"Senior editor, section head"},{vi:"Thư ký tòa soạn, phó tổng biên tập",en:"Managing editor, deputy editor-in-chief"}],glossary:[{term:"Sapo",vi:"Đoạn dẫn ngắn dưới tiêu đề, tóm tắt ý chính của bài.",en:"The short standfirst under the headline that sums up the story."},{term:"Sponsored content",vi:"Nội dung do tổ chức trả phí, phải gắn nhãn để độc giả phân biệt với tin báo chí.",en:"Content paid for by an organisation, labelled so readers can tell it apart from news."},{term:"Fact-checking",vi:"Quy trình kiểm chứng dữ kiện, số liệu, trích dẫn trước khi xuất bản.",en:"The process of verifying facts, figures and quotes before publication."},{term:"Percentage point",vi:"Mức chênh giữa hai tỷ lệ phần trăm, ví dụ từ 4% lên 6% là tăng 2 điểm phần trăm.",en:"The difference between two percentages, e.g. from 4% to 6% is a rise of 2 percentage points."},{term:"Correction",vi:"Thông tin cải chính đăng lại khi tin bài đã xuất bản có nội dung không chính xác.",en:"A published notice that fixes inaccurate information in an article already released."}],quiz:[{q:{vi:"Tỷ lệ thất nghiệp giả định tăng từ 4% lên 6%. Cách viết nào đúng?",en:"A hypothetical unemployment rate rises from 4% to 6%. Which wording is correct?"},options:{vi:["Tăng 2%","Tăng 2 điểm phần trăm, tức tăng 50%","Tăng 6%","Tăng 33%"],en:["Up 2%","Up 2 percentage points, a 50% rise","Up 6%","Up 33%"]},answer:1,explain:{vi:"Chênh lệch là 2 điểm phần trăm; so với kỳ gốc 4% thì mức tăng tương đối là 2 / 4 = 50%.",en:"The gap is 2 percentage points; relative to the 4% base, the increase is 2 / 4 = 50%."}},{q:{vi:"Đối tác trả thêm tiền để bỏ nhãn tài trợ. Bạn làm gì?",en:"A partner pays extra to remove the sponsored label. What do you do?"},options:{vi:["Bỏ nhãn vì có lợi cho tòa soạn","Bỏ nhãn, thêm chữ nhỏ cuối bài","Đăng ở chuyên mục thời sự","Giữ nhãn, báo lãnh đạo tòa soạn và từ chối điều khoản sai"],en:["Remove it, it helps revenue","Remove it and add small print at the end","Run it in the news section","Keep the label, inform newsroom leaders and reject the improper term"]},answer:3,explain:{vi:"Nội dung trả phí phải được nhận biết rõ; che giấu là lừa dối độc giả và vi phạm quy định.",en:"Paid content must be clearly identifiable; hiding it deceives readers and breaks the rules."}},{q:{vi:"Cấu trúc kim tự tháp ngược trong viết tin nghĩa là gì?",en:"What does the inverted pyramid mean in news writing?"},options:{vi:["Thông tin quan trọng nhất ở đầu bài","Kết luận đặt ở cuối bài","Kể theo trình tự thời gian","Mở đầu bằng một trích dẫn"],en:["The most important facts come first","The conclusion goes at the end","Events are told in time order","The story opens with a quote"]},answer:0,explain:{vi:"Tin quan trọng nhất đặt lên đầu để độc giả nắm ngay và bài có thể cắt từ cuối.",en:"The key facts lead so readers get them at once and the story can be trimmed from the bottom."}},{q:{vi:"Một bức ảnh đang lan truyền chưa rõ nguồn. Bước nào nên làm trước tiên?",en:"A viral photo has no clear source. What should you do first?"},options:{vi:["Đăng kèm chú thích ảnh mạng","Đăng trước, sai thì gỡ","Tra ngược ảnh, kiểm tra siêu dữ liệu và liên hệ người chụp","Cắt bỏ logo trong ảnh"],en:["Publish it credited to the internet","Publish first and remove if wrong","Reverse-search it, check metadata and contact the photographer","Crop out the watermark"]},answer:2,explain:{vi:"Phải xác minh nguồn gốc, bối cảnh và quyền sử dụng trước khi đăng.",en:"Verify origin, context and usage rights before publishing."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(5)})(window.KKR);
